const fmt=d=>d?new Intl.DateTimeFormat('ko-KR',{year:'numeric',month:'short',day:'numeric'}).format(new Date(d)):'미정';
const labels={WEEK_1:'1주 체크',WEEK_4_URINE:'4주 소변 건강검사',ARCHIVED:'보관',REVOKED:'회수',UNVERIFIED:'미인증',ACTIVE:'활성',PRE_MEMBER:'승인 대기',INVITED:'초대됨',VERIFICATION_PENDING:'확인 중',SUSPENDED:'정지',WITHDRAWN:'거절·탈퇴',ENDED:'소속 종료',DRAFT:'준비 중',OPEN:'모집 중',SUBMITTED:'접수',APPROVED:'승인',STARTED:'참여 중',COMPLETED:'완료',CONNECTED:'연결 완료',SELECTED:'연결 가능',REVIEWING:'검토 중',PENDING:'대기',VERIFIED:'인증 완료',OWNER:'운영자',MEMBER:'구성원',OWNER_VET:'원장',DIRECTOR:'원장',VETERINARIAN:'수의사',VET:'수의사',STAFF:'직원',STUDENT:'수의대생',ENTERPRISE_USER:'기업회원',GUARDIAN:'보호자',ADMIN:'관리자',GENERAL:'일반 지원',PRODUCT:'제품·샘플',DEMO:'장비 데모',SPONSORSHIP:'협찬·스폰서십',MANAGEMENT:'경영·운영 지원',DOG:'강아지',CAT:'고양이',OTHER:'기타',MALE:'수컷',FEMALE:'암컷',UNKNOWN:'모름',PRIMARY:'주 보호자',SCHEDULED:'예정',REPORTED:'결과 확인'};
