function readSession(){try{return JSON.parse(sessionStorage.getItem('dp_session')||'null')}catch{return null}}
class ClientError extends Error{constructor(status,code,message){super(message);this.status=status;this.code=code}}
async function auth(path,body){const r=await fetch(BASE+'/auth/v1/'+path,{method:'POST',headers:{apikey:KEY,'content-type':'application/json'},body:JSON.stringify(body)});const j=await r.json();if(!r.ok)throw new ClientError(r.status,j.error||'',j.msg||j.error_description||j.message||'인증에 실패했습니다.');return j}
async function api(path,{method='GET',body,idempotency}={}){const r=await fetch(API+path,{method,headers:{authorization:'Bearer '+state.session?.access_token,apikey:KEY,'content-type':'application/json','x-request-id':crypto.randomUUID(),...(idempotency?{'x-idempotency-key':idempotency}:{})},body:body?JSON.stringify(body):undefined});let j={};try{j=await r.json()}catch{}if(!r.ok){if(r.status===401)expireSession();throw new ClientError(r.status,j.error?.code||'',j.error?.message||'요청을 처리하지 못했습니다.')}return j.data}
function expireSession(){sessionStorage.removeItem('dp_session');state.session=null;state.me=null;state.overview=null;state.sessionExpired=true}
function setMsg(m,ok=false){const e=$('#msg');if(e){e.className=ok?'notice success':'notice error';e.textContent=m}}
function badge(value){return `<span class="badge badge-${esc(String(value||'').toLowerCase())}">${esc(label(value))}</span>`}
function empty(title,body='새로운 내용이 생기면 이곳에 표시됩니다.'){return `<div class="empty"><div class="empty-icon">＋</div><strong>${esc(title)}</strong><p>${esc(body)}</p></div>`}
function loading(){return `<div class="loading"><span></span><p>정보를 불러오는 중입니다.</p></div>`}
function errorView(x){const denied=x?.status===403;return `<div class="state-panel ${denied?'deny':'error'}"><strong>${denied?'접근 권한이 없습니다':'정보를 불러오지 못했습니다'}</strong><p>${esc(denied?'현재 역할과 소속으로 허용되지 않은 기능입니다.':x?.message||'잠시 후 다시 시도해 주세요.')}</p><button class="secondary" data-retry>다시 시도</button></div>`}
async function login(e){e.preventDefault();setMsg('');try{const d=await auth('token?grant_type=password',{email:$('#email').value,password:$('#password').value});state.session=d;state.sessionExpired=false;sessionStorage.setItem('dp_session',JSON.stringify(d));await load()}catch(x){setMsg(x.message)}}
async function signup(e){e.preventDefault();try{const d=await auth('signup',{email:$('#email').value,password:$('#password').value,data:{display_name:$('#name').value}});if(!d.access_token)throw new Error('이메일 확인 후 로그인해 주세요.');state.session=d;sessionStorage.setItem('dp_session',JSON.stringify(d));const b=await api('/profile/bootstrap',{method:'POST',body:{displayName:$('#name').value,role:$('#role').value}});state.invite=b.invitationToken||'';sessionStorage.setItem('dp_invite',state.invite);await load()}catch(x){setMsg(x.message)}}
async function activate(){try{await api('/activation',{method:'POST',body:{invitationToken:state.invite},idempotency:'activate:'+state.session.user.id});await load()}catch(x){setMsg(x.message)}}
async function logout(){if(params.get('portal')==='enterprise'){enterpriseEntryPending=true;enterpriseEntryDenied=false;}if(params.get('portal')==='student'){studentEntryPending=true;studentEntryDenied=false;}guardianInput={petId:'',inquiry:'',category:'health',check:{}};state.guardianCare=null;state.selectedPet='';if(params.get('portal')==='guardian'){guardianEntryPending=true;guardianEntryDenied=false;}guardianPetGeneration++;if(params.get('portal')==='vet'){vetEntryPending=true;vetEntryDenied=false;}try{await auth('logout',{})}catch{}sessionStorage.clear();state.session=null;state.me=null;state.overview=null;state.enterprise=null;state.guardian=null;state.admin=null;state.sessionExpired=false;state.page='home';render()}
async function load(){
 guardianPetGeneration++;
 const enterpriseEntryLoad=enterpriseEntryPending;
 const vetEntryLoad=vetEntryPending;
 const hospitalEntryLoad=hospitalEntryPending;
 const generation=++state.loadGeneration;state.busy=true;state.detail=null;state.overview=null;state.enterprise=null;state.guardian=null;state.guardianCare=null;state.admin=null;state.group=null;state.scores=null;render();
 try{const me=await api('/me');if(generation!==state.loadGeneration)return;state.me=me;
 if(enterpriseEntryPending&&!(me?.state==='ACTIVE'&&me.roles?.includes('ENTERPRISE_USER')&&me.permissions?.includes('ROOM_READ')&&me.rooms?.some(r=>r.room_type==='ENTERPRISE_PRIVATE'&&r.status==='ACTIVE'&&me.affiliations?.some(a=>a.enterprise_id===r.enterprise_id&&a.status==='ACTIVE'&&a.verification_status==='VERIFIED')))){enterpriseEntryDenied=true;state.mySpace=null;state.busy=false;render();return}
 if(studentEntryPending&&(me?.state!=='ACTIVE'||!me.roles?.includes('STUDENT'))){studentEntryDenied=true;state.mySpace=null;state.busy=false;render();return}
 if(guardianEntryPending&&(me?.state!=='ACTIVE'||!me.roles?.includes('GUARDIAN'))){guardianEntryDenied=true;state.mySpace=null;state.busy=false;render();return}
 if(vetEntryPending){vetEntryDenied=!(me?.state==='ACTIVE'&&me.roles?.includes('VET')&&me.rooms?.some(r=>r.room_type==='VET_PRIVATE'&&r.status==='ACTIVE'));if(vetEntryDenied){state.busy=false;state.mySpace=null;render();return}}
 if(hospitalEntryPending){
   const rooms=me?.rooms||[],affiliations=me?.affiliations||[];
   const allowed=me?.state==='ACTIVE'&&rooms.some(r=>r.room_type==='HOSPITAL_PRIVATE'&&r.status==='ACTIVE'&&affiliations.some(a=>a.hospital_id===r.hospital_id&&a.status==='ACTIVE'&&a.verification_status==='VERIFIED'));
   hospitalEntryDenied=!allowed;
   if(!allowed){state.mySpace=null;state.busy=false;render();return}
 }
 if(me?.state==='ACTIVE'){
   if(me.roles.some(r=>['GUARDIAN','STUDENT'].includes(r)&&!me.rooms?.some(x=>x.room_type===r+'_PRIVATE'))){await api('/commands',{method:'POST',idempotency:'personal-spaces:'+me.id+':'+me.roles.slice().sort().join('-'),body:{commandType:'ENSURE_PERSONAL_SPACES',payload:{}}});if(generation!==state.loadGeneration)return;const refreshed=await api('/me');if(generation!==state.loadGeneration)return;state.me=refreshed}
   if(guardianEntryPending&&(!state.me.roles?.includes('GUARDIAN')||!state.me.rooms?.some(r=>r.room_type==='GUARDIAN_PRIVATE'&&r.status==='ACTIVE'))){guardianEntryDenied=true;state.busy=false;render();return}
   const space=await api('/my-space');if(generation!==state.loadGeneration)return;state.mySpace=space;
   const contexts=availableContexts();
   if(enterpriseEntryPending){const c=contexts.find(c=>c.kind==='enterprise'&&c.room.status==='ACTIVE');if(!c){enterpriseEntryDenied=true;state.busy=false;render();return}state.context=c.key;enterpriseEntryPending=false;enterpriseEntryDenied=false;}
   if(vetEntryPending){const vet=contexts.find(c=>c.kind==='vet'&&c.room.status==='ACTIVE');if(!vet){vetEntryDenied=true;state.busy=false;render();return}state.context=vet.key;vetEntryPending=false;vetEntryDenied=false;}
   if(hospitalEntryPending){
     const hospitals=contexts.filter(c=>c.kind==='hospital'&&c.room.status==='ACTIVE'&&state.me.affiliations?.some(a=>a.hospital_id===c.room.hospital_id&&a.status==='ACTIVE'&&a.verification_status==='VERIFIED'));
     const remembered=sessionStorage.getItem('dp_context');
     const hospital=hospitals.find(c=>c.key===remembered)||hospitals[0];
     if(!hospital){hospitalEntryDenied=true;state.busy=false;render();return}
     state.context=hospital.key;hospitalEntryPending=false;hospitalEntryDenied=false;
   }
   if(studentEntryPending){const c=contexts.find(c=>c.kind==='student'&&c.room.status==='ACTIVE');if(!c||!studentHasOwnRoom()){studentEntryDenied=true;state.busy=false;render();return}state.context=c.key;studentEntryPending=false;studentEntryDenied=false;}
   if(guardianEntryPending){const c=contexts.find(c=>c.kind==='guardian'&&c.room.status==='ACTIVE');if(!c){guardianEntryDenied=true;state.busy=false;render();return}state.context=c.key;guardianEntryPending=false;guardianEntryDenied=false;}
   if(!contexts.some(c=>c.key===state.context))state.context=contexts.find(c=>c.key==='hospital')?.key||contexts.find(c=>c.key==='enterprise')?.key||contexts.find(c=>c.key==='guardian')?.key||contexts[0]?.key||'account';
   sessionStorage.setItem('dp_context',state.context);const room=currentRoom(),kind=contextKind();
   const path=kind==='admin'?'/admin/dashboard':kind==='enterprise'?'/enterprises/'+room.enterprise_id+'/overview':kind==='guardian'?'/guardian/overview':kind==='group'?'/groups/'+room.group_id:'/overview'+(room?.hospital_id?'?hospitalId='+room.hospital_id:room?'?roomId='+room.id:'');
   const [contextData,scores]=await Promise.all([api(path),kind==='admin'?Promise.resolve(null):api('/scores'+(room?'?roomId='+room.id:''))]);
   const field={admin:'admin',enterprise:'enterprise',guardian:'guardian',group:'group'}[kind]||'overview';const data={[field]:contextData,scores};
   if(generation!==state.loadGeneration)return;Object.assign(state,data);
   if(state.guardian?.pets?.length&&!state.guardian.pets.some(p=>p.id===state.selectedPet)){state.selectedPet=state.guardian.pets[0].id;sessionStorage.setItem('dp_pet',state.selectedPet)}
   if(kind==='guardian'){await loadGuardianExposure();if(generation!==state.loadGeneration)return;const pet=selectedGuardianPet();state.guardianCareError=false;if(pet){try{const care=await api('/guardian/pets/'+pet.id);if(generation!==state.loadGeneration)return;state.guardianCare=care.pet?.id===pet.id?care:null}catch(x){if(generation!==state.loadGeneration)return;if(x.status===401)throw x;state.guardianCare=null;state.guardianCareError=true;}}}
 }else state.mySpace=null;
 if(generation===state.loadGeneration){state.busy=false;render()}
 }catch(x){if(generation!==state.loadGeneration)return;state.busy=false;if(enterpriseEntryLoad&&x.status===403){enterpriseEntryPending=true;enterpriseEntryDenied=true;state.context='enterprise';state.mySpace=null;return render()}if(vetEntryLoad&&x.status===403){vetEntryPending=true;vetEntryDenied=true;state.context='vet';state.mySpace=null;return render()}if(hospitalEntryLoad&&x.status===403){hospitalEntryPending=true;hospitalEntryDenied=true;state.context='hospital';state.mySpace=null;return render()}if(!state.session)return render();render(errorView(x))}
}
async function refreshOverview(){await load()}
async function refreshMySpace(){state.mySpace=await api('/my-space');state.detail=null;render()}
function authView(){if(params.get('portal')==='enterprise')return enterpriseAuthView();if(params.get('portal')==='student')return studentAuthView();if(params.get('portal')==='guardian')return guardianAuthView();if(params.get('portal')==='vet')return vetAuthView();if(params.get('portal')==='hospital')return hospitalAuthView();if(params.get('portal')==='admin')return adminAuthView();return `<div class="auth-wrap"><div class="auth-card"><div class="logo-mark">D</div><div class="brand auth-brand">DoctorPet</div><h1>병원 네트워크 로그인</h1><p class="muted">동물병원 캠페인과 무료지원 서비스를 이용하세요.</p>${state.sessionExpired?'<div class="notice error">로그인이 만료되었습니다. 다시 로그인해 주세요.</div>':''}<div id="msg"></div><form id="login"><label>이메일<input id="email" type="email" autocomplete="username" placeholder="이메일 주소" required></label><label>비밀번호<input id="password" type="password" autocomplete="current-password" minlength="10" placeholder="비밀번호" required></label><button class="primary full-button" type="submit">로그인</button></form><details class="dev-signup"><summary>DEV 테스트 회원가입</summary><form id="signup"><input id="name" placeholder="이름" required><select id="role"><option>VET</option><option>STAFF</option><option>STUDENT</option><option>ENTERPRISE_USER</option><option>GUARDIAN</option></select><button class="secondary" type="submit">가입하기</button></form></details></div></div>`}
const hospitalNav=[['home','홈','⌂'],['campaign','캠페인','▣'],['support','무료지원','♡'],['space','내 공간','⌘'],['more','더보기','•••'],['hospital','내 병원','✚'],['matching','기업 매칭','⇄'],['account','내 계정','○']];
const enterpriseNav=[['home','홈','⌂'],['enterprise','기업방','▦'],['campaign','캠페인','▣'],['matching','병원 매칭','⇄'],['partnership','제휴·광고','◇'],['space','내 공간','⌘'],['account','내 계정','○'],['more','더보기','•••']];
const guardianNav=[['home','홈','⌂'],['pets','반려동물','♥'],['health','건강관리','＋'],['campaign','캠페인','▣'],['space','내 공간','⌘'],['services','보험·서비스','◇'],['account','내 계정','○'],['more','더보기','•••']];
const adminNav=[['admin','관리자 홈','⌂'],['members','회원 승인','✓'],['organizations','조직 관리','▦'],['operations','운영 현황','◎'],['account','내 계정','○']];
const legacyNav=[['home','홈','⌂'],['hospital','병원방','✚'],['enterprise','기업방','▦'],['campaign','캠페인','▣'],['support','무료지원','♡'],['matching','매칭','⇄'],['admin','관리자','◇']];
function isHospitalUser(){return state.me?.roles?.includes('VET')||state.me?.affiliations?.some(a=>a.organization_type==='HOSPITAL')}
function isEnterpriseUser(){return state.me?.roles?.includes('ENTERPRISE_USER')||state.me?.affiliations?.some(a=>a.organization_type==='ENTERPRISE')}
function isGuardianUser(){return state.me?.roles?.includes('GUARDIAN')}
function isAdminUser(){return state.me?.roles?.includes('ADMIN')}
function isEnterpriseContext(){return contextKind()==='enterprise'}
function isGuardianContext(){return contextKind()==='guardian'}
function isAdminContext(){return contextKind()==='admin'}
function navItems(){if(isStudentContext())return studentNav;if(isVetContext())return vetNav;return isAdminContext()?[...adminNav.slice(0,4),['space','내 공간','⌘'],['account','내 계정','○']]:isGuardianContext()?guardianNav.filter(x=>guardianPageVisible(x[0])):isEnterpriseContext()?enterpriseConsoleNav:contextKind()==='hospital'?hospitalNav:[['home','홈','⌂'],['campaign','캠페인','▣'],['support','지원','♡'],['space','내 공간','⌘'],['more','더보기','•••'],['account','내 계정','○']]}
function shell(content){const items=navItems(),contexts=availableContexts().map(c=>[c.key,c.name]);return `<div class="shell ${isStudentContext()?'student-shell':isAdminContext()?'admin-shell':contextKind()==='hospital'?'hospital-shell':isVetContext()?'vet-shell':isEnterpriseContext()?'enterprise-shell':isGuardianContext()?'guardian-shell':''}"><header class="top"><div class="top-brand"><span class="logo-mark small">D</span><span class="brand">DoctorPet</span>${isStudentContext()||isAdminContext()||isVetContext()||isGuardianContext()||contextKind()==='hospital'||(['student','admin','hospital','vet','guardian'].includes(params.get('portal'))&&!state.me)?'': '<span class="dev-tag">DEV</span>'}</div><div class="profile-chip">${contexts.length>0?`<select class="context-switch" id="contextSwitch" aria-label="서비스 공간">${contexts.map(([key,name])=>`<option value="${key}" ${state.context===key?'selected':''}>${name}</option>`).join('')}</select>`:''}<span class="current-context">${esc(availableContexts().find(c=>c.key===state.context)?.name||'내 계정')}</span><span>${esc(isAdminContext()?adminName(state.me?.profile?.display_name):state.me?.profile?.display_name||'회원')}</span>${badge(state.me?.state)}</div></header><div class="layout"><nav class="nav" aria-label="주 메뉴">${items.map(([k,v,i])=>`<button data-page="${k}" class="${(state.page===k||isAdminContext()&&state.page==='home'&&k==='admin')?'active':''}"><span>${i}</span>${v}</button>`).join('')}</nav><main class="main">${content}</main></div></div>`}
function pageTitle(title,desc,action=''){return `<div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>${action}</div>`}
function metric(title,value,note,page){return `<button class="metric-card" ${page?`data-page="${page}"`:''}><span>${esc(title)}</span><strong>${esc(value)}</strong><small>${esc(note)}</small></button>`}
function primaryHospital(){const room=currentRoom();if(contextKind()!=='hospital')return null;return state.me?.affiliations?.find(a=>a.hospital_id===room?.hospital_id&&a.status==='ACTIVE'&&a.verification_status==='VERIFIED')||state.me?.affiliations?.find(a=>a.organization_type==='HOSPITAL'&&a.status==='ACTIVE'&&a.verification_status==='VERIFIED')}
function primaryEnterprise(){const room=currentRoom();return state.me?.affiliations?.find(a=>a.enterprise_id===room?.enterprise_id&&a.status==='ACTIVE'&&a.verification_status==='VERIFIED')||state.me?.affiliations?.find(a=>a.organization_type==='ENTERPRISE'&&a.status==='ACTIVE'&&a.verification_status==='VERIFIED')}
function applicationFor(campaignId){return state.overview?.applications?.find(a=>a.campaign_id===campaignId)}

const hospitalUi={campaignFilter:'all',supportCategory:''};
const hospitalSupportCategories=[['제품 체험','PRODUCT'],['제품·샘플','PRODUCT'],['의약품·처방식·사료','PRODUCT'],['의료기기/장비 데모','DEMO'],['소모품','PRODUCT'],['현물 협찬','SPONSORSHIP'],['후원/스폰서십','SPONSORSHIP'],['병원 홍보','MANAGEMENT'],['법률 지원','MANAGEMENT'],['노무/운영 지원','MANAGEMENT'],['경영/운영 상담','MANAGEMENT'],['견적 비교','GENERAL'],['런치 세미나/교육','MANAGEMENT'],['기타 병원 요청','GENERAL']];
function hospitalAuthView(){return `<div class="auth-wrap admin-auth"><div class="auth-card"><div class="logo-mark">D</div><div class="brand auth-brand">DoctorPet</div><span class="admin-login-eyebrow">동물병원 서비스</span><h1>닥터펫 동물병원 로그인</h1><p class="muted">한 계정으로 병원과 개인공간을 이용하세요.</p>${state.sessionExpired?'<div class="notice error">로그인이 만료되었습니다. 다시 로그인해 주세요.</div>':''}<div id="msg" role="status" aria-live="polite"></div><form id="login"><label>이메일<input id="email" type="email" autocomplete="username" required></label><label>비밀번호<input id="password" type="password" autocomplete="current-password" minlength="10" required></label><button class="primary full-button">로그인</button></form><p class="admin-login-help">승인된 병원 소속과 공간 참여 상태에 따라 서비스를 이용할 수 있습니다.</p><a class="admin-service-link" href="${esc(location.pathname)}">회원가입·다른 서비스로 이동 →</a></div></div>`}
function hospitalRequestState(x){return ({OPEN:'접수',PENDING:'검토 대기',REVIEWING:'검토 중',APPROVED:'지원 승인',MATCHED:'연결 검토',COMPLETED:'지원 완료',CLOSED:'종료',REJECTED:'미승인',CANCELLED:'취소'}[x]||'상태 확인 필요')}
function hospitalMatchingState(x){return ({OPEN:'검토 대기',PENDING:'검토 대기',SUGGESTED:'연결 제안',PROPOSED:'제안 중',CONTACTED:'연락 중',ACCEPTED:'수락',SELECTED:'후보 선정',CONNECTED:'연결 완료',CONVERTED:'후속 전환 완료',COMPLETED:'검토 완료',CLOSED:'종료',REJECTED:'연결 거절',DECLINED:'연결 거절',CANCELLED:'취소'}[x]||'상태 확인 필요')}
function hospitalWorkflowBadge(x,matching=false){return `<span class="badge badge-${esc(String(x||'').toLowerCase())}">${esc(matching?hospitalMatchingState(x):hospitalRequestState(x))}</span>`}
function hospitalCanApply(c){const h=primaryHospital();return c.status==='OPEN'&&!applicationFor(c.id)&&state.me?.state==='ACTIVE'&&h?.status==='ACTIVE'&&h?.verification_status==='VERIFIED'&&(state.me?.permissions||[]).includes('CAMPAIGN_APPLY')&&(!c.starts_at||new Date(c.starts_at)<=new Date())&&(!c.ends_at||new Date(c.ends_at)>=new Date())}
function hospitalServiceCard(title,desc,page,ready=false){return `<article class="service-card ${ready?'slot':''}"><span class="${ready?'slot-badge':'now-badge'}">${ready?'준비 중':'이용 가능'}</span><h3>${esc(title)}</h3><p>${esc(desc)}</p><button class="secondary" data-page="${page}">${ready?'기능 안내':'확인하기'}</button></article>`}
function hospitalServiceBlocks(){return `<div class="service-grid">${hospitalServiceCard('보호자 건강관리','병원 보호자 연결·건강관리 결과·ReturnCare·재내원을 이어갈 서비스입니다.','hospitalCare',true)}${hospitalServiceCard('펫보험 · 보험차트','진료 시 보험정보 확인부터 청구·지급·후속관리까지 연결할 독립 서비스입니다.','hospitalInsurance',true)}${hospitalServiceCard('동물병원 비서','직원 교육·법률·노무·경영·보호자 응대 등 병원 업무를 지원할 비서입니다.','hospitalAssistant',true)}${hospitalServiceCard('회원병원 혜택·파트너','현재 등록된 캠페인 혜택과 연결 기업 제안을 확인하세요.','hospitalBenefits')}${hospitalServiceCard('추천·초대','추천 코드와 링크를 공유하고 실제 추천 관계를 확인하세요.','hospitalNetwork')}${hospitalServiceCard('소모임·공동수요','소모임과 그룹방을 이용하세요. 공동수요 자동 집계는 준비 중입니다.','space')}</div>`}
function hospitalPreparedPage(kind){const config={hospitalInsurance:{title:'펫보험 · 보험차트',desc:'병원은 진료와 보호자 접점에 집중하고, 보험 비교·가입은 보호자와 GA를 통해 연결합니다.',items:['보호자 보험가입 정보 확인','진료 시 보험차트 확인','예상 보장금액·예상 본인부담','진료·치료 후 청구 준비','청구·지급 결과 확인','ReturnCare 후속관리'],notice:'보험정보 조회·보장금액 계산·청구·지급 기능은 아직 제공되지 않습니다. 병원이 보험을 판매하거나 설명하는 화면이 아닙니다.'},hospitalCare:{title:'보호자 건강관리',desc:'우리 병원과 보호자의 건강관리·ReturnCare·후속 방문을 연결하는 서비스입니다.',items:['병원 보호자 연결','Health Check·건강관리 결과','ReturnCare·반복 건강관리','재내원·후속관리','향후 보험차트 연결'],notice:'병원에서 보호자·반려동물의 기록을 조회하는 기능은 준비 중입니다. 보호자 개인공간의 권한과 건강정보는 별도로 보호됩니다.'},hospitalAssistant:{title:'동물병원 비서',desc:'동물병원방 안에서 직원과 원장의 운영 업무를 지원할 기능입니다.',items:['직원 교육','법률','노무','분쟁/소송','병원 경영','병원 운영','보호자 응대','직원 관리','병원 업무 Q&A'],notice:'AI 답변·상담은 준비 중입니다. 현재 질문을 전송하거나 답변을 생성하지 않습니다. 무료 법률지원 신청은 무료지원센터에서 접수할 수 있습니다.'},hospitalTeam:{title:'병원 구성원·직원',desc:'우리 병원의 수의사·직원 소속을 확인할 서비스입니다.',items:['소속 수의사','직원','활성·종료 소속','구성원별 역할'],notice:'현재는 로그인한 사용자의 소속만 확인할 수 있습니다. 전체 구성원 조회·초대·권한 관리는 준비 중입니다.'},hospitalOperations:{title:'병원 운영 정보',desc:'배송·계약·협약·고객지원 정보를 연결할 서비스입니다.',items:['배송 정보','계약·협약 정보','고객지원','병원 공지·알림함'],notice:'현재 병원용 조회·수정 기능은 준비 중입니다. 지원 요청 접수는 무료지원센터를 이용해 주세요.'},hospitalFuture:{title:'병원 서비스 확장',desc:'캠페인과 병원 수요를 이어갈 후속 서비스입니다.',items:['공동수요 집계·기업 제안','공동구매','PBMT·현물지원 프로그램','회원 혜택·Reward','예약·결제·정산','활동·성과 분석'],notice:'등록·거래·자동 집계 기능은 준비 중입니다. 현재 제공 중인 혜택은 등록된 캠페인 상세에서 확인하세요.'}}[kind];return `${pageTitle(config.title,config.desc,'<button class="secondary" data-page="home">← 병원 홈</button>')}<section class="panel hospital-ready"><span class="slot-badge">준비 중</span><h2>${esc(config.title)}</h2><div class="hospital-category-grid">${config.items.map(x=>`<div><b>${esc(x)}</b><small>서비스 연결 준비 중</small></div>`).join('')}</div><div class="notice">${esc(config.notice)}</div>${['hospitalAssistant','hospitalOperations'].includes(kind)?'<button class="secondary" data-page="support">무료지원 신청</button>':''}</section>`}
function hospitalNetworkPage(){return `${pageTitle('추천·초대','주변 수의사와 동물병원에 닥터펫을 소개하세요.')}${inviteContext()}${referralPanel()}${state.mySpace?.referral?.link?`<section class="panel section"><h2>주변 수의사·동물병원 초대</h2><p>같은 추천 링크를 수의사·원장에게 공유할 수 있습니다.</p><div class="hospital-share-actions"><button class="secondary" data-copy="${esc(state.mySpace.referral.link)}">추천 링크 복사</button><a class="secondary" href="${esc('sms:?body='+encodeURIComponent('닥터펫 동물병원 협력 네트워크에 초대합니다. '+state.mySpace.referral.link))}">문자로 공유</a><button class="secondary" id="hospitalNativeShare">공유 메뉴 열기</button></div><p id="hospitalShareStatus" role="status"></p><p class="muted">문자·공유 메뉴는 기기의 앱을 엽니다. 전송 완료 여부를 대신 표시하지 않습니다. 카카오톡 전용 연결은 준비 중입니다.</p></section>`:''}<section class="panel section"><h2>소모임과 그룹방</h2><p>그룹 생성·참여·초대·그룹방은 내 공간에서 이용할 수 있습니다.</p><button class="primary" data-page="space">소모임·내 공간</button></section>`}
function hospitalBenefitsPage(){const rows=state.overview?.campaigns||[],matches=(state.overview?.matching||[]).filter(m=>m.enterprise_name);return `${pageTitle('회원병원 혜택·파트너','현재 조회된 캠페인과 우리 요청에 연결된 기업 정보입니다.')}<section class="section"><h2>등록된 캠페인 혜택</h2>${rows.length?`<div class="campaign-grid">${rows.map(c=>`<article class="campaign-card"><div class="campaign-top"><span>${esc(c.enterprise_name||'기업 정보 없음')}</span>${badge(c.status)}</div><h3>${esc(c.name)}</h3><p>${esc(c.brief?.benefit||c.brief?.benefits||'등록된 혜택 설명이 없습니다.')}</p><button class="secondary" data-campaign="${esc(c.id)}">조건·상태 확인</button></article>`).join('')}</div>`:empty('등록된 캠페인 혜택이 없습니다.')}</section><section class="panel section"><h2>연결 기업·제안 현황</h2>${matches.length?matches.map(m=>`<button class="list-card" data-matching="${esc(m.id)}"><span><b>${esc(m.enterprise_name)}</b><small>${esc(m.support_title||'지원 요청')} · ${esc(hospitalMatchingState(m.result_status||m.status))}</small></span><i>›</i></button>`).join(''):empty('현재 조회된 기업 연결 정보가 없습니다.')}<p class="muted">후보 기업 표시가 협약·후원 확정을 의미하지 않습니다.</p></section><button class="secondary" data-page="hospitalFuture">후속 서비스 안내</button>`}
function hospitalMorePage(){return `${pageTitle('더보기','동물병원방의 모든 서비스와 계정 메뉴입니다.')}<div class="more-list">${[['hospital','내 병원·소속'],['hospitalRequests','우리 병원 요청'],['matching','기업 매칭'],['hospitalCare','보호자 건강관리'],['hospitalInsurance','펫보험 · 보험차트'],['hospitalAssistant','동물병원 비서'],['hospitalNetwork','추천·초대'],['space','소모임·내 공간'],['hospitalBenefits','회원병원 혜택·파트너'],['hospitalTeam','병원 구성원·직원'],['hospitalOperations','배송·협약·고객지원'],['hospitalFuture','후속 서비스 안내'],['account','내 계정']].map(([p,n])=>`<button data-page="${p}"><span>○</span><b>${n}</b><i>›</i></button>`).join('')}</div>`}
function bindHospitalUi(){document.querySelectorAll('[data-hospital-campaign-filter]').forEach(b=>b.onclick=()=>{hospitalUi.campaignFilter=b.dataset.hospitalCampaignFilter;render()});$('#hospitalSupportCategory')?.addEventListener('change',e=>{const item=hospitalSupportCategories.find(([name])=>name===e.target.value);hospitalUi.supportCategory=item?.[0]||'';if(item){$('#supportType').value=item[1];if(!$('#supportTitle').value)$('#supportTitle').value=item[0]+' 요청'}});$('#hospitalNativeShare')?.addEventListener('click',async()=>{const box=$('#hospitalShareStatus'),url=state.mySpace?.referral?.link;if(!url)return;if(!navigator.share){box.textContent='이 기기에서는 공유 메뉴를 지원하지 않습니다. 링크 복사나 문자 공유를 이용해 주세요.';return}try{await navigator.share({title:'닥터펫 동물병원 협력 네트워크',text:'주변 수의사·동물병원에 소개합니다.',url});box.textContent='공유 메뉴 이용이 종료되었습니다. 전송 여부는 공유한 앱에서 확인해 주세요.'}catch(e){box.textContent=e.name==='AbortError'?'공유를 취소했습니다.':'공유 메뉴를 열지 못했습니다. 링크 복사를 이용해 주세요.'}})}
function sanitizeHospitalCopy(root){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(!node.textContent.includes('@'))node.textContent=node.textContent.replace(/\[(?:DEV|UX)[^\]]*\]\s*/gi,'').replace(/^0[6-9][- ]\d+\s*/,'').replace(/\bDEV\b|UX[- ]?\d+(?:[- ]\d+)?|Manual Admin|V1 UI SLOT\s*·?/gi,'').replace(/HOSPITAL_PRIVATE|VET_PRIVATE|GROUP_ROOM|ENTERPRISE_PRIVATE|GUARDIAN_PRIVATE|STUDENT_PRIVATE/g,'서비스 공간').replace(/Canonical|Membership|Affiliation|Context|Runtime|API|Room Type|project_ref|UUID/g,'서비스 연결').replace(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi,'관련 기록')}}

function hospitalHome(){const hospital=primaryHospital(),d=state.overview||{},open=(d.campaigns||[]).filter(c=>c.status==='OPEN'),applications=d.applications||[],support=d.support||[],matching=d.matching||[],alerts=[applications[0]&&`최근 캠페인 신청 · ${label(applications[0].participation_status||applications[0].status)}`,support[0]&&`최근 지원 요청 · ${hospitalRequestState(support[0].status)}`,matching[0]&&`기업 연결 · ${hospitalMatchingState(matching[0].result_status||matching[0].status)}`].filter(Boolean);return `${pageTitle('안녕하세요, '+(state.me.profile?.display_name||'병원 구성원')+'님','우리 병원의 지원·캠페인·보호자 관리·기업 연결·네트워크를 한곳에서 관리하세요.')}<section class="hospital-hero"><div><span class="eyebrow">동물병원방</span><h2>${esc(hospital?.name||'병원 소속 확인 필요')}</h2><p>${esc(state.me.profile?.display_name||'병원 구성원')} · ${esc(label(hospital?.position_code||'MEMBER'))}</p><p>${esc(label(hospital?.verification_status))} · 현재 병원 소속 ${esc(label(hospital?.status))}</p></div><button class="light-button" data-page="hospital">병원 정보 보기 →</button></section><div class="metrics five">${metric('진행 캠페인',open.length+'건','현재 조회된 모집 캠페인','campaign')}${metric('내 신청',applications.length+'건','현재 병원에서 내가 신청한 캠페인','campaign')}${metric('참여 현황',applications.filter(a=>a.participation_status).length+'건','현재 조회된 참여 내역','campaign')}${metric('무료지원',support.length+'건','내가 등록한 현재 병원 요청','support')}${metric('매칭 결과',matching.filter(m=>m.result_status==='CONNECTED').length+'건','현재 조회된 연결 결과','matching')}</div><p class="hospital-data-note">캠페인은 최근 최대 30건 기준입니다. 신청·지원·매칭은 현재 로그인한 담당자의 병원 업무 내역입니다.</p><section class="section"><div class="section-head"><h2>빠른 시작</h2></div><div class="quick-grid">${[['campaign','캠페인','신청·참여 상태'],['support','무료지원','제품·샘플·운영 지원'],['hospitalRequests','우리 병원 요청','요청 접수·기업 연결'],['hospitalCare','보호자 관리','건강관리·후속관리 준비'],['hospitalInsurance','펫보험 · 보험차트','독립 보험서비스 준비'],['hospitalNetwork','추천·소모임','추천 링크·그룹 연결'],['space','내 공간','병원·수의사·그룹 전환']].map(([p,n,d])=>`<button data-page="${p}"><b>${n}</b><span>${d}</span></button>`).join('')}</div></section><section class="section"><h2>주요 알림</h2>${alerts.length?`<div class="alert-list">${alerts.map(x=>`<div><span>●</span>${esc(x)}</div>`).join('')}</div>`:empty('새로운 업무 알림이 없습니다.','조회된 업무 상태를 바탕으로 안내합니다.')}</section><section class="section"><div class="section-head"><h2>우리 병원 서비스</h2></div>${hospitalServiceBlocks()}</section>`}
function hospitalPage(){const affiliations=(state.me.affiliations||[]).filter(a=>a.hospital_id===currentRoom()?.hospital_id&&a.status==='ACTIVE');const rooms=(state.me.rooms||[]).filter(r=>r.hospital_id===currentRoom()?.hospital_id&&r.room_type==='HOSPITAL_PRIVATE');return `${pageTitle('내 병원','인증된 소속과 병원 전용 공간을 확인합니다.')}<div class="content-grid"><section class="panel"><div class="section-head"><h2>병원·소속 정보</h2>${affiliations[0]?badge(affiliations[0].verification_status):''}</div>${affiliations.length?affiliations.map(a=>`<article class="info-card"><div><span class="eyebrow">${a.is_primary?'대표 소속':'소속 병원'}</span><h3>${esc(a.name)}</h3></div><dl><div><dt>현재 역할</dt><dd>${esc(label(a.position_code||'소속 구성원'))}</dd></div><div><dt>지역</dt><dd>${esc(a.region_code||'정보 없음')}</dd></div><div><dt>소속 상태</dt><dd>${badge(a.status)}</dd></div><div><dt>인증 상태</dt><dd>${badge(a.verification_status)}</dd></div></dl></article>`).join(''):empty('인증된 병원 소속이 없습니다.')}</section><section class="panel"><div class="section-head"><h2>병원방</h2><span>${rooms.length}개</span></div>${rooms.length?`<div class="stack">${rooms.map(r=>`<button class="list-card" data-room="${esc(r.id)}"><span class="list-icon">병</span><span><b>${esc(r.name||state.me.affiliations.find(a=>a.hospital_id===r.hospital_id)?.name||'병원')} 전용 공간</b><small>${esc(label(r.membership_role))} · ${label(r.status)}</small></span><i>›</i></button>`).join('')}</div>`:empty('참여 중인 병원방이 없습니다.')}</section></div><section class="panel permissions"><div class="section-head"><h2>현재 역할</h2></div><div class="chip-row">${(state.me.roles||[]).map(x=>`<span class="role-chip">${esc(label(x))}</span>`).join('')}</div><div class="slot-row"><div><b>내 소속과 병원 구성원</b><p>위 정보는 현재 로그인한 사용자의 소속입니다. 전체 수의사·직원 조회는 준비 중입니다.</p></div><span class="slot-badge">준비 중</span></div></section><div class="quick-grid section"><button data-page="hospitalTeam"><b>병원 구성원·직원</b><span>전체 소속 조회 준비</span></button><button data-page="hospitalOperations"><b>배송·협약·고객지원</b><span>운영 정보 연결 준비</span></button></div>`}
function roomDetailView(room){return `${pageTitle('병원방 상세','내 소속과 역할에 따라 이용할 수 있는 병원 전용 공간입니다.','<button class="secondary" data-page="hospital">← 목록</button>')}<section class="panel detail-panel"><span class="eyebrow">병원 전용 공간</span><h2>${esc(primaryHospital()?.name||'병원방')}</h2><p class="lead">캠페인, 무료지원과 매칭 현황을 병원 구성원과 함께 확인하는 공간입니다.</p><dl><div><dt>공간</dt><dd>병원방</dd></div><div><dt>내 역할</dt><dd>${esc(label(room.membership_role))}</dd></div><div><dt>이용 상태</dt><dd>${badge(room.status)}</dd></div></dl><div class="quick-grid compact"><button data-page="campaign"><b>캠페인</b><span>신청과 참여 현황</span></button><button data-page="support"><b>무료지원</b><span>요청과 진행상태</span></button><button data-page="matching"><b>매칭</b><span>기업 연결 결과</span></button></div></section>`}
function campaignCard(c){const a=applicationFor(c.id);return `<article class="campaign-card"><div class="campaign-top"><span class="eyebrow">${esc(c.enterprise_name||'파트너 기업')}</span>${badge(c.status)}</div><h3>${esc(c.name)}</h3><p>${esc(typeof c.brief==='object'?(c.brief?.summary||c.brief?.description||'동물병원을 위한 캠페인입니다.'):(c.brief||'동물병원을 위한 캠페인입니다.'))}</p><div class="date-row"><span>${fmt(c.starts_at)} 시작</span><span>${c.ends_at?fmt(c.ends_at)+' 종료':'종료일 미정'}</span></div><div class="card-actions">${a?`<span class="application-state">${label(a.participation_status||a.status)}</span>`:''}<button class="secondary" data-campaign="${esc(c.id)}">상세 보기</button></div></article>`}

function campaignsPage(){if(contextKind()!=='hospital')return legacyCampaignsPage();const all=state.overview?.campaigns||[],rows=all.filter(c=>hospitalUi.campaignFilter==='all'||hospitalUi.campaignFilter==='open'&&c.status==='OPEN'||hospitalUi.campaignFilter==='mine'&&applicationFor(c.id));return `${pageTitle('동물병원 캠페인','등록된 조건·혜택을 확인하고 우리 병원에서 신청하세요.')}<div class="filter-row">${[['all','전체'],['open','모집 중'],['mine','내 신청']].map(([v,n])=>`<button class="filter ${hospitalUi.campaignFilter===v?'active':''}" data-hospital-campaign-filter="${v}" aria-pressed="${hospitalUi.campaignFilter===v}">${n}</button>`).join('')}</div><p class="hospital-data-note">최근 조회된 캠페인 최대 30건 기준입니다. 실제 참여 대상·기간·혜택은 상세 안내를 확인해 주세요.</p>${rows.length?`<div class="campaign-grid">${rows.map(campaignCard).join('')}</div>`:empty('조건에 맞는 캠페인이 없습니다.')}`}
function campaignDetail(c){if(contextKind()!=='hospital')return legacyCampaignDetail(c);const a=applicationFor(c.id),b=c.brief&&typeof c.brief==='object'?c.brief:{};return `${pageTitle('캠페인 상세','신청·참여·완료와 후속 상태를 확인하세요.','<button class="secondary" data-page="campaign">← 목록</button>')}<article class="panel detail-panel"><div class="campaign-top"><span>${esc(c.enterprise_name||'기업 정보 없음')}</span>${badge(c.status)}</div><h2>${esc(c.name)}</h2><p class="lead">${esc(b.summary||b.description||typeof c.brief==='string'&&c.brief||'등록된 상세 설명이 없습니다.')}</p><dl class="friendly-dl">${[['캠페인 유형',labels[c.campaign_type]||'유형 정보 없음'],['기간',(c.starts_at?fmt(c.starts_at):'시작일 미등록')+' — '+(c.ends_at?fmt(c.ends_at):'종료일 미등록')],['대상',b.target||'대상 정보 미등록'],['혜택',b.benefit||b.benefits||'혜택 정보 미등록']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}<div><dt>신청 상태</dt><dd>${a?badge(a.status):'미신청'}</dd></div><div><dt>참여 상태</dt><dd>${a?.participation_status?badge(a.participation_status):'참여 기록 없음'}</dd></div><div><dt>완료일</dt><dd>${a?.completed_at?fmt(a.completed_at):'완료 기록 없음'}</dd></div></dl><div class="detail-action">${hospitalCanApply(c)?`<button class="primary" id="applyCampaign" data-id="${esc(c.id)}">이 캠페인 신청하기</button>`:a?'<div class="notice success">신청이 접수되었습니다. 표시된 진행 상태를 확인해 주세요.</div>':'<div class="notice">현재 신청할 수 없습니다. 모집 기간·병원 인증·신청 권한을 확인해 주세요.</div>'}</div><p class="muted">후속 안내가 등록되면 캠페인 상세와 업무 상태에서 확인할 수 있습니다.</p></article>`}
function supportPage(){if(contextKind()!=='hospital')return legacySupportPage();const h=primaryHospital(),can=h?.status==='ACTIVE'&&h?.verification_status==='VERIFIED'&&(state.me?.permissions||[]).includes('SUPPORT_REQUEST_CREATE'),rows=state.overview?.support||[],requests=state.page==='hospitalRequests';return `${pageTitle(requests?'우리 병원 요청':'동물병원 무료지원센터','필요한 지원을 접수하면 닥터펫에서 수요를 확인하고 기업·전문가 연결을 검토합니다.')}<div class="hospital-process"><span>병원 요청</span><span>수요 확인</span><span>기업·전문가 연결</span><span>진행 상태 확인</span></div><div class="content-grid support-layout"><section class="panel form-panel"><h2>새 지원 요청</h2>${can?`<div class="selected-hospital"><span>신청 병원</span><b>${esc(h.name)}</b>${badge(h.verification_status)}</div><form id="supportForm"><label>지원 분야<select id="hospitalSupportCategory"><option value="">분야 선택</option>${hospitalSupportCategories.map(([name])=>`<option>${esc(name)}</option>`).join('')}</select></label><label>지원 유형<select id="supportType"><option value="GENERAL">일반 지원</option><option value="PRODUCT">제품·샘플</option><option value="DEMO">장비 데모</option><option value="SPONSORSHIP">협찬·스폰서십</option><option value="MANAGEMENT">경영·운영 지원</option></select></label><label>요청 제목<input id="supportTitle" maxlength="120" required placeholder="필요한 지원을 한 줄로 알려주세요"></label><label>요청 내용<textarea id="supportDesc" maxlength="1000" rows="6" required placeholder="지원 분야, 제품·수량, 일정과 지역 등 구체적인 수요를 알려주세요"></textarea></label><p class="hospital-data-note">법률·노무 지원은 신청 접수입니다. 비서의 질문·상담 기능과 구분되며, 지원 제공은 검토·연결 후 확정됩니다.</p><button class="primary full-button">지원 요청 등록</button></form>`:'<div class="state-panel deny"><strong>인증된 병원 소속과 지원 신청 권한이 필요합니다.</strong><p>현재 계정에서는 요청을 작성할 수 없습니다. 기존 요청은 아래에서 확인하세요.</p></div>'}</section><section class="panel"><h2>내 요청 현황</h2><p class="hospital-data-note">현재 병원에서 내가 접수한 요청 ${rows.length}건</p>${rows.length?`<div class="stack">${rows.map(r=>`<button class="list-card support-card" data-support="${esc(r.id)}"><span><b>${esc(r.title||label(r.request_type))}</b><small>${fmt(r.requested_at)} · ${esc(label(r.request_type))}</small></span>${hospitalWorkflowBadge(r.status)}<i>›</i></button>`).join('')}</div>`:empty('아직 등록한 지원 요청이 없습니다.')}<button class="secondary" data-page="matching">기업 연결·매칭 확인</button></section></div>`}
function morePage(){return contextKind()==='hospital'?hospitalMorePage():legacyMorePage()}

function legacyCampaignsPage(){const rows=state.overview?.campaigns||[];return `${pageTitle('동물병원 캠페인','병원에 맞는 캠페인을 확인하고 바로 신청하세요.')}<div class="filter-row"><button class="filter active">전체 ${rows.length}</button><button class="filter">진행 중 ${rows.filter(x=>x.status==='OPEN').length}</button><span class="spacer"></span><span class="muted">내 신청 ${(state.overview?.applications||[]).length}건</span></div>${rows.length?`<div class="campaign-grid">${rows.map(campaignCard).join('')}</div>`:empty('현재 진행 중인 캠페인이 없습니다.')}`}
function legacyCampaignDetail(c){const a=applicationFor(c.id);const canApply=c.status==='OPEN'&&!a;const brief=typeof c.brief==='object'?c.brief:{};return `${pageTitle('캠페인 상세','신청 조건과 진행상태를 확인하세요.','<button class="secondary" data-page="campaign">← 목록</button>')}<article class="panel detail-panel"><div class="campaign-top"><span class="eyebrow">${esc(c.enterprise_name||'파트너 기업')}</span>${badge(c.status)}</div><h2>${esc(c.name)}</h2><p class="lead">${esc(typeof c.brief==='object'?(brief.summary||brief.description||'등록된 상세 설명이 없습니다.'):(c.brief||'등록된 상세 설명이 없습니다.'))}</p><dl><div><dt>캠페인 유형</dt><dd>${esc(labels[c.campaign_type]||'동물병원 캠페인')}</dd></div><div><dt>진행 기간</dt><dd>${fmt(c.starts_at)} — ${c.ends_at?fmt(c.ends_at):'미정'}</dd></div><div><dt>참여 대상</dt><dd>${esc(brief.target||'참여 가능한 동물병원')}</dd></div><div><dt>제공 혜택</dt><dd>${esc(brief.benefit||brief.benefits||'캠페인 상세 혜택을 확인해 주세요.')}</dd></div><div><dt>신청 상태</dt><dd>${a?badge(a.status):'미신청'}</dd></div><div><dt>참여 상태</dt><dd>${a?.participation_status?badge(a.participation_status):'참여 전'}</dd></div></dl><div class="detail-action">${canApply?`<button class="primary" id="applyCampaign" data-id="${esc(c.id)}">이 캠페인 신청하기</button>`:a?`<div class="notice success">신청이 접수되었습니다. 현재 상태: ${esc(label(a.participation_status||a.status))}</div>`:`<div class="notice">현재 신청할 수 없는 캠페인입니다.</div>`}</div></article>`}
function legacySupportPage(){const hospital=primaryHospital();const rows=state.overview?.support||[];return `${pageTitle('동물병원 무료지원센터','제품·샘플·데모·운영 지원을 요청하세요.')}<div class="content-grid support-layout"><section class="panel form-panel"><div class="section-head"><h2>새 지원 요청</h2></div>${hospital?`<div class="selected-hospital"><span>신청 병원</span><b>${esc(hospital.name)}</b>${badge(hospital.verification_status)}</div><form id="supportForm"><label>지원 유형<select id="supportType"><option value="GENERAL">일반 지원</option><option value="PRODUCT">제품·샘플</option><option value="DEMO">장비 데모</option><option value="SPONSORSHIP">협찬·스폰서십</option><option value="MANAGEMENT">경영·운영 지원</option></select></label><label>요청 제목<input id="supportTitle" maxlength="120" placeholder="필요한 지원을 한 줄로 입력하세요" required></label><label>요청 내용<textarea id="supportDesc" maxlength="1000" rows="6" placeholder="필요한 제품, 수량, 일정 등을 알려주세요" required></textarea></label><button class="primary full-button" type="submit">지원 요청 등록</button></form>`:`<div class="state-panel deny"><strong>인증된 병원 소속이 필요합니다.</strong><p>병원 소속 인증이 완료되면 무료지원을 요청할 수 있습니다.</p></div>`}</section><section class="panel"><div class="section-head"><h2>내 요청 현황</h2><span>${rows.length}건</span></div>${rows.length?`<div class="stack">${rows.map(r=>`<button class="list-card support-card" data-support="${esc(r.id)}"><span><b>${esc(r.title||r.request_type)}</b><small>${fmt(r.requested_at)} · ${esc(label(r.request_type))}</small></span>${badge(r.status)}<i>›</i></button>`).join('')}</div>`:empty('아직 등록한 지원 요청이 없습니다.','첫 지원 요청을 작성하면 진행상태를 이곳에서 확인할 수 있습니다.')}</section></div>`}
function supportDetail(r){if(contextKind()!=='hospital')return legacySupportDetail(r);const match=(state.overview?.matching||[]).find(m=>m.support_request_id===r.id);return `${pageTitle('지원 요청 상세','접수 내용과 기업 연결 진행 상태를 확인하세요.','<button class="secondary" data-page="support">← 목록</button>')}<section class="panel detail-panel"><div class="campaign-top"><span>${esc(label(r.request_type))}</span>${hospitalWorkflowBadge(r.status)}</div><h2>${esc(r.title||'지원 요청')}</h2><p class="lead">${esc(r.description||'등록된 상세 내용이 없습니다.')}</p><dl><div><dt>신청 병원</dt><dd>${esc(primaryHospital()?.name||'병원 정보 없음')}</dd></div><div><dt>접수일</dt><dd>${fmt(r.requested_at)}</dd></div><div><dt>연결 상태</dt><dd>${match?hospitalWorkflowBadge(match.result_status||match.status,true):'매칭 대기'}</dd></div></dl>${match?'<button class="secondary" data-page="matching">매칭 결과 보기 →</button>':'<p class="muted">요청을 확인한 뒤 연결을 검토합니다. 접수가 기업 연결이나 지원 확정을 의미하지 않습니다.</p>'}</section>`}
function legacySupportDetail(r){const match=(state.overview?.matching||[]).find(m=>m.support_request_id===r.id);return `${pageTitle('지원 요청 상세','요청 내용과 매칭 진행상태입니다.','<button class="secondary" data-page="support">← 목록</button>')}<section class="panel detail-panel"><div class="campaign-top"><span class="eyebrow">${esc(label(r.request_type))}</span>${badge(r.status)}</div><h2>${esc(r.title||'지원 요청')}</h2><p class="lead">${esc(r.description||'등록된 상세 내용이 없습니다.')}</p><dl><div><dt>신청 병원</dt><dd>${esc(primaryHospital()?.name||'-')}</dd></div><div><dt>신청일</dt><dd>${fmt(r.requested_at)}</dd></div><div><dt>매칭 상태</dt><dd>${match?badge(match.status):'매칭 대기'}</dd></div></dl>${match?`<button class="secondary" data-page="matching">매칭 결과 보기 →</button>`:''}</section>`}
function matchingPage(){const rows=state.overview?.matching||[];return `${pageTitle('기업 매칭','지원 요청별 기업 연결 결과를 확인하세요.')}${contextKind()==='hospital'?'<p class="hospital-data-note">현재 병원에서 로그인한 담당자의 지원 요청에 연결된 결과입니다. 연결·협약·지원 확정은 표시된 상태를 확인해 주세요.</p>':''}<section class="panel"><div class="section-head"><h2>매칭 현황</h2><span>${rows.length}건</span></div>${rows.length?`<div class="stack">${rows.map(m=>`<button class="matching-card" data-matching="${esc(m.id)}"><span class="match-flow"><i>요청</i><em></em><i>매칭</i><em></em><i class="${m.result_status==='CONNECTED'?'done':''}">연결</i></span><span class="match-copy"><b>${esc(m.support_title||'지원 요청')}</b><small>${esc(m.enterprise_name||'기업 검토 중')} · ${fmt(m.opened_at)}</small></span>${contextKind()==='hospital'?hospitalWorkflowBadge(m.result_status||m.status,true):badge(m.result_status||m.status)}<strong>›</strong></button>`).join('')}</div>`:empty('진행 중인 매칭이 없습니다.','무료지원 요청이 접수되면 매칭 진행상태가 표시됩니다.')}</section>`}
function matchingDetail(m){return `${pageTitle('매칭 상세','지원 요청과 연결 기업의 현재 상태입니다.','<button class="secondary" data-page="matching">← 목록</button>')}<section class="panel detail-panel"><div class="campaign-top"><span class="eyebrow">${contextKind()==='hospital'?'기업 연결':'MATCHING'}</span>${contextKind()==='hospital'?hospitalWorkflowBadge(m.result_status||m.status,true):badge(m.result_status||m.status)}</div><h2>${esc(m.support_title||'지원 요청 매칭')}</h2><div class="match-steps"><div class="done"><b>1</b><span>지원 요청<small>접수 완료</small></span></div><div class="${m.status?'done':''}"><b>2</b><span>기업 매칭<small>${esc(m.enterprise_name||'검토 중')}</small></span></div><div class="${m.result_status==='CONNECTED'?'done':''}"><b>3</b><span>연결 결과<small>${esc(contextKind()==='hospital'?hospitalMatchingState(m.result_status||'PENDING'):label(m.result_status||'PENDING'))}</small></span></div></div><dl><div><dt>매칭 기업</dt><dd>${esc(m.enterprise_name||'선정 중')}</dd></div><div><dt>후보 상태</dt><dd>${esc(contextKind()==='hospital'?hospitalMatchingState(m.candidate_status||'PENDING'):label(m.candidate_status||'PENDING'))}</dd></div><div><dt>연결 상태</dt><dd>${contextKind()==='hospital'?hospitalWorkflowBadge(m.result_status||m.status,true):badge(m.result_status||m.status)}</dd></div><div><dt>연결일</dt><dd>${fmt(m.connected_at)}</dd></div></dl></section>`}
const slotSurfaces={owner:{kind:'개인공간',title:'원장 개인방',description:'병원 공용 공간과 분리된 원장님의 개인 업무 공간입니다.',items:['내 업무','내 활동','내 관계','내 알림']},vet:{kind:'수의사',title:'수의사방',description:'수의학 정보와 직군 네트워크를 위한 개인 공간입니다.',items:['수의학 정보','논문·증례','교육·세미나','수의사 네트워크']},assistant:{kind:'Personal AI',title:'내 비서방',description:'개인 업무와 기억을 연결할 확장 공간입니다.',items:['할 일','미완료 업무','결정·메모','후속 알림']},ownedGroups:{kind:'그룹·소모임',title:'내가 운영하는 그룹',description:'내가 만든 그룹과 그룹장으로 운영하는 공간입니다.',items:['운영 그룹','그룹 구성원','그룹장 위임']},joinedGroups:{kind:'그룹·소모임',title:'내가 참여하는 그룹',description:'가입한 그룹과 소모임을 확인하는 공간입니다.',items:['참여 그룹','그룹 소식','그룹방']},createGroup:{kind:'그룹·소모임',title:'그룹 만들기',description:'새 그룹을 만들고 참여자를 초대하는 기능입니다.',items:['그룹 정보','공개 범위','그룹방 연결']},invite:{kind:'초대',title:'초대하기',description:'조직과 공간에 함께할 사람을 초대하는 기능입니다.',items:['초대 대상','초대 상태','수락 확인']},share:{kind:'공유',title:'공유 링크',description:'캠페인과 그룹을 안전하게 공유하는 기능입니다.',items:['공유 링크','공유 상태','유입 확인']},referralCode:{kind:'추천',title:'추천 코드',description:'내 추천 코드와 사용 상태를 확인하는 기능입니다.',items:['추천 코드','사용 상태','추천 연결']},referralStatus:{kind:'추천',title:'추천 현황',description:'내 추천 활동과 연결 결과를 확인하는 기능입니다.',items:['추천 건수','연결 상태','최근 추천']},referralLineage:{kind:'추천',title:'추천 계보',description:'직접 추천과 이어진 추천 관계를 확인하는 기능입니다.',items:['직접 추천','추천 경로','연결 계보']}};
function slotCard(key,icon){const s=slotSurfaces[key];return `<button class="space-card slot" data-slot="${esc(key)}"><span class="space-icon">${esc(icon)}</span><span class="space-copy"><small>${esc(s.kind)}</small><b>${esc(s.title)}</b><em>${esc(s.description)}</em></span><span class="slot-badge">준비 중</span><i>›</i></button>`}
function friendlyRoom(room){const map={HOSPITAL_PRIVATE:['병','병원방'],VET_PRIVATE:['수','수의사방'],ENTERPRISE_PRIVATE:['기','기업방'],GUARDIAN_PRIVATE:['보','보호자방'],STUDENT_PRIVATE:['학','수의대생방'],GROUP_ROOM:['그','그룹방']};return map[room.room_type]||['공','참여 공간']}
function membershipCard(room){const [icon,name]=friendlyRoom(room);const hospital=room.room_type==='HOSPITAL_PRIVATE';return `<button class="space-card actual" ${hospital?`data-room="${esc(room.id)}"`:`data-space-room="${esc(room.id)}"`}><span class="space-icon">${icon}</span><span class="space-copy"><small>참여 중</small><b>${esc(hospital?(primaryHospital()?.name||name):name)}</b><em>${esc(label(room.membership_role))} · ${esc(label(room.status))}</em></span><span class="now-badge">이용 가능</span><i>›</i></button>`}
function spacePage(){const rooms=state.me.rooms||[];const hospital=primaryHospital();const operated=rooms.filter(r=>r.membership_role==='OWNER');return `${pageTitle('내 공간','한 계정에 연결된 역할과 공간을 한곳에서 확인하세요.')}<section class="space-summary"><div><span class="eyebrow">내 역할</span><h2>${esc((state.me.roles||[]).map(label).join(' · ')||'회원')}</h2><p>로그아웃하지 않고 연결된 공간 사이를 이동할 수 있습니다.</p></div><div><strong>${rooms.length}</strong><span>참여 공간</span></div></section><section class="space-section"><div class="section-head"><div><h2>내 개인공간</h2><p>나의 역할을 중심으로 확장될 개인 공간입니다.</p></div></div><div class="space-list">${slotCard('owner','나')}${slotCard('vet','수')}${slotCard('assistant','AI')}</div></section><section class="space-section"><div class="section-head"><div><h2>내가 운영하는 공간</h2><p>Owner 관계가 확인된 공간입니다.</p></div></div><div class="space-list">${hospital?`<button class="space-card actual" data-page="hospital"><span class="space-icon">병</span><span class="space-copy"><small>내 병원</small><b>${esc(hospital.name)}</b><em>${esc(label(hospital.position_code||'OWNER'))} · ${esc(label(hospital.verification_status))}</em></span><span class="now-badge">이용 가능</span><i>›</i></button>`:''}${operated.filter(r=>r.room_type!=='HOSPITAL_PRIVATE').map(membershipCard).join('')}${slotCard('ownedGroups','그')}</div></section><section class="space-section"><div class="section-head"><div><h2>내가 참여하는 공간</h2><p>현재 활성 Membership으로 연결된 공간입니다.</p></div><span>${rooms.length}개</span></div>${rooms.length?`<div class="space-list">${rooms.map(membershipCard).join('')}</div>`:empty('참여 중인 공간이 없습니다.','소속이나 초대가 확인되면 이곳에 표시됩니다.')}</section><section class="space-section"><div class="section-head"><div><h2>그룹·소모임</h2><p>Canonical 구조는 준비되어 있으며 사용자 API 연결 전입니다.</p></div></div><div class="space-list compact-list">${slotCard('joinedGroups','그')}${slotCard('createGroup','＋')}</div></section><section class="space-section"><div class="section-head"><div><h2>초대·추천</h2><p>초대와 추천 관계를 확인할 확장 진입점입니다.</p></div></div><div class="space-list compact-list">${slotCard('invite','초')}${slotCard('share','링')}${slotCard('referralCode','코')}${slotCard('referralStatus','현')}${slotCard('referralLineage','계')}</div></section><div class="notice">‘준비 중’ 기능은 화면 구조만 제공하며 요청 전송이나 데이터 변경을 수행하지 않습니다.</div>`}
function slotDetail(key){const s=slotSurfaces[key];return `${pageTitle(s.title,'현재는 확장 위치만 준비된 기능입니다.','<button class="secondary" data-page="space">← 내 공간</button>')}<section class="panel slot-detail"><span class="slot-badge">V1 UI SLOT · 준비 중</span><h2>${esc(s.title)}</h2><p class="lead">${esc(s.description)}</p><div class="future-list">${s.items.map(x=>`<div><span>○</span><b>${esc(x)}</b><small>향후 API 연결 후 제공</small></div>`).join('')}</div><div class="notice">현재 화면에서는 조회·저장·초대·공유를 실행하지 않습니다.</div></section>`}
function spaceRoomDetail(room){const [,name]=friendlyRoom(room);return `${pageTitle(name,'현재 Membership으로 접근 가능한 공간입니다.','<button class="secondary" data-page="space">← 내 공간</button>')}<section class="panel detail-panel"><span class="now-badge">이용 가능</span><h2>${esc(name)}</h2><p class="lead">현재 연결된 공간과 내 참여 상태를 확인합니다. 전용 서비스 기능은 해당 UX Block에서 연결됩니다.</p><dl><div><dt>내 역할</dt><dd>${esc(label(room.membership_role))}</dd></div><div><dt>이용 상태</dt><dd>${badge(room.status)}</dd></div></dl></section>`}
function groupCard(g){return `<button class="space-card actual" data-group="${esc(g.id)}"><span class="space-icon">그</span><span class="space-copy"><small>${g.group_role==='OWNER'?'내가 운영':'참여 중'}</small><b>${esc(g.name)}</b><em>${esc(g.description||'그룹 소개가 아직 없습니다.')} · ${g.member_count}명</em></span><span class="now-badge">${esc(label(g.group_role))}</span><i>›</i></button>`}
function inviteContext(){if(!state.groupInvite&&!state.referral)return '';return `<section class="context-banner"><div><b>${state.groupInvite?'그룹 초대가 도착했습니다.':'추천 링크로 방문했습니다.'}</b><p>현재 계정으로 연결 내용을 확인하고 수락할 수 있습니다.</p></div><button class="primary" id="${state.groupInvite?'acceptGroupInvite':'acceptReferral'}">연결 수락</button></section>`}
function referralPanel(){const r=state.mySpace?.referral||{};return `<div class="referral-grid"><article class="panel referral-code"><span class="eyebrow">내 추천코드</span>${r.code?`<strong>${esc(r.code)}</strong><p>추천 링크를 공유하면 연결 관계가 자동으로 기록됩니다.</p><div class="copy-row"><input readonly value="${esc(r.link)}" aria-label="추천 링크"><button class="secondary" data-copy="${esc(r.link)}">복사</button></div>`:`<h3>추천코드 만들기</h3><p>내부 회원번호가 노출되지 않는 안전한 추천코드를 생성합니다.</p><button class="primary" id="ensureReferral">추천코드 생성</button>`}</article><article class="panel"><span class="eyebrow">추천 현황</span><div class="referral-metrics"><div><strong>${r.directCount||0}</strong><span>1차 추천</span></div><div><strong>${r.totalCount||0}</strong><span>누적 추천</span></div></div><p class="muted">나를 추천한 사람: ${esc(r.referredBy||'없음')}</p></article></div><section class="panel lineage-panel"><div class="section-head"><h2>추천 계보</h2><span>${r.totalCount||0}명</span></div>${r.tree?.length?`<div class="lineage-tree">${r.tree.map(x=>`<div style="--level:${Math.min(x.level,6)}"><span>└</span><b>${esc(x.referred_name||'회원')}</b><small>${x.level}차 추천</small></div>`).join('')}</div>`:empty('아직 추천 관계가 없습니다.','추천 링크를 공유하면 실제 연결 결과가 계보로 표시됩니다.')}</section>`}
function spacePageNow(){const rooms=state.me.rooms||[],hospital=primaryHospital(),groups=state.mySpace?.groups||[],owned=groups.filter(g=>g.group_role==='OWNER'),joined=groups.filter(g=>g.group_role!=='OWNER');return `${pageTitle('내 공간','한 계정에 연결된 역할과 공간을 한곳에서 확인하세요.')}${inviteContext()}<section class="space-summary"><div><span class="eyebrow">내 역할</span><h2>${esc((state.me.roles||[]).map(label).join(' · ')||'회원')}</h2><p>로그아웃하지 않고 연결된 공간 사이를 이동할 수 있습니다.</p></div><div><strong>${rooms.length}</strong><span>참여 공간</span></div></section><section class="space-section"><div class="section-head"><div><h2>내 개인공간</h2><p>나의 역할을 중심으로 확장될 개인 공간입니다.</p></div></div><div class="space-list">${slotCard('owner','나')}${rooms.find(r=>r.room_type==='VET_PRIVATE')?membershipCard(rooms.find(r=>r.room_type==='VET_PRIVATE')):slotCard('vet','수')}${slotCard('assistant','AI')}</div></section><section class="space-section"><div class="section-head"><div><h2>내가 운영하는 공간</h2><p>내 병원과 직접 만든 그룹을 관리합니다.</p></div></div><div class="space-list">${hospital?`<button class="space-card actual" data-page="hospital"><span class="space-icon">병</span><span class="space-copy"><small>내 병원</small><b>${esc(hospital.name)}</b><em>${esc(label(hospital.position_code||'OWNER'))} · ${esc(label(hospital.verification_status))}</em></span><span class="now-badge">이용 가능</span><i>›</i></button>`:''}${owned.map(groupCard).join('')}</div></section><section class="space-section"><div class="section-head"><div><h2>내가 참여하는 공간</h2><p>현재 활성 Membership으로 연결된 Room과 그룹입니다.</p></div><span>${rooms.length+joined.length}개</span></div>${rooms.length||joined.length?`<div class="space-list">${rooms.map(membershipCard).join('')}${joined.map(groupCard).join('')}</div>`:empty('참여 중인 공간이 없습니다.','소속이나 초대가 확인되면 이곳에 표시됩니다.')}</section><section class="space-section"><div class="section-head"><div><h2>그룹·소모임 만들기</h2><p>그룹을 만들면 그룹장과 전용 그룹방이 함께 연결됩니다.</p></div></div><section class="panel form-panel group-form"><form id="groupForm"><label>그룹명<input id="groupName" maxlength="80" placeholder="예: 재활 수의사 소모임" required></label><label>그룹 소개<textarea id="groupDescription" maxlength="500" rows="4" placeholder="그룹의 목적과 활동을 소개해 주세요"></textarea></label><button class="primary" type="submit">그룹 만들기</button></form></section></section><section class="space-section"><div class="section-head"><div><h2>초대·공유·추천</h2><p>그룹 초대와 추천 관계를 실제 링크로 연결합니다.</p></div></div>${referralPanel()}</section>`}
function groupDetailView(g){const owner=g.group_role==='OWNER';return `${pageTitle(g.name,'그룹 정보와 현재 구성원을 확인하세요.','<button class="secondary" data-page="space">← 내 공간</button>')}<section class="panel detail-panel"><div class="campaign-top"><span class="eyebrow">그룹·소모임</span>${badge(g.status)}</div><h2>${esc(g.name)}</h2><p class="lead">${esc(g.description||'그룹 소개가 아직 없습니다.')}</p><dl><div><dt>내 역할</dt><dd>${esc(label(g.group_role))}</dd></div><div><dt>구성원</dt><dd>${g.members?.length||0}명</dd></div></dl>${owner?`<div class="invite-box"><h3>그룹 초대·공유</h3><p>7일 동안 유효한 안전한 초대 링크를 만듭니다.</p><button class="primary" id="createGroupInvite" data-id="${esc(g.id)}">초대 링크 생성</button><div id="inviteResult"></div></div>`:''}<div class="group-lifecycle">${owner?`<label>그룹장 위임<select id="nextGroupOwner"><option value="">구성원 선택</option>${(g.members||[]).filter(m=>m.person_id&&m.person_id!==state.me.id).map(m=>`<option value="${esc(m.person_id)}">${esc(m.display_name)}</option>`).join('')}</select></label><button class="secondary" data-group-action="TRANSFER_GROUP_OWNER" data-id="${esc(g.id)}">그룹장 위임</button><button class="danger-button" data-group-action="ARCHIVE_GROUP" data-id="${esc(g.id)}">그룹 보관</button>`:`<button class="danger-button" data-group-action="LEAVE_GROUP" data-id="${esc(g.id)}">그룹 탈퇴</button>`}</div><div class="member-list"><h3>그룹 구성원</h3>${(g.members||[]).map(m=>`<div><span class="avatar small-avatar">${esc((m.display_name||'회').slice(0,1))}</span><b>${esc(m.display_name||'회원')}</b>${badge(m.group_role)}</div>`).join('')}</div></section>`}
function legacyMorePage(){return `${pageTitle('더보기','병원 운영과 계정 메뉴를 확인하세요.')}<div class="more-list"><button data-page="hospital"><span>✚</span><b>내 병원</b><i>›</i></button><button data-page="matching"><span>⇄</span><b>매칭</b><i>›</i></button><button data-page="account"><span>○</span><b>내 계정</b><i>›</i></button></div>`}
function accountPage(){return `${pageTitle('내 계정','동일 계정의 프로필·역할·소속·상태를 확인합니다.')}<section class="panel account-panel"><div class="avatar">${esc((state.me.profile?.display_name||'회').slice(0,1))}</div><h2>${esc(isAdminContext()?adminName(state.me.profile?.display_name):state.me.profile?.display_name||'회원')}</h2><p>${esc(state.me.profile?.email||'')}</p><dl><div><dt>회원 상태</dt><dd>${badge(state.me.state)}</dd></div><div><dt>역할</dt><dd>${esc((state.me.roles||[]).map(label).join(' · '))}</dd></div></dl><h3>모든 소속</h3>${(state.me.affiliations||[]).map(a=>`<article class="info-card"><h4>${esc(a.name)}</h4><p>${esc(label(a.position_code||'구성원'))} · ${esc(label(a.status))} · ${esc(label(a.verification_status))}${a.is_primary?' · 대표 소속':''}</p></article>`).join('')||empty('연결된 소속이 없습니다.')}<button class="danger-button" id="accountLogout">로그아웃</button></section>`}
function enterpriseHome(){const d=state.enterprise,e=d?.enterprise,c=d?.campaigns||[],m=d?.matching||[];if(!e)return enterpriseMissing();const alerts=[c[0]&&`${c[0].name} 캠페인이 ${label(c[0].status)} 상태입니다.`,m[0]&&`${m[0].hospital_name||'동물병원'} 요청이 ${label(m[0].result_status||m[0].candidate_status||m[0].status)} 상태입니다.`].filter(Boolean);return `${pageTitle('기업 서비스 홈','동물병원 네트워크 캠페인과 매칭 현황을 확인하세요.')}<section class="enterprise-hero"><div><span class="eyebrow">내 기업</span><h2>${esc(e.name)}</h2><p>${esc(label(e.position_code||'기업회원'))} · ${esc(label(e.affiliation_verification))}</p></div><button class="light-button" data-page="enterprise">기업방 보기 →</button></section><div class="metrics">${metric('진행 캠페인',c.filter(x=>['OPEN','ACTIVE'].includes(x.status)).length+'건','우리 기업 캠페인','campaign')}${metric('참여 병원',c.reduce((n,x)=>n+(x.hospital_count||0),0)+'곳','캠페인 연결 병원','campaign')}${metric('병원 매칭',m.length+'건',m[0]?label(m[0].result_status||m[0].candidate_status):'새 매칭 없음','matching')}${metric('제휴 프로그램',(d.advertisements?.length||0)+(d.sponsorships?.length||0)+'건','광고·스폰서십','partnership')}</div><section class="section"><div class="section-head"><h2>해야 할 일</h2></div>${alerts.length?`<div class="alert-list">${alerts.map(x=>`<div><span>●</span>${esc(x)}</div>`).join('')}</div>`:empty('현재 확인할 새 업무가 없습니다.','새로운 캠페인 신청이나 병원 매칭이 생기면 알려드립니다.')}</section><section class="section"><div class="section-head"><h2>DoctorPet에서 할 수 있는 일</h2></div>${enterpriseServices()}</section>`}
function enterpriseMissing(){return `${pageTitle('기업 서비스','기업 소속과 기업방을 확인합니다.')}<div class="state-panel deny"><strong>인증된 기업 소속이 필요합니다.</strong><p>기업 Affiliation과 기업방 Membership이 확인되면 기업 전용 서비스를 이용할 수 있습니다.</p></div>`}
function enterpriseServices(){const services=[['동물병원 캠페인','전국 제휴 동물병원을 대상으로 제품 체험·설문·캠페인을 진행합니다.','campaign','NOW'],['병원 지원·샘플·데모','병원이 요청한 제품·샘플·의료기기 데모와 연결됩니다.','matching','NOW'],['보호자 캠페인','참여 병원을 통해 보호자 대상 혜택과 체험을 확장합니다.','','SLOT'],['광고','병원 네트워크 광고 문의를 접수합니다. 실제 광고 운영은 검토 후 진행합니다.','partnership','NOW'],['공식 스폰서십','공식 후원 상담을 접수합니다. 계약과 후원 확정은 별도 검토합니다.','partnership','NOW']];return `<div class="service-grid">${services.map(([n,d,p,s])=>`<article class="service-card ${s==='SLOT'?'slot':''}"><span class="${s==='NOW'?'now-badge':'slot-badge'}">${s==='NOW'?'이용 가능':'상담 준비'}</span><h3>${esc(n)}</h3><p>${esc(d)}</p>${p?`<button class="secondary" data-page="${p}">확인하기</button>`:'<small>현재 온라인 접수 기능은 준비 중입니다.</small>'}</article>`).join('')}</div>`}
function enterpriseRoomPage(){const d=state.enterprise,e=d?.enterprise;if(!e)return enterpriseMissing();return `${pageTitle('기업방','우리 기업에 연결된 캠페인과 병원 네트워크 업무 공간입니다.')}<section class="enterprise-hero compact"><div><span class="eyebrow">기업 전용 공간</span><h2>${esc(e.name)}</h2><p>${esc(label(e.membership_role))} · ${esc(label(e.room_status))}</p></div>${badge(e.affiliation_verification)}</section><div class="content-grid"><section class="panel"><div class="section-head"><h2>기업 정보·소속</h2><span class="slot-badge">수정 준비 중</span></div><dl class="friendly-dl"><div><dt>기업명</dt><dd>${esc(e.name)}</dd></div><div><dt>내 직책</dt><dd>${esc(label(e.position_code||'기업회원'))}</dd></div><div><dt>소속 상태</dt><dd>${badge(e.affiliation_status)}</dd></div><div><dt>인증 상태</dt><dd>${badge(e.affiliation_verification)}</dd></div></dl></section><section class="panel"><div class="section-head"><h2>기업방 구성원</h2><span>${d.members?.length||0}명</span></div>${d.members?.length?`<div class="member-list enterprise-members">${d.members.map(m=>`<div><span class="avatar small-avatar">${esc((m.display_name||'회').slice(0,1))}</span><b>${esc(m.display_name||'기업 회원')}</b>${badge(m.membership_role)}</div>`).join('')}</div>`:empty('표시할 기업 구성원이 없습니다.')}</section></div><section class="section"><div class="section-head"><h2>기업 업무 바로가기</h2></div><div class="quick-grid"><button data-page="campaign"><b>캠페인</b><span>참여 병원과 신청 현황</span></button><button data-page="matching"><b>병원 매칭</b><span>병원 요청과 연결 결과</span></button><button data-page="partnership"><b>제휴·광고·스폰서</b><span>기업 프로그램 안내</span></button></div></section>`}
function enterpriseCampaignCard(c){return `<article class="campaign-card"><div class="campaign-top"><span class="eyebrow">${esc(label(c.campaign_type)||'동물병원 캠페인')}</span>${badge(c.status)}</div><h3>${esc(c.name)}</h3><p>${esc(c.brief?.summary||c.brief?.description||'동물병원 네트워크 캠페인입니다.')}</p><div class="campaign-stats"><span>신청 <b>${c.application_count||0}</b></span><span>참여 <b>${c.participation_count||0}</b></span><span>병원 <b>${c.hospital_count||0}</b></span></div><div class="card-actions"><button class="secondary" data-enterprise-campaign="${esc(c.id)}">상세 보기</button></div></article>`}
function enterpriseCampaignsPage(){const rows=state.enterprise?.campaigns||[];return `${pageTitle('기업 캠페인','우리 기업의 캠페인과 참여 병원 현황을 확인합니다.')}<div class="campaign-proposal"><div><b>새 병원 캠페인을 진행하고 싶으신가요?</b><p>캠페인 제안을 접수하면 운영자가 검토합니다. 접수는 캠페인 개설이나 계약 체결과 별개입니다.</p></div>${enterpriseInquiryForm("CAMPAIGN")}</div>${rows.length?`<div class="campaign-grid">${rows.map(enterpriseCampaignCard).join('')}</div>`:empty('현재 등록된 기업 캠페인이 없습니다.','캠페인이 개설되면 진행상태와 참여 병원을 이곳에서 확인할 수 있습니다.')}`}
function enterpriseCampaignDetail(c){const apps=(state.enterprise?.applications||[]).filter(x=>x.campaign_id===c.id);return `${pageTitle('캠페인 상세','기간, 대상과 참여 현황을 확인합니다.','<button class="secondary" data-page="campaign">← 목록</button>')}<section class="panel detail-panel"><div class="campaign-top"><span class="eyebrow">기업 캠페인</span>${badge(c.status)}</div><h2>${esc(c.name)}</h2><p class="lead">${esc(c.brief?.summary||c.brief?.description||'등록된 상세 설명이 없습니다.')}</p><dl><div><dt>진행 기간</dt><dd>${fmt(c.starts_at)} — ${c.ends_at?fmt(c.ends_at):'미정'}</dd></div><div><dt>대상</dt><dd>${esc(c.brief?.target||'제휴 동물병원')}</dd></div><div><dt>신청</dt><dd>${c.application_count||0}건</dd></div><div><dt>참여 병원</dt><dd>${c.hospital_count||0}곳</dd></div></dl></section><section class="panel campaign-hospitals"><div class="section-head"><h2>신청·참여 현황</h2><span>${apps.length}건</span></div>${apps.length?`<div class="stack">${apps.map(a=>`<article class="list-card"><span class="list-icon">병</span><span><b>${esc(a.applicant_name)}</b><small>${fmt(a.submitted_at)} · ${esc(label(a.status))}</small></span>${badge(a.participation_status||a.status)}</article>`).join('')}</div>`:empty('아직 신청한 병원이 없습니다.')}</section>`}
function enterpriseMatchingPage(){const rows=state.enterprise?.matching||[];return `${pageTitle('병원 요청·매칭','우리 기업 후보로 연결된 병원 요청만 표시합니다.')}<div class="notice">병원 내부정보와 보호자 개인정보는 표시하지 않습니다. 수락·거절 Action은 운영자 연결 후 제공됩니다.</div>${rows.length?`<div class="matching-list enterprise-match-list">${rows.map(r=>`<button class="matching-card" data-enterprise-match="${esc(r.id)}"><span class="match-flow"><i>병원 요청</i><em></em><i>기업 연결</i></span><span class="match-copy"><b>${esc(r.support_title||label(r.request_type))}</b><small>${esc(r.hospital_name||'제휴 동물병원')} · ${esc(r.region_code||'지역 정보 없음')} · ${fmt(r.requested_at)}</small></span>${badge(r.result_status||r.candidate_status||r.status)}<strong>›</strong></button>`).join('')}</div>`:empty('새로운 병원 매칭 결과가 없습니다.','우리 기업이 후보로 선정된 요청만 이곳에 표시됩니다.')}`}
function enterpriseMatchDetail(r){return `${pageTitle('병원 매칭 상세','허용된 범위의 요청과 연결상태입니다.','<button class="secondary" data-page="matching">← 목록</button>')}<section class="panel detail-panel"><div class="campaign-top"><span class="eyebrow">${esc(label(r.request_type))}</span>${badge(r.result_status||r.candidate_status||r.status)}</div><h2>${esc(r.support_title||'병원 지원 요청')}</h2><dl><div><dt>요청 병원</dt><dd>${esc(r.hospital_name||'제휴 동물병원')}</dd></div><div><dt>지역</dt><dd>${esc(r.region_code||'정보 없음')}</dd></div><div><dt>요청일</dt><dd>${fmt(r.requested_at)}</dd></div><div><dt>연결 상태</dt><dd>${esc(label(r.result_status||r.candidate_status||r.status))}</dd></div></dl><div class="notice">기업의 직접 수락·거절·제안 기능은 현재 API가 없어 표시하지 않습니다.</div></section>`}
function partnershipPage(){return `${pageTitle('제휴·광고·스폰서','DoctorPet 병원 네트워크와 함께할 수 있는 기업 프로그램입니다.')} ${enterpriseServices()}${enterpriseInquiryForm("PARTNERSHIP")}<div class="content-grid partnership-status"><section class="panel"><div class="section-head"><h2>광고 현황</h2><span>${state.enterprise?.advertisements?.length||0}건</span></div>${state.enterprise?.advertisements?.length?state.enterprise.advertisements.map(x=>`<div class="status-row"><b>${esc(x.name)}</b>${badge(x.status)}</div>`).join(''):empty('진행 중인 광고가 없습니다.','아래 문의에서 광고 제안을 접수할 수 있습니다.')}</section><section class="panel"><div class="section-head"><h2>스폰서십 현황</h2><span>${state.enterprise?.sponsorships?.length||0}건</span></div>${state.enterprise?.sponsorships?.length?state.enterprise.sponsorships.map(x=>`<div class="status-row"><b>${esc(x.name)}</b>${badge(x.status)}</div>`).join(''):empty('진행 중인 스폰서십이 없습니다.','아래 문의에서 스폰서십 상담을 접수할 수 있습니다.')}</section></div>`}
function enterpriseAccountPage(){const e=state.enterprise?.enterprise;return `${pageTitle('내 계정','회원정보와 기업 소속을 확인합니다.')}<section class="panel account-panel"><div class="avatar">${esc((state.me.profile?.display_name||'회').slice(0,1))}</div><h2>${esc(state.me.profile?.display_name||'기업 회원')}</h2><p>${esc(state.me.profile?.email||'')}</p><dl><div><dt>회원 상태</dt><dd>${badge(state.me.state)}</dd></div><div><dt>역할</dt><dd>기업회원</dd></div><div><dt>소속 기업</dt><dd>${esc(e?.name||'확인 필요')}</dd></div><div><dt>기업 인증</dt><dd>${e?badge(e.affiliation_verification):'-'}</dd></div></dl><button class="danger-button" id="accountLogout">로그아웃</button></section>`}
function enterpriseSpacePage(){const e=state.enterprise?.enterprise,groups=state.mySpace?.groups||[];return `${pageTitle('내 공간','기업방과 내가 참여하는 공간을 한 계정에서 이동합니다.')}<section class="space-summary"><div><span class="eyebrow">현재 Context</span><h2>${esc(e?.name||'기업 회원')}</h2><p>기업방·그룹·다른 역할 공간을 로그아웃 없이 이동합니다.</p></div><div><strong>${(state.me.rooms||[]).length+groups.length}</strong><span>참여 공간</span></div></section><section class="space-section"><div class="section-head"><div><h2>기업 공간</h2><p>인증된 기업 소속과 Membership으로 연결됩니다.</p></div></div><div class="space-list">${e?`<button class="space-card actual" data-page="enterprise"><span class="space-icon">기</span><span class="space-copy"><small>내 기업</small><b>${esc(e.name)}</b><em>${esc(label(e.membership_role))} · ${esc(label(e.room_status))}</em></span><span class="now-badge">이용 가능</span><i>›</i></button>`:''}</div></section><section class="space-section"><div class="section-head"><div><h2>그룹·소모임</h2><p>UX-2에서 연결된 실제 그룹입니다.</p></div></div>${groups.length?`<div class="space-list">${groups.map(groupCard).join('')}</div>`:empty('참여 중인 그룹이 없습니다.')}</section>${isHospitalUser()?'<div class="notice">상단의 공간 전환 버튼으로 병원 Context로 이동할 수 있습니다.</div>':''}`}
function enterpriseContent(){if(state.detail?.type==='enterpriseCampaign')return enterpriseCampaignDetail(state.detail.data);if(state.detail?.type==='enterpriseMatch')return enterpriseMatchDetail(state.detail.data);if(state.detail?.type==='group')return groupDetailView(state.detail.data);if(state.page==='home')return enterpriseHome();if(state.page==='enterprise')return enterpriseRoomPage();if(state.page==='campaign')return enterpriseCampaignsPage();if(state.page==='matching')return enterpriseMatchingPage();if(state.page==='partnership')return partnershipPage();if(state.page==='space')return enterpriseSpacePage();if(state.page==='account')return enterpriseAccountPage();if(state.page==='more')return `<div class="more-list"><button data-page="partnership"><span>◇</span><b>제휴·광고·스폰서</b><i>›</i></button><button data-page="account"><span>○</span><b>내 계정</b><i>›</i></button></div>`;return enterpriseHome()}
function selectedGuardianPet(){return state.guardian?.pets?.find(p=>p.id===state.selectedPet)||state.guardian?.pets?.[0]||null}
function petSelector(){const pets=state.guardian?.pets||[];return pets.length>1?`<label class="pet-switcher">현재 반려동물<select id="petSwitch">${pets.map(p=>`<option value="${esc(p.id)}" ${p.id===state.selectedPet?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>`:''}
function petSummaryCard(p){return `<button class="pet-card" data-pet="${esc(p.id)}"><span class="pet-avatar">${esc((p.name||'펫').slice(0,1))}</span><span><small>${esc(label(p.species)||'반려동물')}</small><b>${esc(p.name)}</b><em>${esc(p.breed||'품종 정보 없음')} · 건강체크 ${p.health_check_count||0}건</em></span>${p.is_primary?'<span class="now-badge">대표 반려동물</span>':''}<i>›</i></button>`}
function guardianHome(){const pet=selectedGuardianPet(),care=guardianCare(),latest=guardianLatestCheck(),programs=care?.programs||[],campaigns=state.guardian?.campaigns||[],hospitalNames=[...new Set(programs.map(p=>p.hospital_name).filter(Boolean))];return `${pageTitle('우리 아이 건강관리','선택한 반려동물의 건강과 연결 상태를 확인하세요.',petSelector())}${pet?`<section class="guardian-hero"><div><span class="eyebrow">현재 반려동물</span><h2>${esc(pet.name)}</h2><p>${esc(label(pet.species))} · ${esc(pet.breed||'품종 정보 없음')}</p></div><button class="light-button" data-pet="${esc(pet.id)}">우리 아이 정보 →</button></section><div class="guardian-status-grid"><article class="panel"><h2>최근 건강상태</h2><b>${esc(latest?.result?.summary||latest?.result?.grade||(latest?'결과 요약 미등록':'등록된 기록 없음'))}</b><p>${latest?fmt(latest.checked_at)+' · '+esc(label(latest.check_type)):'건강상태는 등록된 결과로만 표시합니다.'}</p><button class="secondary" data-page="health">시간순 건강기록</button></article><article class="panel"><h2>연결 동물병원</h2><b>${esc(hospitalNames.join(' · ')||'연결 프로그램 없음')}</b><p>프로그램에 등록된 병원입니다. 진료 관계 전체를 의미하지 않습니다.</p><button class="secondary" data-page="guardianHospital">병원·관리 연결</button></article></div><div class="metrics">${metric('건강기록',(pet.health_check_count||0)+'건','선택한 반려동물','health')}${metric('ReturnCare',(pet.active_program_count||0)+'개','진행 프로그램','guardianReturnCare')}${metric('다음 확인',pet.next_follow_up_at?fmt(pet.next_follow_up_at):'예정 없음','등록된 후속 일정','guardianReturnCare')}${guardianPageVisible('services')?metric('보험 연결',care?.insurance?.length?'기록 있음':'등록 없음','가입 여부는 보험사 확인','services'):metric('캠페인',campaigns.filter(guardianCampaignOpen).length+'개','보호자 개인 단위','campaign')}</div>${state.guardianCareError?'<div class="notice error">건강 상세를 불러오지 못했습니다. 다른 반려동물의 기록은 표시하지 않습니다. <button class="secondary" id="loadPetCare" data-id="'+esc(pet.id)+'">다시 불러오기</button></div>':''}`:`<section class="panel">${empty('등록된 반려동물이 없습니다.','우리 아이를 등록하면 건강관리를 시작할 수 있습니다.')}<button class="primary" data-page="pets">우리 아이 등록하기</button></section>`}${guardianHub()}<section class="panel section"><h2>오늘의 확인</h2><dl class="friendly-dl"><div><dt>최근 문의</dt><dd>문의 전송·내역 연결 준비 중</dd></div><div><dt>24시 건강체크</dt><dd>입력·접수 서비스 준비 중 · 기존 기록은 조회 가능</dd></div><div><dt>캠페인·혜택</dt><dd>${campaigns.filter(guardianCampaignOpen).length}개 모집 중 · 보호자 개인 단위</dd></div><div><dt>Reward</dt><dd>적립·포인트·내역 준비 중</dd></div><div><dt>생활서비스</dt><dd>사업자 연결 준비 중</dd></div></dl></section>`}
function petsPage(){const pets=state.guardian?.pets||[];return `${pageTitle('내 반려동물','반려동물을 등록하고 기본정보를 관리합니다.')}<div class="content-grid pet-layout"><section class="panel"><div class="section-head"><h2>등록된 반려동물</h2><span>${pets.length}마리</span></div>${pets.length?`<div class="pet-list">${pets.map(petSummaryCard).join('')}</div>`:empty('등록된 반려동물이 없습니다.')}</section><section class="panel form-panel"><div class="section-head"><h2>새 반려동물 등록</h2></div><form id="petForm"><label>이름<input id="petName" maxlength="80" required></label><label>종<select id="petSpecies"><option value="DOG">강아지</option><option value="CAT">고양이</option><option value="OTHER">기타</option></select></label><label>품종<input id="petBreed" maxlength="80"></label><label>성별<select id="petSex"><option value="">선택 안 함</option><option value="MALE">수컷</option><option value="FEMALE">암컷</option><option value="UNKNOWN">모름</option></select></label><label>생년월일<input id="petBirthDate" type="date"></label><button class="primary full-button" type="submit">반려동물 등록</button></form></section></div>`}
function petDetailPage(care){const p=care.pet;return `${pageTitle(p.name,'반려동물 기본정보와 건강관리 연결상태입니다.','<button class="secondary" data-page="pets">← 목록</button>')}<div class="content-grid"><section class="panel detail-panel"><span class="now-badge">내 반려동물</span><h2>${esc(p.name)}</h2><dl><div><dt>종</dt><dd>${esc(label(p.species))}</dd></div><div><dt>품종</dt><dd>${esc(p.breed||'정보 없음')}</dd></div><div><dt>성별</dt><dd>${esc(label(p.sex)||'정보 없음')}</dd></div><div><dt>생년월일</dt><dd>${p.birth_date?fmt(p.birth_date):'정보 없음'}</dd></div><div><dt>연결 병원</dt><dd>${esc(care.programs?.[0]?.hospital_name||'아직 연결된 동물병원이 없습니다.')}</dd></div></dl></section><section class="panel form-panel"><div class="section-head"><h2>기본정보 수정</h2></div><form id="petUpdateForm" data-id="${esc(p.id)}"><label>이름<input id="editPetName" maxlength="80" value="${esc(p.name)}" required></label><label>종<select id="editPetSpecies">${[["DOG","강아지"],["CAT","고양이"],["OTHER","기타"]].map(([v,t])=>`<option value="${v}" ${p.species===v?"selected":""}>${t}</option>`).join("")}</select></label><label>품종<input id="editPetBreed" maxlength="80" value="${esc(p.breed||'')}"></label><label>성별<select id="editPetSex">${[["","선택 안 함"],["MALE","수컷"],["FEMALE","암컷"],["UNKNOWN","모름"]].map(([v,t])=>`<option value="${v}" ${(p.sex||"")===v?"selected":""}>${t}</option>`).join("")}</select></label><label>생년월일<input id="editPetBirthDate" type="date" value="${esc(p.birth_date||'')}"></label><button class="primary" type="submit">변경사항 저장</button></form></section></div>`}
function healthPage(){const pet=selectedGuardianPet(),care=guardianCare();return `${pageTitle('시간순 건강기록',(pet?.name||'우리 아이')+'의 등록된 기록입니다.',petSelector())}${!pet?empty('먼저 반려동물을 등록해 주세요.'):!care?guardianCarePending():guardianTimeline(care)}<section class="panel section"><h2>집에서도 이어가는 건강관리</h2><p>새 건강체크 접수와 자동 병원 알림은 준비 중입니다.</p><button class="secondary" data-page="guardianCheck">24시 건강관리</button><button class="secondary" data-page="guardianReturnCare">ReturnCare</button></section>`}
function guardianCampaigns(){const all=state.guardian?.campaigns||[],rows=all.filter(c=>guardianUi.campaignFilter==='mine'?c.application_id||c.application_status:guardianUi.campaignFilter==='open'?guardianCampaignOpen(c):true);return `${pageTitle('보호자 캠페인','개인 신청과 참여 상태를 확인하세요.')}<div class="filter-row">${[['all','전체'],['open','모집 중'],['mine','내 신청']].map(([k,t])=>`<button class="filter ${guardianUi.campaignFilter===k?'active':''}" data-guardian-filter="${k}" aria-pressed="${guardianUi.campaignFilter===k}">${t}</button>`).join('')}</div><p class="guardian-note">최근 조회된 최대 30건입니다. 보호자 전용 대상 판정은 준비 중입니다. 등록된 대상·혜택·조건을 먼저 확인하세요.</p>${rows.length?`<div class="campaign-grid">${rows.map(c=>`<article class="campaign-card"><div class="campaign-top"><span>${esc(c.enterprise_name||'기업 정보 미등록')}</span>${badge(c.status)}</div><h3>${esc(c.name)}</h3><p>${esc(c.brief?.summary||c.brief?.description||'설명 미등록')}</p><div class="date-row">${fmt(c.starts_at)} — ${c.ends_at?fmt(c.ends_at):'종료일 미등록'}</div>${c.application_status?badge(c.application_status):''}${c.participation_status?badge(c.participation_status):''}<button class="secondary" data-guardian-detail="${esc(c.id)}">대상·혜택·진행 확인</button></article>`).join('')}</div>`:empty('조건에 맞는 캠페인이 없습니다.')}`}

function guardianServices(){if(!guardianPageVisible('services'))return guardianFeatureOff();const pet=selectedGuardianPet(),care=guardianCare();return `${pageTitle('내 펫보험','선택한 반려동물의 등록된 보험 연결 기록입니다.',petSelector())}<section class="panel"><h2>${esc(pet?.name||'우리 아이')}의 보험 상태</h2>${!pet?empty('먼저 반려동물을 등록해 주세요.'):!care?guardianCarePending():care.insurance?.length?care.insurance.map(x=>`<article class="info-card"><dl class="friendly-dl"><div><dt>상담 연결</dt><dd>${badge(x.status)}</dd></div><div><dt>가입 연결</dt><dd>${x.enrollment_status?badge(x.enrollment_status):'등록 없음'}</dd></div><div><dt>계약 연결</dt><dd>${x.policy_status?badge(x.policy_status):'등록 없음'}</dd></div><div><dt>등록된 기간</dt><dd>${fmt(x.starts_at)} — ${fmt(x.ends_at)}</dd></div></dl></article>`).join(''):empty('등록된 보험 연결 정보가 없습니다.','미가입 확정은 아닙니다. 가입 여부는 보험사에서 확인해 주세요.')}<p class="guardian-note">연결 상태만 조회합니다. 가입상품·보장·지급 확정은 보험사 안내로 확인하세요.</p></section>${guardianInsurancePage('guardianInsurance',true)}`}

function guardianSpace(){const pets=state.guardian?.pets||[],groups=state.mySpace?.groups||[];return `${pageTitle('내 공간','보호자·반려동물·그룹 공간을 한 계정에서 이동합니다.')}<section class="space-summary"><div><span class="eyebrow">보호자 공간</span><h2>${esc(state.me.profile?.display_name||'보호자')}</h2><p>반려동물을 중심으로 건강관리와 연결 서비스를 확인합니다.</p></div><div><strong>${pets.length}</strong><span>반려동물</span></div></section><section class="space-section"><div class="section-head"><h2>내 반려동물</h2></div><div class="pet-list">${pets.length?pets.map(petSummaryCard).join(''):empty('등록된 반려동물이 없습니다.')}</div></section><section class="space-section"><div class="section-head"><h2>참여 그룹</h2></div>${groups.length?`<div class="space-list">${groups.map(groupCard).join('')}</div>`:empty('참여 중인 그룹이 없습니다.')}</section>`}
function guardianAccount(){return `${pageTitle('내 계정','보호자 회원정보를 확인합니다.')}<section class="panel account-panel"><div class="avatar">${esc((state.me.profile?.display_name||'보').slice(0,1))}</div><h2>${esc(state.me.profile?.display_name||'보호자')}</h2><p>${esc(state.me.profile?.email||'')}</p><dl><div><dt>회원 상태</dt><dd>${badge(state.me.state)}</dd></div><div><dt>역할</dt><dd>보호자</dd></div><div><dt>등록 반려동물</dt><dd>${state.guardian?.pets?.length||0}마리</dd></div></dl><button class="danger-button" id="accountLogout">로그아웃</button></section>`}
function guardianContent(){if(state.detail?.type==='guardianCampaign')return guardianCampaignDetail(state.detail.data);if(['guardianCheck','guardianReturnCare','guardianInsurance','guardianClaims','guardianReward','guardianAssistant','guardianInquiry','guardianLife','guardianHospital','guardianNotifications'].includes(state.page))return guardianPreparedPage(state.page);if(state.detail?.type==='guardianPet')return petDetailPage(state.detail.data);if(state.detail?.type==='group')return groupDetailView(state.detail.data);if(state.page==='home')return guardianHome();if(state.page==='pets')return petsPage();if(state.page==='health')return healthPage();if(state.page==='campaign')return guardianCampaigns();if(state.page==='guardianBenefits')return guardianBenefitsPage();if(state.page==='guardianReferral')return guardianReferralPage();if(state.page==='services')return guardianServices();if(state.page==='space')return guardianSpace();if(state.page==='account')return guardianAccount();if(state.page==='more')return guardianMorePage();return guardianHome()}
const adminFilters={memberQuery:'',memberState:'',memberRole:'',organizationQuery:'',organizationState:'',organizationKind:''};
let adminApprovalResult=null;
const adminName=x=>String(x||'').replace(/\[(?:DEV|UX)[^\]]*\]\s*/gi,'').replace(/\b(?:DEV|UX[- ]?\d+(?:[- ]\d+)?|Manual Admin|Manual)\b/gi,'').replace(/^0[6-9][- ]\d+\s*/,'').trim()||'관리자';
const adminState=x=>({PENDING_APPROVAL:'전체 승인 대기',ACTIVE:'정상',PRE_MEMBER:'승인 대기',INVITED:'초대 대기',VERIFICATION_PENDING:'확인 필요',SUSPENDED:'이용 정지',WITHDRAWN:'거절·탈퇴',VERIFIED:'인증 완료',UNVERIFIED:'확인 필요',OPEN:'확인 필요',PENDING:'대기',FAILED:'처리 실패',RESOLVED:'처리 완료',RETRYING:'재처리 중',REVOKED:'권한 회수',ARCHIVED:'보관',APPROVED:'승인',SUBMITTED:'접수',ENDED:'종료'}[x]||'확인 필요');
function adminBadge(x){return `<span class="badge badge-${esc(String(x||'').toLowerCase())}">${esc(adminState(x))}</span>`}
function adminMetric(title,value,description,page){const html=metric(title,value==null?'집계 정보 없음':new Intl.NumberFormat('ko-KR').format(value),description,page);return page?html:html.replace('<button','<div').replace('</button>','</div>')}

function adminJumpMetric(title,value,description,page,filter=''){return adminMetric(title,value,description,page).replace(`data-page="${page}"`,`data-admin-target="${page}" data-admin-filter="${filter}"`)}
function adminFieldList(rows){return `<dl class="admin-key-values">${rows.map(([name,value])=>`<div><dt>${esc(name)}</dt><dd>${esc(value??'정보 제공되지 않음')}</dd></div>`).join('')}</dl>`}
function adminOrganizationDetail(x,kind){const ownRooms=(state.me?.rooms||[]).filter(r=>kind==='hospital'?r.hospital_id===x.id:kind==='enterprise'?r.enterprise_id===x.id:false);return adminFieldList([['이름',adminName(x.name)],['이용 상태',adminState(x.status)],['인증 상태',x.verification_status?adminState(x.verification_status):null],['소속·역할 관계',null],['내 계정에 연결된 공간',ownRooms.length?ownRooms.map(r=>adminName(r.name)).join(', '):'현재 계정의 연결 공간 없음']])+`<p class="admin-data-note">조직 전체의 구성원·공간 관계는 현재 조회 정보에 포함되지 않습니다.</p>`}
function adminVetDetail(p){return adminFieldList([['이름',adminName(p.display_name)],['회원 상태',adminState(p.state)],['인증 상태',p.verification_status?adminState(p.verification_status):null],['소속',(p.hospitals||[]).map(adminName).join(', ')||'소속 정보 없음'],['역할',(p.roles||[]).map(label).join(' · ')],['개인공간',p.vet_room_count==null?null:p.vet_room_count+'개'],['병원공간',p.hospital_room_count==null?null:p.hospital_room_count+'개']])}
function adminApprovalPanel(){const r=adminApprovalResult;if(!r||r.actorId!==state.me?.id)return '';const p=r.provisioning||{},connection=(id,created)=>!id?'연결 결과 정보 제공되지 않음':created===true?'새 공간 생성·연결 완료':created===false?'기존 공간 연결 완료':'공간 연결 완료';return `<section class="panel admin-approval-complete" aria-label="승인 완료 결과"><h2>승인 완료</h2><p>${esc(r.name)}님의 승인이 완료되었습니다.</p>${adminFieldList([['수의사 개인공간',connection(p.vetRoomId,p.vetRoomCreated)],...(p.hospitalRoomId?[['병원공간',(r.hospitalName?r.hospitalName+' · ':'')+connection(p.hospitalRoomId,p.hospitalRoomCreated)]]:r.hospitalSelected?[['병원공간','연결 결과 정보 제공되지 않음']]:[])])}<div class="admin-result-links">${r.hospitalName&&p.hospitalRoomId?`<button class="secondary" data-admin-target="organizations" data-admin-filter="hospital" data-admin-query="${esc(r.hospitalName)}">연결 병원 확인</button>`:''}<button class="secondary" data-page="space">내 공간으로 이동</button></div><p class="admin-data-note">내 공간은 현재 로그인한 관리자의 공간입니다. 승인 회원의 공간 접근 권한은 별도로 유지됩니다.</p></section>`}
function adminReadableRecord(value,depth=0){if(value==null)return '<p>상세 정보 없음</p>';if(depth>3)return '<p>추가 상세 기록 있음</p>';const safe=v=>String(v).replace(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi,'관련 기록').replace(/mabvxdcpmfdzrqlgkxqn|clgpzcjmchuingefjqfy/g,'관련 서비스');if(typeof value!=='object')return `<p>${esc(safe(value))}</p>`;if(Array.isArray(value))return value.map(v=>adminReadableRecord(v,depth+1)).join('');const names={issue:'확인 사항',message:'확인 내용',reason:'사유',expected:'기대 상태',actual:'현재 상태',status:'상태',state:'회원 상태',count:'건수',description:'설명',details:'세부 내용',entity_type:'대상 유형'};return Object.entries(value).filter(([k])=>!/(?:^id$|_id$|Id$|token|secret|key|project_ref)/i.test(k)).map(([k,v])=>`<div><b>${esc(names[k]||'추가 확인 정보')}</b>${adminReadableRecord(v,depth+1)}</div>`).join('')||'<p>관련 기록 확인 필요</p>'}
function bindAdminTargets(){document.querySelectorAll('[data-admin-target]').forEach(b=>b.onclick=()=>{const page=b.dataset.adminTarget,filter=b.dataset.adminFilter||'';if(page==='members'){adminFilters.memberQuery='';adminFilters.memberRole='';adminFilters.memberState=filter;}if(page==='organizations'){adminFilters.organizationKind=filter;adminFilters.organizationState='';adminFilters.organizationQuery=b.dataset.adminQuery||'';}state.page=page;state.detail=null;render()})}

function adminIssues(){const d=state.admin||{},seen=new Set();return [...(d.provisioningIssues||[]),...(d.consistencyIssues||[])].filter(x=>{const key=(x.entity_id||x.display_name)+':'+x.issue;if(seen.has(key))return false;seen.add(key);return true})}
function filteredAdminMembers(){const q=adminFilters.memberQuery.toLowerCase().trim();return (state.admin?.persons||[]).filter(p=>(!adminFilters.memberState||(adminFilters.memberState==='PENDING_APPROVAL'?['PRE_MEMBER','INVITED','VERIFICATION_PENDING'].includes(p.state):p.state===adminFilters.memberState))&&(!adminFilters.memberRole||(p.roles||[]).includes(adminFilters.memberRole))&&(!q||[adminName(p.display_name),p.email,...(p.hospitals||[]).map(adminName),...(p.roles||[]).map(label)].join(' ').toLowerCase().includes(q)))}
function adminOrganizationRows(){const d=state.admin||{},q=adminFilters.organizationQuery.toLowerCase().trim(),match=x=>(!q||adminName(x.name).toLowerCase().includes(q))&&(!adminFilters.organizationState||x.status===adminFilters.organizationState);return `<div class="content-grid">${!adminFilters.organizationKind||adminFilters.organizationKind==='hospital'?`<section class="panel"><div class="section-head"><h2>동물병원</h2><span>조회 ${(d.hospitals||[]).filter(match).length}곳</span></div>${(d.hospitals||[]).filter(match).map(x=>`<details class="admin-entity-detail"><summary><article class="admin-organization-card"><span class="admin-entity-symbol">병</span><div><h3>${esc(adminName(x.name))}</h3><p>병원 이용 상태 · ${adminState(x.status)}</p><small>인증 상태 · ${adminState(x.verification_status)}</small></div>${adminBadge(x.status)}</article></summary>${adminOrganizationDetail(x,(d.hospitals||[]).includes(x)?'hospital':'enterprise')}</details>`).join('')||empty('조건에 맞는 병원이 없습니다.')}</section>`:''}${!adminFilters.organizationKind||adminFilters.organizationKind==='enterprise'?`<section class="panel"><div class="section-head"><h2>기업</h2><span>조회 ${(d.enterprises||[]).filter(match).length}곳</span></div>${(d.enterprises||[]).filter(match).map(x=>`<details class="admin-entity-detail"><summary><article class="admin-organization-card"><span class="admin-entity-symbol">기</span><div><h3>${esc(adminName(x.name))}</h3><p>기업 이용 상태 · ${adminState(x.status)}</p><small>인증 상태 · ${adminState(x.verification_status)}</small></div>${adminBadge(x.status)}</article></summary>${adminOrganizationDetail(x,(d.hospitals||[]).includes(x)?'hospital':'enterprise')}</details>`).join('')||empty('조건에 맞는 기업이 없습니다.')}</section>`:''}</div>${!adminFilters.organizationKind||adminFilters.organizationKind==='vet'?`<section class="panel section"><div class="section-head"><h2>수의사·소속 현황</h2><span>최근 조회 회원 기준</span></div>${(d.persons||[]).filter(p=>(p.roles||[]).includes('VET')&&(!q||[adminName(p.display_name),...(p.hospitals||[]).map(adminName)].join(' ').toLowerCase().includes(q))&&(!adminFilters.organizationState||p.state===adminFilters.organizationState)).map(p=>`<details class="admin-entity-detail"><summary><div class="admin-directory-row"><div><b>${esc(adminName(p.display_name))}</b><small>${esc((p.hospitals||[]).map(adminName).join(', ')||'소속 정보 없음')} · 개인공간 ${p.vet_room_count??'미연결'}개</small></div>${adminBadge(p.state)}</div></summary>${adminVetDetail(p)}</details>`).join('')||empty('조건에 맞는 수의사가 없습니다.')}</section>`:''}`}
function bindAdminFilters(){const updateMembers=()=>{const rows=filteredAdminMembers();$('#adminMemberRows').innerHTML=rows.map(memberApprovalCard).join('')||empty('조건에 맞는 회원이 없습니다.','검색어나 필터를 변경해 주세요.');$('#adminMemberCount').textContent=rows.length+'명';document.querySelectorAll('[data-approve-member]').forEach(b=>b.onclick=()=>approveMember(b));document.querySelectorAll('[data-reject-member]').forEach(b=>b.onclick=()=>rejectMember(b.dataset.rejectMember));document.querySelectorAll('[data-suspend-member]').forEach(b=>b.onclick=()=>suspendMember(b.dataset.suspendMember))};$('#adminMemberSearch')?.addEventListener('input',e=>{adminFilters.memberQuery=e.target.value;updateMembers()});$('#adminMemberState')?.addEventListener('change',e=>{adminFilters.memberState=e.target.value;updateMembers()});$('#adminMemberRole')?.addEventListener('change',e=>{adminFilters.memberRole=e.target.value;updateMembers()});$('#adminOrganizationKind')?.addEventListener('change',e=>{adminFilters.organizationKind=e.target.value;updateOrganizations()});const updateOrganizations=()=>{$('#adminOrganizationRows').innerHTML=adminOrganizationRows()};$('#adminOrganizationSearch')?.addEventListener('input',e=>{adminFilters.organizationQuery=e.target.value;updateOrganizations()});$('#adminOrganizationState')?.addEventListener('change',e=>{adminFilters.organizationState=e.target.value;updateOrganizations()});}
function adminAuthView(){return `<div class="auth-wrap admin-auth"><div class="auth-card"><div class="logo-mark">D</div><div class="brand auth-brand">DoctorPet</div><span class="admin-login-eyebrow">운영 관리</span><h1>닥터펫 관리자 로그인</h1><p class="muted">관리자 계정으로 로그인해 주세요.</p>${state.sessionExpired?'<div class="notice error">로그인이 만료되었습니다. 다시 로그인해 주세요.</div>':''}<div id="msg" role="status" aria-live="polite"></div><form id="login"><label>이메일<input id="email" type="email" autocomplete="username" placeholder="관리자 이메일" required></label><label>비밀번호<input id="password" type="password" autocomplete="current-password" minlength="10" placeholder="비밀번호" required></label><button class="primary full-button" type="submit">로그인</button></form><p class="admin-login-help">관리자 권한이 부여된 계정으로만 운영 기능을 이용할 수 있습니다.</p><a class="admin-service-link" href="${esc(location.pathname)}">회원 서비스로 이동 →</a></div></div>`}
function sanitizeAdminCopy(root){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(!node.textContent.includes('@')&&/\bDEV\b|UX[- ]?\d|Manual Admin|^0[6-9][- ]\d/i.test(node.textContent))node.textContent=adminName(node.textContent)}}
function adminHome(){const d=state.admin||{},k=d.kpi||{},o=d.operationalKpi||{},rows=d.persons||[],pending=rows.filter(p=>['PRE_MEMBER','INVITED','VERIFICATION_PENDING'].includes(p.state)),issues=adminIssues(),roleCount=role=>rows.filter(p=>(p.roles||[]).includes(role)).length;return `${pageTitle('관리자 홈','회원 승인부터 서비스 운영까지, 오늘 확인할 업무를 한눈에 살펴보세요.','<button class="primary" data-admin-target="members" data-admin-filter="PENDING_APPROVAL">승인 대기 확인</button>')}<div class="admin-summary"><div><span class="eyebrow">오늘의 운영</span><h2>확인이 필요한 업무</h2><p>회원과 소속을 확인한 후 승인해 주세요. 승인이 완료되면 필요한 공간이 연결됩니다.</p></div><div class="admin-summary-count"><strong>${pending.length}</strong><span>조회 회원의 승인 대기</span></div></div><div class="metrics admin-metrics">${adminMetric('전체 회원',k.persons,'등록 회원 전체','members')}${adminJumpMetric('승인 대기',pending.length,'최근 조회 회원 기준','members','PENDING_APPROVAL')}${adminJumpMetric('동물병원',k.hospitals,'등록 병원 전체','organizations','hospital')}${adminJumpMetric('수의사',roleCount('VET'),'최근 조회 회원 기준','organizations','vet')}${adminJumpMetric('기업',o.enterprise_count,'등록 기업 전체','organizations','enterprise')}${adminMetric('보호자',o.guardian_count,'활성 보호자 프로필','members')}${adminMetric('수의대생',roleCount('STUDENT'),'최근 조회 회원 기준','members')}${adminMetric('활성 공간',o.active_room_count,'이용 중인 서비스 공간','space')}${adminMetric('활성 그룹',o.group_count,'운영 중인 그룹','space')}</div><p class="admin-data-note">역할별 회원 수와 승인 대기는 최근 조회된 최대 50명 기준입니다. 전체 회원 수와 조직·공간 집계는 연결된 전체 집계 값입니다. 미연결 항목은 숫자를 표시하지 않습니다.</p><div class="content-grid admin-home-grid"><section class="panel"><div class="section-head"><h2>캠페인 현황</h2><span>진행 상태</span></div><div class="admin-campaign-stats">${adminMetric('전체 캠페인',k.campaigns,'등록 캠페인')}${adminMetric('진행 중',o.active_campaign_count,'모집·진행 캠페인')}${adminMetric('완료',o.completed_campaign_count,'종료된 캠페인')}</div><dl class="admin-key-values"><div><dt>접수된 신청</dt><dd>${o.campaign_application_count??'미연결'}</dd></div><div><dt>참여 건수</dt><dd>${o.campaign_participation_count??'미연결'}</dd></div><div><dt>완료 참여</dt><dd>${o.campaign_completion_count??'미연결'}</dd></div></dl></section><section class="panel"><div class="section-head"><h2>운영 확인</h2><button class="text-button" data-page="operations">전체 보기 →</button></div><div class="admin-status-banner ${k.failed_jobs>0?'attention':''}"><span class="status-dot"></span><b>${k.failed_jobs==null?'운영 상태 미연결':k.failed_jobs>0?'처리 실패 확인 필요':'처리 실패 없음'}</b></div><dl class="admin-key-values"><div><dt><button class="text-button" data-admin-target="operations">처리 실패</button></dt><dd>${k.failed_jobs??'미연결'}건</dd></div><div><dt><button class="text-button" data-admin-target="operations">데이터 확인 필요</button></dt><dd>${k.reconciliation_open??'미연결'}건</dd></div><div><dt><button class="text-button" data-admin-target="operations">공간·계정 연결 검토</button></dt><dd>${issues.length}건</dd></div></dl></section></div><section class="panel section"><div class="section-head"><h2>최근 승인 대기</h2><button class="text-button" data-page="members">회원 승인으로 이동 →</button></div>${pending.length?`<div class="admin-pending-list">${pending.slice(0,4).map(p=>`<div><div class="small-avatar">${esc(adminName(p.display_name).slice(0,1))}</div><div><b>${esc(adminName(p.display_name))}</b><small>${esc((p.roles||[]).map(label).join(' · '))} · ${esc((p.hospitals||[]).map(adminName).join(', ')||'소속 확인 필요')}</small></div>${adminBadge(p.state)}</div>`).join('')}</div>`:empty('현재 조회된 승인 대기가 없습니다.','새로운 가입 요청이 접수되면 이곳에서 확인할 수 있습니다.')}</section>`}
function memberApprovalCard(p){const pending=['PRE_MEMBER','INVITED','VERIFICATION_PENDING'].includes(p.state),vet=(p.roles||[]).includes('VET');return `<article class="approval-card"><div class="approval-person"><div class="small-avatar">${esc(adminName(p.display_name).slice(0,1))}</div><div><h3>${esc(adminName(p.display_name))}</h3><p>${esc(p.email||'이메일 미등록')}</p></div>${adminBadge(p.state)}</div><div class="approval-facts"><span>역할 <b>${esc((p.roles||[]).map(label).join(' · ')||'확인 필요')}</b></span><span>병원·소속 <b>${esc((p.hospitals||[]).map(adminName).join(', ')||'소속 정보 없음')}</b></span><span>가입일 <b>${p.created_at?fmt(p.created_at):'정보 없음'}</b></span><span>연결 공간 <b>수의사 ${p.vet_room_count??'미연결'} · 병원 ${p.hospital_room_count??'미연결'}</b></span></div>${pending&&vet?`<div class="approval-controls"><label>승인 역할<select data-position><option value="VET">일반 수의사</option><option value="OWNER_VET">동물병원 원장</option></select></label><label>연결 병원<select data-hospital><option value="">병원 소속 없음</option>${(state.admin?.hospitals||[]).map(h=>`<option value="${esc(h.id)}">${esc(adminName(h.name))}</option>`).join('')}</select></label><button class="primary" data-approve-member="${esc(p.id)}">승인하고 공간 연결</button><button class="danger-button" data-reject-member="${esc(p.id)}">가입 거절</button></div>`:`<div class="approval-result"><span>${pending?'승인 경로 확인 필요':p.state==='ACTIVE'?'서비스 이용 중':adminState(p.state)}</span><span>${pending&&!vet?'해당 역할은 별도 승인 검토가 필요합니다.':''}</span>${pending?`<button class="danger-button" data-reject-member="${esc(p.id)}">가입 거절</button>`:p.state==='ACTIVE'?`<button class="danger-button" data-suspend-member="${esc(p.id)}">회원 정지</button>`:''}</div>`}</article>`}
function adminMembers(){const rows=filteredAdminMembers();return `${pageTitle('회원 승인','가입 요청과 소속을 확인하고 승인·거절·정지를 처리하세요.')}<div id="adminActionMessage" role="status" aria-live="polite"></div>${adminApprovalPanel()}<section class="admin-toolbar"><label class="admin-search"><span>회원 검색</span><input id="adminMemberSearch" type="search" placeholder="이름, 이메일, 소속 검색" value="${esc(adminFilters.memberQuery)}"></label><label><span>승인 상태</span><select id="adminMemberState"><option value="">모든 상태</option>${['PENDING_APPROVAL','PRE_MEMBER','INVITED','VERIFICATION_PENDING','ACTIVE','SUSPENDED','WITHDRAWN'].map(x=>`<option value="${x}" ${adminFilters.memberState===x?'selected':''}>${adminState(x)}</option>`).join('')}</select></label><label><span>역할</span><select id="adminMemberRole"><option value="">모든 역할</option>${['VET','STAFF','STUDENT','ENTERPRISE_USER','GUARDIAN','ADMIN'].map(x=>`<option value="${x}" ${adminFilters.memberRole===x?'selected':''}>${label(x)}</option>`).join('')}</select></label></section><div class="admin-list-meta"><b id="adminMemberCount">${rows.length}명</b><span>최근 조회 회원 최대 50명 · 가입일·기업 소속 상세는 정보가 있는 항목만 표시합니다</span></div><div class="approval-list" id="adminMemberRows">${rows.length?rows.map(memberApprovalCard).join(''):empty('조건에 맞는 회원이 없습니다.','검색어나 상태·역할 필터를 변경해 주세요.')}</div>`}
function adminOrganizations(){return `${pageTitle('병원·수의사·기업 관리','조직의 이용·인증 상태와 수의사 소속을 확인하세요.')}<section class="admin-toolbar"><label class="admin-search"><span>조직·수의사 검색</span><input id="adminOrganizationSearch" type="search" placeholder="병원명, 기업명, 수의사 이름 검색" value="${esc(adminFilters.organizationQuery)}"></label><label><span>대상</span><select id="adminOrganizationKind">${[['','전체'],['hospital','병원'],['vet','수의사'],['enterprise','기업']].map(([v,n])=>`<option value="${v}" ${adminFilters.organizationKind===v?'selected':''}>${n}</option>`).join('')}</select></label><label><span>이용 상태</span><select id="adminOrganizationState"><option value="">모든 상태</option>${['ACTIVE','SUSPENDED','ARCHIVED'].map(x=>`<option value="${x}" ${adminFilters.organizationState===x?'selected':''}>${adminState(x)}</option>`).join('')}</select></label></section><p class="admin-data-note">조직별 최근 최대 20곳을 조회합니다. 검색은 이 조회 범위에서 수행됩니다. 구성원별 최근 활동 정보는 제공되지 않습니다.</p><div id="adminOrganizationRows">${adminOrganizationRows()}</div>`}
function adminOperations(){const d=state.admin||{},k=d.kpi||{},issues=adminIssues();return `${pageTitle('운영 현황','확인할 업무와 처리 실패를 점검하세요.')}<div class="metrics admin-operation-metrics">${adminMetric('처리 실패',k.failed_jobs,'확인·재처리가 필요한 작업')}${adminMetric('데이터 확인 필요',k.reconciliation_open,'열린 검토 항목')}${adminMetric('공간·계정 검토',issues.length,'현재 조회된 연결 후보')}</div><div class="content-grid"><section class="panel"><div class="section-head"><h2>처리 실패</h2></div>${(d.failedJobs||[]).length?d.failedJobs.map(x=>`<article class="admin-operation-item"><div><b>${x.status==='RESOLVED'?'처리 완료':'재처리 필요'}</b><span>${x.failed_at?fmt(x.failed_at):'처리일 미연결'}</span></div><p>${x.status==='RESOLVED'?'확인된 작업입니다.':'작업 처리 결과를 확인한 후 운영 절차에 따라 재처리해 주세요.'}</p><details><summary>상세 기록</summary><dl><div><dt>작업 유형</dt><dd>${esc(x.job_type||'정보 없음')}</dd></div><div><dt>시도 횟수</dt><dd>${x.attempt_count??'정보 없음'}</dd></div><div><dt>오류 기록</dt><dd>${esc(x.error_code||'기록 없음')}</dd></div></dl></details></article>`).join(''):empty('처리 실패가 없습니다.','현재 조회된 작업에 확인할 실패 기록이 없습니다.')}</section><section class="panel"><div class="section-head"><h2>데이터 확인</h2></div>${(d.reconciliation||[]).length?d.reconciliation.map(x=>`<article class="admin-operation-item"><div><b>${adminState(x.status)}</b><span>${x.created_at?fmt(x.created_at):'접수일 미연결'}</span></div><p>기존 기록과 연결된 정보를 확인해 주세요.</p><details><summary>확인 내용</summary>${adminReadableRecord(x.discrepancy)}</details></article>`).join(''):empty('확인할 항목이 없습니다.')}</section></div>${adminIntegrationPanel()}`}
function adminContent(){if(state.page==='members')return adminMembers();if(state.page==='organizations')return adminOrganizations();if(state.page==='operations')return adminOperations();if(state.page==='account')return accountPage();return adminHome()}
function legacyTable(rows,cols){return !rows?.length?empty('표시할 데이터가 없습니다.'): `<div class="table-wrap"><table><thead><tr>${cols.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(x=>`<td>${esc(typeof r[x]==='object'?JSON.stringify(r[x]):r[x])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
async function legacyPage(kind){try{const d=kind==='admin'?await api('/admin/dashboard'):state.overview||await api('/overview');if(kind==='admin')return `<section class="hospital-hero"><div><h2>관리자 대시보드</h2><p>Scope가 확인된 ADMIN 전용</p></div></section><div class="metrics">${Object.entries(d.kpi).map(([k,v])=>metric(k,v,'')).join('')}</div><section class="panel">${legacyTable(d.persons,['display_name','email','status','state'])}${legacyTable(d.hospitals,['name','status','verification_status'])}${legacyTable(d.enterprises,['name','status','verification_status'])}${legacyTable(d.agreements,['agreement_type','status','signed_at'])}${legacyTable(d.acquisition,['source_type','source_key','channel','occurred_at'])}${legacyTable(d.reconciliation,['status','discrepancy','created_at'])}</section>`;if(kind==='campaign')return campaignsPage();if(kind==='support')return supportPage();if(kind==='matching')return matchingPage();return `${pageTitle(kind==='hospital'?'병원방':'기업방','허용된 Affiliation과 Room만 표시됩니다.')}<section class="panel">${legacyTable(state.me.affiliations,['name','organization_type','position_code','status'])}${legacyTable(state.me.rooms,['room_type','membership_role','status'])}</section>`}catch(x){return errorView(x)}}
function hospitalContent(){if(state.detail?.type==='room')return roomDetailView(state.detail.data);if(state.detail?.type==='spaceRoom')return spaceRoomDetail(state.detail.data);if(state.detail?.type==='group')return groupDetailView(state.detail.data);if(state.detail?.type==='slot')return slotDetail(state.detail.key);if(state.detail?.type==='campaign')return campaignDetail(state.detail.data);if(state.detail?.type==='support')return supportDetail(state.detail.data);if(state.detail?.type==='matching')return matchingDetail(state.detail.data);if(state.page==='home')return hospitalHome();if(state.page==='hospital')return hospitalPage();if(state.page==='campaign')return campaignsPage();if(['support','hospitalRequests'].includes(state.page))return supportPage();if(state.page==='hospitalNetwork')return hospitalNetworkPage();if(state.page==='hospitalBenefits')return hospitalBenefitsPage();if(['hospitalInsurance','hospitalCare','hospitalAssistant','hospitalTeam','hospitalOperations','hospitalFuture'].includes(state.page))return hospitalPreparedPage(state.page);if(state.page==='matching')return matchingPage();if(state.page==='space')return spacePageNow();if(state.page==='account')return accountPage();if(state.page==='more')return morePage();return hospitalHome()}
async function render(override){if(enterpriseEntryDenied){document.title='닥터펫 | 기업';const root=$('#app');root.innerHTML=enterpriseAuthView();$('#login').onsubmit=login;setMsg('인증된 기업 소속과 기업방 이용 권한이 있는 계정으로 로그인해 주세요.');return}if(studentEntryDenied){document.title='닥터펫 | 수의대생';const root=$('#app');root.innerHTML=studentAuthView();$('#login').onsubmit=login;setMsg('수의대생 개인공간 이용 권한이 있는 계정으로 로그인해 주세요.');return}if(guardianEntryDenied){const root=$('#app');root.innerHTML=guardianAuthView();$('#login').onsubmit=login;setMsg('보호자 서비스 이용 권한이 있는 계정으로 로그인해 주세요.');return}document.title=isStudentContext()||params.get('portal')==='student'&&!state.me?'닥터펫 | 수의대생':isGuardianContext()||params.get('portal')==='guardian'&&!state.me?'닥터펫 | 보호자 건강관리':isVetContext()||params.get('portal')==='vet'&&!state.me?'닥터펫 | 수의사 개인 서비스':isAdminContext()||(params.get('portal')==='admin'&&!state.me)?'닥터펫 | 운영 관리':contextKind()==='hospital'||params.get('portal')==='hospital'&&!state.me?'닥터펫 | 동물병원 서비스':originalDocumentTitle;const root=$('#app');if(vetEntryDenied){document.title='닥터펫 | 수의사 개인 서비스';root.innerHTML=vetAuthView();$('#login').onsubmit=login;setMsg('수의사 개인공간 이용 권한이 있는 계정으로 로그인해 주세요.');return}if(hospitalEntryDenied){document.title='닥터펫 | 동물병원 서비스';root.innerHTML=hospitalAuthView();$('#login').onsubmit=login;setMsg('동물병원 이용 권한이 있는 계정으로 로그인해 주세요.');return}if(!state.session){root.innerHTML=authView();$('#login').onsubmit=login;if($('#signup'))$('#signup').onsubmit=signup;return}if(state.busy){root.innerHTML=shell(loading());if(isAdminContext())sanitizeAdminCopy(root);if(contextKind()==='hospital')sanitizeHospitalCopy(root);if(isVetContext())sanitizeVetCopy(root);if(isGuardianContext())sanitizeGuardianCopy(root);if(isStudentContext())sanitizeStudentCopy(root);bindShell();return}if(override){root.innerHTML=shell(override);if(isAdminContext())sanitizeAdminCopy(root);if(contextKind()==='hospital')sanitizeHospitalCopy(root);if(isVetContext())sanitizeVetCopy(root);if(isGuardianContext())sanitizeGuardianCopy(root);if(isStudentContext())sanitizeStudentCopy(root);bindShell();return}if(!state.me){root.innerHTML=shell('<div class="state-panel"><strong>회원 연결을 확인하고 있습니다.</strong></div>');bindShell();return}if(state.me.state!=='ACTIVE'){root.innerHTML=shell(`<section class="panel activation"><h1>회원 승인이 필요합니다.</h1><p>관리자 승인이 완료되면 서비스를 이용할 수 있습니다.</p></section>`);bindShell();return}let content=state.page==='space'&&!state.detail?(isVetContext()?vetSpace():integratedSpace()):state.page==='account'?accountPage():isStudentContext()?studentContent():['vet','student','group','account'].includes(contextKind())?personalContent():isAdminContext()?adminContent():isGuardianContext()?guardianContent():isEnterpriseContext()?enterpriseConsoleContent():isHospitalUser()?hospitalContent():await legacyPage(state.page);if(state.page==='home'&&(!isGuardianContext()||['scores','levels','tiers','eligibility'].some(k=>state.scores?.[k]?.length))&&!isAdminContext()&&!isEnterpriseContext()&&!['vet','student','group','account'].includes(contextKind()))content+=storedScorePanel();root.innerHTML=shell(content);if(isAdminContext())sanitizeAdminCopy(root);if(contextKind()==='hospital')sanitizeHospitalCopy(root);if(isVetContext())sanitizeVetCopy(root);if(isGuardianContext())sanitizeGuardianCopy(root);if(isStudentContext())sanitizeStudentCopy(root);bindShell();bindPage()}
function bindShell(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;state.detail=null;render()});document.querySelector('[data-retry]')?.addEventListener('click',load);$('#contextSwitch')?.addEventListener('change',e=>switchContext(e.target.value));if(isGuardianContext())bindGuardianPreparedInputs()}
function bindPage(){if(isGuardianContext())bindGuardianUi();if(isVetContext())bindVetUi();if(isAdminContext()){bindAdminFilters();bindAdminTargets();}if(contextKind()==='hospital')bindHospitalUi();document.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>openRoom(b.dataset.room,'room'));document.querySelectorAll('[data-space-room]').forEach(b=>b.onclick=()=>openRoom(b.dataset.spaceRoom,'spaceRoom'));document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>{state.detail={type:'slot',key:b.dataset.slot};render()});document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>openGroup(b.dataset.group));document.querySelectorAll('[data-pet]').forEach(b=>b.onclick=()=>openGuardianPet(b.dataset.pet));document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>copyValue(b.dataset.copy,b));document.querySelectorAll('[data-campaign]').forEach(b=>b.onclick=()=>{state.detail={type:'campaign',data:state.overview.campaigns.find(x=>x.id===b.dataset.campaign)};render()});document.querySelectorAll('[data-guardian-campaign]').forEach(b=>b.onclick=()=>applyGuardianCampaign(b.dataset.guardianCampaign));document.querySelectorAll('[data-enterprise-campaign]').forEach(b=>b.onclick=()=>{state.detail={type:'enterpriseCampaign',data:state.enterprise.campaigns.find(x=>x.id===b.dataset.enterpriseCampaign)};render()});document.querySelectorAll('[data-enterprise-match]').forEach(b=>b.onclick=()=>{state.detail={type:'enterpriseMatch',data:state.enterprise.matching.find(x=>x.id===b.dataset.enterpriseMatch)};render()});document.querySelectorAll('[data-support]').forEach(b=>b.onclick=()=>{state.detail={type:'support',data:state.overview.support.find(x=>x.id===b.dataset.support)};render()});document.querySelectorAll('[data-matching]').forEach(b=>b.onclick=()=>{state.detail={type:'matching',data:state.overview.matching.find(x=>x.id===b.dataset.matching)};render()});document.querySelectorAll('[data-approve-member]').forEach(b=>b.onclick=()=>approveMember(b));document.querySelectorAll('[data-reject-member]').forEach(b=>b.onclick=()=>rejectMember(b.dataset.rejectMember));document.querySelectorAll('[data-suspend-member]').forEach(b=>b.onclick=()=>suspendMember(b.dataset.suspendMember));$('#petSwitch')?.addEventListener('change',e=>selectPet(e.target.value));$('#loadPetCare')?.addEventListener('click',e=>loadPetCare(e.currentTarget.dataset.id));$('#petForm')?.addEventListener('submit',createPet);$('#petUpdateForm')?.addEventListener('submit',updatePet);$('#groupForm')?.addEventListener('submit',createGroup);$('#createGroupInvite')?.addEventListener('click',createGroupInvite);$('#ensureReferral')?.addEventListener('click',ensureReferral);$('#acceptGroupInvite')?.addEventListener('click',acceptGroupInvite);$('#acceptReferral')?.addEventListener('click',acceptReferral);$('#applyCampaign')?.addEventListener('click',applyCampaign);$('#supportForm')?.addEventListener('submit',submitSupport);$('#adminScoreForm')?.addEventListener('submit',adminScoreRead);$('#enterpriseInquiry')?.addEventListener('submit',submitEnterpriseInquiry);$('#accountLogout')?.addEventListener('click',logout);document.querySelectorAll('[data-context]').forEach(b=>b.onclick=()=>switchContext(b.dataset.context));document.querySelectorAll('[data-group-action]').forEach(b=>b.onclick=()=>groupLifecycle(b.dataset.groupAction,b.dataset.id));}
async function openRoom(id,type){const generation=state.loadGeneration;state.busy=true;render();try{const data=await api('/rooms/'+id);if(generation!==state.loadGeneration)return;state.detail={type,data};state.busy=false;render()}catch(x){if(generation!==state.loadGeneration)return;state.busy=false;render(errorView(x))}}
async function openGroup(id){const generation=state.loadGeneration;state.busy=true;render();try{const data=await api('/groups/'+id);if(generation!==state.loadGeneration)return;state.detail={type:'group',data};state.busy=false;render()}catch(x){if(generation!==state.loadGeneration)return;state.busy=false;render(errorView(x))}}
async function copyValue(value,button){try{await navigator.clipboard.writeText(value);button.textContent='복사 완료'}catch{button.textContent='직접 선택해 복사해 주세요'}}
function selectPet(id){if(!state.guardian?.pets?.some(p=>p.id===id))return;guardianPetGeneration++;guardianInput={petId:id,inquiry:'',category:'health',check:{}};state.busy=false;state.selectedPet=id;state.guardianCare=null;state.guardianCareError=false;state.detail=null;sessionStorage.setItem('dp_pet',id);render();loadPetCare(id)}
async function refreshGuardian(){state.guardian=await api('/guardian/overview');if(state.guardian.pets?.length&&!state.guardian.pets.some(p=>p.id===state.selectedPet)){state.selectedPet=state.guardian.pets[0].id;sessionStorage.setItem('dp_pet',state.selectedPet)}}
async function loadPetCare(id){const generation=state.loadGeneration,petGeneration=++guardianPetGeneration;state.busy=true;render();try{const data=await api('/guardian/pets/'+id);if(generation!==state.loadGeneration||petGeneration!==guardianPetGeneration||!isGuardianContext())return;state.guardianCare=data.pet?.id===id?data:null;state.guardianCareError=false;state.busy=false;render()}catch(x){if(generation!==state.loadGeneration||petGeneration!==guardianPetGeneration||!isGuardianContext())return;state.busy=false;render(errorView(x))}}
async function openGuardianPet(id){const generation=state.loadGeneration,petGeneration=++guardianPetGeneration;state.busy=true;render();try{const data=await api('/guardian/pets/'+id);if(generation!==state.loadGeneration||petGeneration!==guardianPetGeneration||!isGuardianContext())return;state.selectedPet=id;sessionStorage.setItem('dp_pet',id);state.guardianCare=data;state.detail={type:'guardianPet',data};state.busy=false;render()}catch(x){if(generation!==state.loadGeneration||petGeneration!==guardianPetGeneration||!isGuardianContext())return;state.busy=false;render(errorView(x))}}
async function createPet(e){e.preventDefault();try{const result=await api('/commands',{method:'POST',idempotency:'create-pet:'+crypto.randomUUID(),body:{commandType:'CREATE_PET',payload:{name:$('#petName').value,species:$('#petSpecies').value,breed:$('#petBreed').value,sex:$('#petSex').value,birthDate:$('#petBirthDate').value}}});await refreshGuardian();state.selectedPet=result.resourceId;sessionStorage.setItem('dp_pet',result.resourceId);await openGuardianPet(result.resourceId)}catch(x){alert(x.message)}}
async function updatePet(e){e.preventDefault();const id=e.currentTarget.dataset.id;try{await api('/commands',{method:'POST',idempotency:'update-pet:'+crypto.randomUUID(),body:{commandType:'UPDATE_OWN_PET',payload:{petId:id,name:$('#editPetName').value,species:$('#editPetSpecies').value,breed:$('#editPetBreed').value,sex:$('#editPetSex').value,birthDate:$('#editPetBirthDate').value}}});await refreshGuardian();await openGuardianPet(id)}catch(x){alert(x.message)}}
async function applyGuardianCampaign(id){const c=state.guardian?.campaigns?.find(x=>x.id===id),room=currentRoom();if(!guardianCanApply(c)||guardianUi.applying)return;if(!confirm('등록된 참여 조건을 확인하셨습니까? 이 캠페인에 참여 신청합니다.'))return;guardianUi.applying=true;const generation=state.loadGeneration;try{await api('/commands',{method:'POST',idempotency:'guardian-apply:'+state.me.id+':'+room.id+':'+id,body:{commandType:'APPLY_CAMPAIGN',payload:{campaignId:id,roomId:room.id}}});if(generation!==state.loadGeneration||!isGuardianContext())return;await refreshGuardian();state.detail={type:'guardianCampaign',data:state.guardian.campaigns.find(x=>x.id===id)||c};render()}catch(x){alert(x.message)}finally{guardianUi.applying=false}}

async function createGroup(e){e.preventDefault();try{await api('/commands',{method:'POST',idempotency:'group:'+crypto.randomUUID(),body:{commandType:'CREATE_GROUP',payload:{name:$('#groupName').value,description:$('#groupDescription').value}}});await refreshMySpace()}catch(x){alert(x.message)}}
async function createGroupInvite(){const id=$('#createGroupInvite').dataset.id;try{const result=await api('/commands',{method:'POST',idempotency:'group-invite:'+crypto.randomUUID(),body:{commandType:'CREATE_GROUP_INVITATION',payload:{groupId:id}}});const box=$('#inviteResult');box.innerHTML=`<div class="copy-row"><input readonly value="${esc(result.inviteUrl)}" aria-label="그룹 초대 링크"><button class="secondary" data-copy="${esc(result.inviteUrl)}">복사</button></div><p class="muted">이 링크는 지금 한 번만 표시됩니다. 안전하게 공유해 주세요.</p>`;box.querySelector('[data-copy]').onclick=e=>copyValue(result.inviteUrl,e.currentTarget)}catch(x){alert(x.message)}}
async function ensureReferral(){try{await api('/commands',{method:'POST',idempotency:'referral-code:'+state.me.id,body:{commandType:'ENSURE_REFERRAL_CODE',payload:{}}});await refreshMySpace()}catch(x){alert(x.message)}}
async function acceptGroupInvite(){try{await api('/commands',{method:'POST',idempotency:'accept-group:'+state.me.id+':'+state.groupInvite.slice(0,12),body:{commandType:'ACCEPT_GROUP_INVITATION',payload:{invitationToken:state.groupInvite}}});sessionStorage.removeItem('dp_group_invite');state.groupInvite='';history.replaceState({},'',location.pathname);await load()}catch(x){alert(x.message)}}
async function acceptReferral(){try{await api('/commands',{method:'POST',idempotency:'accept-ref:'+state.me.id+':'+state.referral.slice(0,12),body:{commandType:'ACCEPT_REFERRAL',payload:{referralToken:state.referral}}});sessionStorage.removeItem('dp_referral');state.referral='';history.replaceState({},'',location.pathname);await load()}catch(x){alert(x.message)}}
async function applyCampaign(){const id=$('#applyCampaign').dataset.id;if(!confirm('이 캠페인에 신청하시겠습니까?'))return;const generation=state.loadGeneration;try{await api('/commands',{method:'POST',idempotency:'apply:'+state.me.id+':'+(currentRoom()?.id||'personal')+':'+id,body:{commandType:'APPLY_CAMPAIGN',payload:{campaignId:id,roomId:currentRoom()?.id,...(currentRoom()?.hospital_id?{hospitalId:currentRoom().hospital_id}:{})}}});if(generation!==state.loadGeneration)return;state.detail=null;await refreshOverview()}catch(x){alert(x.message)}}
async function submitSupport(e){e.preventDefault();const hospital=primaryHospital();if(!hospital)return;const generation=state.loadGeneration;try{const result=await api('/commands',{method:'POST',idempotency:'support:'+crypto.randomUUID(),body:{commandType:'CREATE_SUPPORT_REQUEST',payload:{hospitalId:hospital.hospital_id,title:$('#supportTitle').value,description:$('#supportDesc').value,requestType:$('#supportType').value}}});if(generation!==state.loadGeneration)return;const nextGeneration=state.loadGeneration+1;await refreshOverview();if(state.loadGeneration!==nextGeneration||currentRoom()?.hospital_id!==hospital.hospital_id)return;const data=state.overview?.support?.find(x=>x.id===result.resourceId);if(!data){state.detail=null;render();return}state.detail={type:'support',data};render()}catch(x){alert(x.message)}}
async function refreshAdmin(message=''){state.admin=await api('/admin/dashboard');render();if(message){const box=$('#adminActionMessage');if(box){box.className='notice success';box.textContent=message}}}
async function approveMember(button){const card=button.closest('.approval-card'),personId=button.dataset.approveMember,positionCode=card.querySelector('[data-position]').value,hospitalId=card.querySelector('[data-hospital]').value;if(positionCode==='OWNER_VET'&&!hospitalId){alert('원장 승인에는 연결 병원을 선택해 주세요.');return}button.disabled=true;try{const actorId=state.me?.id,generation=state.loadGeneration,member=(state.admin?.persons||[]).find(p=>p.id===personId),hospital=(state.admin?.hospitals||[]).find(h=>h.id===hospitalId);const result=await api('/commands',{method:'POST',idempotency:'approve-member:'+personId+':'+(hospitalId||'none')+':'+positionCode,body:{commandType:'APPROVE_MEMBER',payload:{personId,hospitalId:hospitalId||null,positionCode}}});if(generation!==state.loadGeneration||actorId!==state.me?.id)return;adminApprovalResult={actorId,name:adminName(member?.display_name),hospitalName:hospital?.name?adminName(hospital.name):null,hospitalSelected:!!hospitalId,provisioning:result.provisioning||{}};await refreshAdmin('승인과 공간 연결이 완료되었습니다.')}catch(x){button.disabled=false;alert(x.message)}}
async function rejectMember(personId){if(!confirm('이 회원가입 요청을 거절하시겠습니까?'))return;try{await api('/commands',{method:'POST',idempotency:'reject-member:'+personId,body:{commandType:'REJECT_MEMBER',payload:{personId,reason:'관리자 가입 검토 결과'}}});await refreshAdmin('회원가입 요청을 거절했습니다.')}catch(x){alert(x.message)}}
async function suspendMember(personId){if(!confirm('회원 접근을 정지하시겠습니까? 공간 데이터는 삭제되지 않습니다.'))return;try{await api('/commands',{method:'POST',idempotency:'suspend-member:'+personId,body:{commandType:'SUSPEND_MEMBER',payload:{personId,reason:'관리자 접근 정지'}}});await refreshAdmin('회원 접근을 정지했습니다.')}catch(x){alert(x.message)}}

// UX-6: Context is a navigation choice; server relationships remain authoritative.
function availableContexts(){
 const spaces=state.mySpace?.spaces||state.me?.rooms||[],seen=new Set();const contexts=[];
 for(const room of spaces){let kind={HOSPITAL_PRIVATE:'hospital',ENTERPRISE_PRIVATE:'enterprise',GUARDIAN_PRIVATE:'guardian',VET_PRIVATE:'vet',STUDENT_PRIVATE:'student',GROUP_ROOM:'group'}[room.room_type];if(!kind)continue;
 const key=!seen.has(kind)&&kind!=='group'?kind:room.id;seen.add(kind);
 const affiliation=state.me?.affiliations?.find(a=>a.hospital_id&&a.hospital_id===room.hospital_id||a.enterprise_id&&a.enterprise_id===room.enterprise_id);
 const name=['hospital','enterprise','group'].includes(kind)?room.name||affiliation?.name||friendlyRoom(room)[1]:friendlyRoom(room)[1];contexts.push({key,kind,name,room});}
 if(isAdminUser()&&state.me.adminDashboardAllowed!==false)contexts.push({key:'admin',kind:'admin',name:'관리자 공간',room:null});
 return contexts;
}
function currentRoom(){return availableContexts().find(c=>c.key===state.context)?.room||null}
function contextKind(){return availableContexts().find(c=>c.key===state.context)?.kind||'account'}
async function switchContext(key){guardianInput={petId:'',inquiry:'',category:'health',check:{}};state.context=key;state.page='home';state.detail=null;sessionStorage.setItem('dp_context',key);await load()}
function contextCard(c){const room=c.room,[icon]=friendlyRoom(room);return `<button class="space-card actual" data-context="${esc(c.key)}" ${c.kind==='hospital'?`data-room="${esc(room.id)}"`:c.kind==='group'?`data-group="${esc(room.group_id)}"`:`data-space-room="${esc(room.id)}"`}><span class="space-icon">${icon}</span><span class="space-copy"><small>${esc(label(room.membership_role))}</small><b>${esc(c.name)}</b><em>이용 가능</em></span><span class="now-badge">${state.context===c.key?'현재 공간':'이동'}</span><i>›</i></button>`}
function integratedSpace(){const contexts=availableContexts().filter(c=>c.room),groups=state.mySpace?.groups||[];const section=(title,kinds)=>`<section class="space-section"><div class="section-head"><h2>${title}</h2></div><div class="space-list">${contexts.filter(c=>kinds.includes(c.kind)).map(contextCard).join('')||empty('연결된 공간이 없습니다.')}</div></section>`;return `${pageTitle('내 공간','한 계정에 연결된 역할·소속·방을 이동합니다.')}${inviteContext()}${section('내 개인공간',['vet','guardian','student'])}<div class="space-list">${slotCard('assistant','AI')}</div>${section('내 병원',['hospital'])}${section('내 기업',['enterprise'])}${section('내 그룹',['group'])}<section class="space-section"><h2>내가 운영하는 공간</h2><p>${contexts.filter(c=>c.room.membership_role==='OWNER').length}개 공간</p><h2>내가 참여하는 공간</h2><p>${contexts.length}개 공간</p></section><section class="space-section"><h2>내 계정</h2><p>${esc(isAdminContext()?adminName(state.me?.profile?.display_name):state.me?.profile?.display_name||'회원')} · ${esc((state.me?.roles||[]).map(label).join(' · '))}</p><button class="secondary" data-page="account">프로필·역할·소속 확인</button></section>${!contexts.some(c=>c.kind==='group')&&groups.length?`<div class="space-list">${groups.map(groupCard).join('')}</div>`:''}<section class="space-section"><h2>그룹·소모임 만들기</h2><section class="panel form-panel group-form"><form id="groupForm"><label>그룹명<input id="groupName" maxlength="80" required></label><label>그룹 소개<textarea id="groupDescription" maxlength="500"></textarea></label><button class="primary">그룹 만들기</button></form></section></section><section class="space-section"><h2>초대·공유·추천</h2>${referralPanel()}</section>`}
function storedScorePanel(){const d=state.scores;return `<section class="panel score-panel"><h2>활동 점수·등급·자격</h2><p>평가가 기록되면 이 공간의 결과가 표시됩니다.</p>${['scores','levels','tiers','eligibility'].map(k=>(d?.[k]||[]).map(x=>`<div class="status-row"><b>${esc(x.name||x.code)}</b><span>${esc(x.score??(x.eligible===undefined?x.rank:x.eligible?'대상':'비대상'))}</span></div>`).join('')).join('')||empty('기록된 평가가 없습니다.')}<p class="muted">활동 평가와 서비스 접근 권한은 별도로 관리됩니다.</p></section>`}
function personalContent(){if(isVetContext())return vetContent();if(state.detail?.type==='slot')return slotDetail(state.detail.key);if(state.detail?.type==='group')return groupDetailView(state.detail.data);if(state.page==='campaign')return campaignsPage();if(state.page==='support')return empty('병원 Context에서 지원을 요청할 수 있습니다.');if(state.page==='more')return morePage();const room=currentRoom(),kind=contextKind();return `${kind==='group'&&state.group?groupDetailView(state.group):pageTitle(room?friendlyRoom(room)[1]:'내 계정','현재 공간의 정보와 연결 서비스를 확인하세요.')}<div class="quick-grid"><button data-page="space"><b>내 공간</b><span>다른 역할·소속으로 이동</span></button><button data-page="account"><b>내 계정</b><span>역할·소속·상태 확인</span></button></div>${storedScorePanel()}`}
async function groupLifecycle(type,groupId){const names={LEAVE_GROUP:'그룹 탈퇴',ARCHIVE_GROUP:'그룹 보관',TRANSFER_GROUP_OWNER:'그룹장 위임'};if(!confirm(names[type]+'을 진행하시겠습니까?'))return;const payload={groupId};if(type==='TRANSFER_GROUP_OWNER'){const personId=$('#nextGroupOwner')?.value;if(!personId){alert('위임할 구성원을 선택해 주세요.');return}payload.personId=personId}try{await api('/commands',{method:'POST',idempotency:'group-lifecycle:'+crypto.randomUUID(),body:{commandType:type,payload}});await load()}catch(x){alert(x.message)}}


function enterpriseInquiryForm(category){return `<section class="panel form-panel"><h2>기업 문의·제안 접수</h2><form id="enterpriseInquiry"><label>문의 종류<select id="inquiryCategory">${[['CAMPAIGN','캠페인'],['PARTNERSHIP','제휴'],['ADVERTISING','광고'],['SPONSORSHIP','스폰서십']].map(([k,v])=>`<option value="${k}" ${k===category?'selected':''}>${v}</option>`).join('')}</select></label><label>제목<input id="inquiryTitle" maxlength="120" required></label><label>내용<textarea id="inquiryDescription" maxlength="3000" required></textarea></label><button class="primary">접수하기</button><div id="inquiryResult" role="status"></div></form><h3>우리 기업 접수 내역</h3>${(state.enterprise?.inquiries||[]).map(x=>`<div class="status-row"><b>${esc(x.answers?.title||'문의')}</b>${badge(x.status)}<span>${fmt(x.submitted_at)}</span></div>`).join('')||empty('접수 내역이 없습니다.')}</section>`}
async function submitEnterpriseInquiry(e){e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;const context=state.context;const requestKey=e.currentTarget.dataset.idempotency||(e.currentTarget.dataset.idempotency='enterprise-inquiry:'+crypto.randomUUID());try{await api('/commands',{method:'POST',idempotency:requestKey,body:{commandType:'SUBMIT_ENTERPRISE_INQUIRY',payload:{enterpriseId:currentRoom()?.enterprise_id,category:$('#inquiryCategory').value,title:$('#inquiryTitle').value,description:$('#inquiryDescription').value}}});if(state.context!==context)return;await load();const box=$('#inquiryResult');if(box){box.className='notice success';box.textContent='접수되었습니다. 운영자가 검토합니다.'}}catch(x){button.disabled=false;alert(x.message)}}


function adminIntegrationPanel(){const d=state.admin||{},names={agreement_count:'서명 협약',unique_hospital_count:'협약 병원',unique_vet_count:'협약 수의사',pre_member_count:'사전회원',active_member_count:'활성 회원',referral_count:'확정 추천',campaign_application_count:'캠페인 신청',campaign_participation_count:'캠페인 참여',campaign_completion_count:'캠페인 완료',enterprise_count:'등록 기업',active_enterprise_count:'활성 기업',sponsorship_count:'스폰서십',active_campaign_count:'진행 캠페인',completed_campaign_count:'완료 캠페인',guardian_count:'활성 보호자 프로필',pet_count:'활성 반려동물',group_count:'활성 그룹',active_room_count:'활성 공간'};return `<section class="panel section"><div class="section-head"><h2>운영 지표</h2><span>연결된 집계 기준</span></div><p class="admin-data-note">운영 집계는 공개 네트워크 증빙 수치와 구분됩니다.</p><div class="metrics">${Object.entries(d.operationalKpi||{}).map(([k,v])=>adminMetric(names[k]||'운영 지표',v,'현재 연결된 집계')).join('')}</div></section><section class="panel section"><h2>공간·계정 연결 검토</h2>${adminIssues().map(x=>`<details class="admin-entity-detail"><summary><div class="admin-directory-row"><div><b>${esc(adminName(x.display_name))}</b><small>${esc(x.issue)}</small></div><span class="badge badge-verification_pending">확인 필요</span></div></summary>${adminFieldList([['대상',adminName(x.display_name)],['확인 사항',x.issue],['현재 상태',x.state?adminState(x.state):null],['대상 구분',x.entity_type?label(x.entity_type):null]])}</details>`).join('')||empty('검토할 연결 후보가 없습니다.')}<p class="admin-data-note">확인 결과에 따라 운영자가 처리합니다. 계정과 권한은 자동으로 변경되지 않습니다.</p></section><section class="panel section"><h2>기업 문의·제안</h2>${(d.inquiries||[]).map(x=>`<article class="admin-operation-item"><div><h3>${esc(adminName(x.answers?.title||'기업 문의'))}</h3>${adminBadge(x.status)}</div><p>${esc(adminName(x.enterprise_name))} · ${esc(adminName(x.actor_name))}</p><p>${esc(x.answers?.description||'문의 내용 없음')}</p></article>`).join('')||empty('접수된 문의가 없습니다.')}</section><section class="panel section form-panel"><h2>활동 평가 조회</h2><p class="admin-data-note">저장된 점수·등급·자격 판정 결과를 확인합니다. 조회 결과로 시스템 권한이 변경되지 않습니다.</p><form id="adminScoreForm"><label>조회 대상<select id="adminScoreSubject">${[['PERSON',d.persons||[]],['HOSPITAL',d.hospitals||[]],['ENTERPRISE',d.enterprises||[]]].flatMap(([type,rows])=>rows.map(x=>`<option value="${type}:${esc(x.id)}">${esc(adminName(x.display_name||x.name||'회원'))}</option>`)).join('')}</select></label><button class="secondary">평가 결과 조회</button></form><div id="adminScoreResult" role="status"></div></section>`}
async function adminScoreRead(e){e.preventDefault();const generation=state.loadGeneration;const [subjectType,subjectId]=$('#adminScoreSubject').value.split(':');try{const d=await api('/admin/scores?subjectType='+subjectType+'&subjectId='+subjectId);if(generation!==state.loadGeneration)return;$('#adminScoreResult').innerHTML=['scores','levels','tiers','eligibility'].flatMap(k=>(d[k]||[]).map(x=>`<p>${esc(x.name||x.code)} · ${esc(x.score??x.rank??(x.eligible?'대상':'비대상'))}</p>`)).join('')||'기록된 평가가 없습니다.'}catch(x){if(generation===state.loadGeneration)$('#adminScoreResult').textContent=x.status===403?'조회 권한이 없습니다.':x.message}}

// UX-7-3: personal veterinarian services reuse existing Runtime contracts.
const vetNav=[['home','홈','⌂'],['campaign','캠페인','▣'],['vetNetwork','네트워크','◎'],['space','내 공간','⌘'],['more','더보기','•••'],['vetAffiliations','소속 병원','▤'],['account','내 계정','○']];
const vetUi={campaignFilter:'all'};
function isVetContext(){return contextKind()==='vet'}
function vetAuthView(){return `<div class="auth-wrap admin-auth"><div class="auth-card"><div class="logo-mark">D</div><div class="brand auth-brand">DoctorPet</div><span class="admin-login-eyebrow">수의사 개인 서비스</span><h1>닥터펫 수의사 로그인</h1><p class="muted">개인 캠페인, 추천 네트워크와 소모임을 한곳에서 이용하세요.</p>${state.sessionExpired?'<div class="notice error">로그인이 만료되었습니다. 다시 로그인해 주세요.</div>':''}<div id="msg" role="status" aria-live="polite"></div><form id="login"><label>이메일<input id="email" type="email" autocomplete="username" required></label><label>비밀번호<input id="password" type="password" autocomplete="current-password" minlength="10" required></label><button class="primary full-button">로그인</button></form><p class="muted">수의사 역할과 개인공간 이용 권한이 있는 계정으로 로그인해 주세요.</p><a class="admin-service-link" href="${esc(location.pathname)}">다른 서비스로 이동 →</a></div></div>`}
function vetServiceCard(title,desc,page,ready=false){return `<article class="service-card ${ready?'slot':''}"><span class="${ready?'slot-badge':'now-badge'}">${ready?'준비 중':'이용 가능'}</span><h3>${esc(title)}</h3><p>${esc(desc)}</p><button class="secondary" data-page="${page}">${ready?'기능 안내':'확인하기'}</button></article>`}
function vetHome(){const me=state.me,active=(me.affiliations||[]).filter(a=>a.organization_type==='HOSPITAL'&&a.status==='ACTIVE'),apps=state.overview?.applications||[],campaigns=state.overview?.campaigns||[];return `${inviteContext()}${pageTitle('수의사방',(me.profile?.display_name||'수의사')+'님의 개인 활동과 네트워크를 위한 공간입니다.')}<section class="panel vet-profile"><span class="eyebrow">수의사 개인공간</span><h2>${esc(me.profile?.display_name||'수의사')}</h2><p>${esc((me.roles||[]).map(label).join(' · '))}</p><div class="vet-profile-status">${badge(me.state)}<span class="muted">수의사 자격 인증 조회 준비 중</span></div><p>${active.length?active.map(a=>esc(a.name||'병원명 미등록')).join(' · '):'연결된 활성 병원 소속이 없습니다.'}</p><button class="secondary" data-page="vetAffiliations">소속·병원공간 확인</button><p class="vet-data-note">병원 소속 인증과 수의사 자격 인증은 별도로 관리됩니다.</p></section><div class="vet-metrics"><button data-page="campaign"><strong>${campaigns.length}</strong><span>조회된 캠페인</span></button><button data-page="campaign" data-vet-campaign-filter="mine"><strong>${apps.length}</strong><span>내 개인 신청</span></button><button data-page="vetGroups"><strong>${state.mySpace?.groups?.length||0}</strong><span>내 소모임</span></button></div><p class="vet-data-note">캠페인은 최근 조회 최대 30건, 신청은 현재 수의사 개인공간 기준입니다.</p><section class="section"><h2>빠른 시작</h2><div class="quick-grid">${[['vetSupport','개인 지원·수요 요청','제품·교육·학술 지원 준비'],['vetMatching','기업 매칭','개인 수요 연결 준비'],['vetInsurance','펫보험·보험차트','권한 기반 진료 연결 준비'],['vetHub','수의 통합관','학술·교육·전문 서비스 허브'],['vetKnowledge','논문·증례','학술자료 연결 준비'],['vetNetwork','추천계보','개인 추천 연결 확인'],['vetAffiliations','소속 병원','활성 병원·공간 확인'],['campaign','개인 캠페인','개인 신청·참여 상태'],['vetBenefits','수의사 혜택','등록된 캠페인 혜택'],['vetKnowledge','수의학 정보','논문·증례 안내'],['vetEducation','교육·세미나','학술·교육 진입'],['vetAssistant','수의사 비서','임상·학술·커리어 지원 준비'],['vetNetwork','추천·네트워크','추천 관계·계보'],['vetGroups','소모임','그룹 생성·초대·참여'],['space','내 공간','개인·병원·그룹 전환']].map(([p,t,d])=>`<button data-page="${p}"><b>${t}</b><span>${d}</span></button>`).join('')}</div></section><section class="panel section"><h2>내 신청·참여 안내</h2>${apps.length?apps.slice(0,5).map(a=>`<div class="status-row"><b>${esc(campaigns.find(c=>c.id===a.campaign_id)?.name||'신청한 캠페인')}</b>${badge(a.status)}${a.participation_status?badge(a.participation_status):''}</div>`).join(''):empty('새 개인 신청·참여 기록이 없습니다.')}<button class="secondary" data-page="vetNotifications">알림·활동 안내</button></section><section class="section"><h2>수의사 개인 서비스</h2><div class="service-grid">${vetServiceCard('수의사 비서','진료·임상, 논문·증례, 약물·제품, 교육과 커리어를 지원할 개인 서비스입니다.','vetAssistant',true)}${vetServiceCard('수의학 정보 · 논문·증례','등록 자료 조회와 학술 관심 연결을 준비하고 있습니다.','vetKnowledge',true)}${vetServiceCard('교육·세미나','교육·학회 소식을 연결할 공간입니다.','vetEducation',true)}${vetServiceCard('수의사 혜택','현재 등록된 캠페인 안내를 확인하세요. 전용 혜택 제공은 준비 중입니다.','vetBenefits')}${vetServiceCard('수의사 네트워크','실제 추천 관계와 참여 중인 그룹을 확인하세요.','vetNetwork')}${vetServiceCard('소모임·공동수요','소모임과 그룹방을 이용하세요. 공동수요 자동화는 준비 중입니다.','vetGroups')}</div></section>${storedScorePanel()}`}
function vetCanApply(c){const room=currentRoom();return state.me?.state==='ACTIVE'&&state.me?.roles?.includes('VET')&&room?.room_type==='VET_PRIVATE'&&room.status==='ACTIVE'&&(state.me?.permissions||[]).includes('CAMPAIGN_APPLY')&&c.status==='OPEN'&&!applicationFor(c.id)&&(!c.starts_at||new Date(c.starts_at)<=new Date())&&(!c.ends_at||new Date(c.ends_at)>=new Date())}
function vetCampaignCard(c){const a=applicationFor(c.id);return `<article class="campaign-card"><div class="campaign-top"><span>${esc(c.enterprise_name||'기업 정보 미등록')}</span>${badge(c.status)}</div><h3>${esc(c.name||'캠페인명 미등록')}</h3><p>${esc(typeof c.brief==='object'?(c.brief?.summary||c.brief?.description||'상세 안내를 확인해 주세요.'):(c.brief||'상세 안내를 확인해 주세요.'))}</p><div class="date-row"><span>${fmt(c.starts_at)} 시작</span><span>${c.ends_at?fmt(c.ends_at)+' 종료':'종료일 미등록'}</span></div><div class="card-actions">${a?badge(a.participation_status||a.status):''}<button class="secondary" data-campaign="${esc(c.id)}">상세 보기</button></div></article>`}
function vetCampaignsPage(){const rows=(state.overview?.campaigns||[]).filter(c=>vetUi.campaignFilter==='all'||vetUi.campaignFilter==='open'&&c.status==='OPEN'||vetUi.campaignFilter==='mine'&&applicationFor(c.id));return `${pageTitle('수의사 개인 캠페인','개인공간에서 신청하며, 병원의 신청·참여 기록은 병원공간에서 확인합니다.')}<div class="filter-row">${[['all','전체'],['open','모집 중'],['mine','내 신청']].map(([k,v])=>`<button class="filter ${vetUi.campaignFilter===k?'active':''}" data-vet-campaign-filter="${k}" aria-pressed="${vetUi.campaignFilter===k}">${v}</button>`).join('')}</div><p class="vet-data-note">최근 조회된 최대 30건입니다. 수의사 전용 대상 목록은 준비 중이며, 각 캠페인에 등록된 참여 대상과 조건을 먼저 확인하세요.</p>${rows.length?`<div class="campaign-grid">${rows.map(vetCampaignCard).join('')}</div>`:empty('조건에 맞는 캠페인이 없습니다.')}`}
function vetCampaignDetail(c){const a=applicationFor(c.id),b=c.brief&&typeof c.brief==='object'?c.brief:{};return `${pageTitle('수의사 개인 캠페인 상세','개인 신청·참여·완료 기록을 확인하세요.','<button class="secondary" data-page="campaign">← 목록</button>')}<article class="panel detail-panel"><div class="campaign-top"><span>${esc(c.enterprise_name||'기업 정보 미등록')}</span>${badge(c.status)}</div><h2>${esc(c.name)}</h2><p class="lead">${esc(b.summary||b.description||typeof c.brief==='string'&&c.brief||'등록된 설명이 없습니다.')}</p><dl class="friendly-dl">${[['캠페인 유형',({VET:'수의사',HOSPITAL:'동물병원',GENERAL:'일반',EDUCATION:'교육'})[c.campaign_type]||'등록 유형 확인 필요'],['대상',b.target||'대상 정보 미등록'],['혜택',b.benefit||b.benefits||'혜택 정보 미등록'],['기간',fmt(c.starts_at)+' — '+(c.ends_at?fmt(c.ends_at):'종료일 미등록')],['신청 주체','나의 수의사 개인공간']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}<div><dt>신청 상태</dt><dd>${a?badge(a.status):'미신청'}</dd></div><div><dt>참여 상태</dt><dd>${a?.participation_status?badge(a.participation_status):'참여 기록 없음'}</dd></div><div><dt>완료일</dt><dd>${a?.completed_at?fmt(a.completed_at):'완료 기록 없음'}</dd></div></dl><div class="detail-action">${vetCanApply(c)?`<button class="primary" id="applyCampaign" data-id="${esc(c.id)}">개인 캠페인 신청하기</button>`:a?'<div class="notice success">개인 신청이 접수되었습니다. 표시된 진행 상태를 확인해 주세요.</div>':'<div class="notice">현재 신청할 수 없습니다. 모집 기간·수의사 개인공간·신청 권한을 확인해 주세요.</div>'}</div><p class="vet-data-note">참여 대상과 혜택의 최종 조건은 등록 안내를 따릅니다. 개인 캠페인 전용 대상 판정 연결은 준비 중입니다.</p></article>`}
function vetBenefitsPage(){const rows=(state.overview?.campaigns||[]).filter(c=>c.brief?.benefit||c.brief?.benefits);return `${pageTitle('수의사 혜택','현재 등록된 캠페인 혜택을 확인하세요.')}<div class="notice">수의사 전용 혜택 지급·수령·리워드 서비스는 준비 중입니다. 아래 안내는 혜택 확정이나 수령 기록을 의미하지 않습니다.</div>${rows.length?`<div class="campaign-grid">${rows.map(c=>`<article class="campaign-card"><h3>${esc(c.name)}</h3><p>${esc(c.brief.benefit||c.brief.benefits)}</p>${badge(c.status)}<button class="secondary" data-campaign="${esc(c.id)}">대상·조건 확인</button></article>`).join('')}</div>`:empty('등록된 캠페인 혜택 안내가 없습니다.')}<button class="secondary" data-page="campaign">개인 캠페인 보기</button>`}
function vetPreparedPage(page){const config={vetSupport:['개인 지원·수요 요청','병원 요청과 분리된 수의사 개인 수요 서비스입니다.',['제품·샘플','의약품·사료·영양','의료기기·장비 데모','교육·세미나','학술 지원','협찬·스폰서십','서비스','기타 수의사 수요'],'개인 요청 접수는 준비 중입니다. 병원 요청으로 대신 접수하거나 접수 완료를 표시하지 않습니다.'],vetMatching:['기업 매칭','수의사 개인 요청을 기업·서비스사와 연결할 공간입니다.',['개인 요청','닥터펫 수요 확인','기업·서비스사 연결','진행 상태','결과 확인'],'개인 요청·매칭 서비스는 준비 중입니다. 병원 매칭 기록을 표시하지 않습니다.'],vetInsurance:['펫보험·보험차트','권한이 확인된 보호자·반려동물·병원 진료를 연결할 서비스입니다.',['보호자 보험정보','반려동물·병원 진료','예상 보장·본인부담','치료·청구','지급·ReturnCare'],'보험차트는 준비 중입니다. 현재 보험정보 조회·보장 계산·청구를 제공하지 않습니다.'],vetHub:['수의 통합관','수의학·학술·교육·전문 서비스를 연결할 개인 서비스 허브입니다.',['수의학 정보','논문·증례','학술자료','교육·세미나','약물·제품 정보','전문분야 정보','수의사 네트워크','외부 전문 서비스'],'콘텐츠와 외부 전문 서비스 연결은 준비 중입니다. 등록되지 않은 자료를 실제 제공 콘텐츠로 표시하지 않습니다.'],vetAssistant:['수의사 비서','수의사 개인방 안에서 진료·학술·업무를 지원할 기능입니다.',['진료·임상 질문','수의학 정보','논문·증례','약물·제품 정보','교육·세미나','병원 업무','수의사 커리어','개인 메모·후속 업무'],'답변·상담과 개인 기억 연결은 준비 중입니다. 현재 질문을 전송하거나 답변을 생성하지 않습니다.'],vetKnowledge:['수의학 정보 · 논문·증례','학술 자료와 관심분야를 연결할 공간입니다.',['수의학 정보','논문','증례','학술 관심분야'],'자료 조회·검색·관심 저장은 준비 중입니다. 등록되지 않은 논문이나 증례를 제공하지 않습니다.'],vetEducation:['교육·세미나','교육과 학회 활동을 연결할 공간입니다.',['교육','세미나','학회','제품 교육'],'교육 일정·예약·참가 확인은 준비 중입니다. 현재 등록된 캠페인 안내는 캠페인에서 확인하세요.'],vetCareer:['수의사 업무·커리어','개인의 전문 활동과 커리어를 이어갈 공간입니다.',['업무','경력·전문분야','기업 협업','개인 프로필 수정'],'전문분야·관심·경력 저장과 채용·협업 매칭은 준비 중입니다.'],vetDemand:['공동수요·기업 제안','소모임의 수요를 기업 지원과 이어갈 후속 서비스입니다.',['공동수요','제품 체험 수요','기업 제안','협업 기회'],'공동수요 자동 집계와 기업 제안 생성은 준비 중입니다. 소모임 생성·초대·참여는 현재 이용할 수 있습니다.'],vetNotifications:['알림·활동 안내','개인 신청·참여 기록과 후속 알림을 연결할 공간입니다.',['개인 신청','참여·완료 상태','알림함','후속 안내'],'알림함·알림 발송은 준비 중입니다. 현재 신청·참여·완료 기록은 개인 캠페인에서 확인하세요.']}[page];return `${pageTitle(config[0],config[1],'<button class="secondary" data-page="home">← 수의사 홈</button>')}<section class="panel vet-ready"><span class="slot-badge">준비 중</span><h2>${esc(config[0])}</h2><div class="vet-category-grid">${config[2].map(x=>`<div><b>${esc(x)}</b><small>서비스 연결 준비 중</small></div>`).join('')}</div><div class="notice">${esc(config[3])}</div>${page==='vetEducation'||page==='vetNotifications'?'<button class="secondary" data-page="campaign">개인 캠페인·상태 보기</button>':page==='vetDemand'?'<button class="secondary" data-page="vetGroups">내 소모임 보기</button>':''}</section>`}
function vetNetworkPage(){return `${pageTitle('수의사 네트워크','개인의 추천 관계와 소모임을 함께 확인하세요.')}${inviteContext()}${referralPanel()}<section class="panel section"><h2>소모임으로 연결하기</h2><p>지역·동문·학회·전문분야 모임을 직접 만들거나 초대 링크로 참여하세요.</p><button class="primary" data-page="vetGroups">소모임·그룹방</button><p class="vet-data-note">전문분야별 수의사 검색·공개 디렉터리는 준비 중입니다. 현재 추천 관계와 참여 그룹만 표시합니다.</p></section>`}
function vetGroupCard(g){const context=availableContexts().find(c=>c.kind==='group'&&c.room.group_id===g.id);return context?groupCard(g).replace('data-group=',`data-context="${esc(context.key)}" data-group=`):`<article class="panel"><h3>${esc(g.name)}</h3><p>그룹방 연결을 확인해 주세요.</p></article>`}
function vetGroupsPage(){const groups=state.mySpace?.groups||[];return `${pageTitle('수의사 소모임','그룹과 그룹방에서 실제 구성원·초대·위임·탈퇴·보관을 관리합니다.')}<div class="space-list">${groups.map(vetGroupCard).join('')||empty('참여 중인 소모임이 없습니다.')}</div><section class="panel section form-panel"><h2>소모임 만들기</h2><p>모임 이름과 소개에 유형을 적어 주세요. 자동 분류·자동 가입은 제공하지 않습니다.</p><div class="vet-category-actions">${['지역','동문','학회','친목','전문분야','임상 관심분야'].map(k=>`<button class="secondary" data-vet-group-category="${k}">${k} 소모임</button>`).join('')}</div><form id="groupForm"><label>소모임 이름<input id="groupName" maxlength="80" required></label><label>모임 소개<textarea id="groupDescription" maxlength="500"></textarea></label><button class="primary">그룹 만들기</button></form><p class="vet-data-note">관심분야·지역별 자동 검색은 준비 중입니다. 초대 링크는 추천 링크와 별도로 생성·수락합니다.</p></section><section class="panel section"><h2>공동수요·기업 제안</h2><p>자동 집계·제안 서비스는 준비 중입니다.</p><button class="secondary" data-page="vetDemand">후속 서비스 안내</button></section>`}
function vetAffiliationsPage(){const rows=(state.me?.affiliations||[]).filter(a=>a.organization_type==='HOSPITAL');return `${pageTitle('소속 병원','개인의 병원 소속과 각 병원공간의 접근 상태입니다.')}<div class="vet-affiliations">${rows.map(a=>{const context=availableContexts().find(c=>c.kind==='hospital'&&c.room.hospital_id===a.hospital_id),allowed=a.status==='ACTIVE'&&a.verification_status==='VERIFIED'&&context;return `<article class="panel"><h2>${esc(a.name||'병원명 미등록')}</h2><p>${esc(label(a.position_code||'구성원'))}${a.is_primary?' · 대표 소속':''}</p><div class="vet-profile-status">${badge(a.status)}${badge(a.verification_status)}</div>${allowed?`<button class="secondary" data-context="${esc(context.key)}">이 병원공간으로 이동</button>`:'<p class="muted">현재 이 병원공간을 이용할 수 없습니다.</p>'}</article>`}).join('')||empty('연결된 병원 소속이 없습니다.')}<div class="notice">병원 소속은 수의사 개인 역할과 별개입니다. 한 병원의 소속이 종료되어도 다른 활성 병원·개인공간은 각 권한으로 이용합니다.</div></div>`}
function vetMorePage(){return `${pageTitle('더보기','수의사 개인 서비스와 계정 메뉴입니다.')}<div class="more-list">${[['vetSupport','개인 지원·수요 요청'],['vetMatching','기업 매칭'],['vetInsurance','펫보험·보험차트'],['vetHub','수의 통합관'],['vetNetwork','추천계보'],['vetBenefits','수의사 혜택'],['vetKnowledge','수의학 정보 · 논문·증례'],['vetEducation','교육·세미나'],['vetAssistant','수의사 비서'],['vetCareer','수의사 업무·커리어'],['vetNetwork','추천·네트워크'],['vetGroups','소모임·그룹방'],['vetDemand','공동수요·기업 제안'],['vetAffiliations','소속 병원'],['vetNotifications','알림·활동 안내'],['space','내 공간'],['account','내 계정']].map(([p,t])=>`<button data-page="${p}"><span>○</span><b>${t}</b><i>›</i></button>`).join('')}</div>`}
function vetSpace(){return integratedSpace().replace(slotCard('assistant','AI'),vetServiceCard('수의사 비서','수의사 개인공간 안의 기능입니다. 답변 서비스는 준비 중입니다.','vetAssistant',true))}
function vetContent(){if(state.detail?.type==='campaign')return vetCampaignDetail(state.detail.data);if(state.detail?.type==='group')return groupDetailView(state.detail.data);if(state.detail?.type==='slot')return vetPreparedPage('vetAssistant');if(state.page==='campaign')return vetCampaignsPage();if(state.page==='more')return vetMorePage();if(state.page==='vetBenefits')return vetBenefitsPage();if(state.page==='vetNetwork')return vetNetworkPage();if(state.page==='vetGroups')return vetGroupsPage();if(state.page==='vetAffiliations')return vetAffiliationsPage();if(['vetSupport','vetMatching','vetInsurance','vetHub','vetAssistant','vetKnowledge','vetEducation','vetCareer','vetDemand','vetNotifications'].includes(state.page))return vetPreparedPage(state.page);return vetHome()}
function bindVetUi(){document.querySelectorAll('[data-vet-campaign-filter]').forEach(b=>b.addEventListener('click',()=>{vetUi.campaignFilter=b.dataset.vetCampaignFilter;render()}));document.querySelectorAll('[data-vet-group-category]').forEach(b=>b.onclick=()=>{$('#groupName').value=b.dataset.vetGroupCategory+' 소모임';$('#groupDescription').value=b.dataset.vetGroupCategory+'에 관심 있는 수의사 모임입니다.';$('#groupName').focus()})}
function sanitizeVetCopy(root){const walk=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=walk.nextNode()){if(['SCRIPT','STYLE'].includes(n.parentElement?.tagName))continue;n.textContent=n.textContent.replace(/\[DEV[^\]]*\]/g,'').replace(/\bDEV\b|UX6|V1 UI SLOT/g,'').replace(/AI 비서방|내 비서방/g,'수의사 비서').replace(/HOSPITAL_PRIVATE|VET_PRIVATE|GROUP_ROOM/g,'참여 공간').replace(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi,'공간 정보');}}

function guardianAuthView(){return `<div class="auth-wrap"><div class="auth-card"><div class="logo-mark">D</div><div class="brand auth-brand">DoctorPet</div><h1>보호자 건강관리 로그인</h1><p>우리 아이의 건강기록·병원 연계·캠페인을 확인하세요.</p>${state.sessionExpired?'<div class="notice error">로그인이 만료되었습니다. 다시 로그인해 주세요.</div>':''}<div id="msg"></div><form id="login"><label>이메일<input id="email" type="email" autocomplete="username" required></label><label>비밀번호<input id="password" type="password" autocomplete="current-password" required></label><button class="primary full-button">로그인</button></form></div></div>`}
function guardianServiceCard(title,description,page,prepared=false){return `<article class="service-card ${prepared?'slot':''}"><span class="${prepared?'slot-badge':'now-badge'}">${prepared?'준비 중':'이용 가능'}</span><h3>${esc(title)}</h3><p>${esc(description)}</p><button class="secondary" data-page="${page}">${prepared?'준비 안내':'확인하기'}</button></article>`}
function guardianHub(){return `<section class="section"><h2>보호자 서비스</h2><div class="guardian-priority-grid">${[['우리 아이','등록·수정·여러 마리 전환','pets',false],['건강상태 / 문의','자유롭게 적어 보는 문의창 · 전송 준비 중','guardianInquiry',true],['24시 건강관리','집에서 확인하는 건강 항목과 건강기록','guardianCheck',true],['ReturnCare','프로그램·1주·4주 체크·후속 일정','guardianReturnCare',false],['보험','내 보험 연결 기록과 상담·청구 안내','services',false],['혜택 / Reward','실제 캠페인 신청과 리워드 준비 안내','guardianBenefits',false]].filter(x=>guardianPageVisible(x[2])).map(x=>guardianServiceCard(...x)).join('')}</div><div class="more-list"><button data-page="guardianReferral"><span>↗</span><b>친구·가족 추천</b><i>›</i></button>${guardianPageVisible('guardianLife')?'<button data-page="guardianLife"><span>◇</span><b>반려동물 생활서비스</b><i>›</i></button>':''}<button data-page="more"><span>○</span><b>전체 서비스·내 공간·계정</b><i>›</i></button></div></section>`}
function guardianCampaignOpen(c){const now=Date.now();return !!c&&c.status==='OPEN'&&(!c.starts_at||Date.parse(c.starts_at)<=now)&&(!c.ends_at||Date.parse(c.ends_at)>=now)}
function guardianCanApply(c){const r=currentRoom();return guardianCampaignOpen(c)&&!c.application_id&&!c.application_status&&isGuardianContext()&&state.me?.state==='ACTIVE'&&state.me.roles?.includes('GUARDIAN')&&state.me.permissions?.includes('CAMPAIGN_APPLY')&&r?.room_type==='GUARDIAN_PRIVATE'&&r.status==='ACTIVE'}
function guardianCampaignDetail(c){const b=c.brief&&typeof c.brief==='object'?c.brief:{};return `${pageTitle('보호자 캠페인 상세','등록된 조건과 개인 참여 상태입니다.','<button class="secondary" data-page="campaign">← 목록</button>')}<section class="panel detail-panel"><h2>${esc(c.name)}</h2>${badge(c.status)}<p>${esc(b.summary||b.description||'설명 미등록')}</p><dl class="friendly-dl">${[['대상',b.target||'대상 정보 미등록'],['혜택',b.benefit||b.benefits||'혜택 정보 미등록'],['기간',fmt(c.starts_at)+' — '+fmt(c.ends_at)],['신청 주체','나의 보호자 개인공간']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}<div><dt>신청 상태</dt><dd>${c.application_status?badge(c.application_status):'미신청'}</dd></div><div><dt>참여 상태</dt><dd>${c.participation_status?badge(c.participation_status):'참여 기록 없음'}</dd></div></dl>${guardianCanApply(c)?`<button class="primary" data-guardian-campaign="${esc(c.id)}">참여 신청</button>`:'<div class="notice">현재 신청할 수 없습니다. 신청 상태·모집 기간·이용 권한을 확인하세요.</div>'}<p class="guardian-note">보호자 전용 대상 판정과 반려동물별 신청 연결은 준비 중입니다. 등록된 대상·조건을 확인하세요.</p></section>`}
function guardianPreparedPage(page){if(!guardianPageVisible(page))return guardianFeatureOff();if(page==='guardianInquiry'||page==='guardianAssistant')return guardianInquiryPage();if(page==='guardianCheck')return guardianCheckPage();if(page==='guardianReturnCare')return guardianReturnCarePage();if(page==='guardianHospital')return guardianHospitalPage();if(page==='guardianInsurance'||page==='guardianClaims')return guardianInsurancePage(page);if(page==='guardianReward')return guardianRewardPage();if(page==='guardianLife')return guardianLifePage();return `${pageTitle('알림·활동 안내','등록된 후속 일정은 건강관리에서 확인하세요.')}<section class="panel"><span class="slot-badge">준비 중</span><h2>건강 확인·병원 안내</h2><p>알림함·자동 발송은 아직 연결되지 않았습니다.</p><button class="secondary" data-page="guardianReturnCare">등록된 후속 일정</button></section>`}
function guardianMorePage(){return `${pageTitle('더보기','보호자 서비스와 계정입니다.')}<div class="more-list">${[['pets','우리 아이'],['guardianInquiry','건강상태 / 문의'],['guardianCheck','24시 건강관리'],['health','시간순 건강기록'],['guardianReturnCare','ReturnCare'],['guardianHospital','연결 동물병원'],['services','내 펫보험'],['guardianInsurance','보험 비교·상담'],['guardianClaims','보험 청구'],['guardianBenefits','캠페인·혜택'],['guardianReward','Reward'],['guardianReferral','친구·가족 추천'],['guardianLife','반려동물 생활서비스'],['guardianNotifications','알림·활동 안내'],['space','내 공간·참여 그룹'],['account','내 계정']].filter(x=>guardianPageVisible(x[0])).map(([p,t])=>`<button data-page="${p}"><span>○</span><b>${t}</b><i>›</i></button>`).join('')}</div>`}
function bindGuardianUi(){document.querySelectorAll('[data-guardian-filter]').forEach(b=>b.onclick=()=>{guardianUi.campaignFilter=b.dataset.guardianFilter;render()});document.querySelectorAll('[data-guardian-detail]').forEach(b=>b.onclick=()=>{state.detail={type:'guardianCampaign',data:state.guardian.campaigns.find(c=>c.id===b.dataset.guardianDetail)};render()})}
function sanitizeGuardianCopy(root){const walk=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=walk.nextNode()){if(['SCRIPT','STYLE'].includes(n.parentElement?.tagName))continue;n.textContent=n.textContent.replace(/\[(?:DEV|UX)[^\]]*\]\s*/gi,'').replace(/\bDEV\b|UI SLOT|FUTURE/g,'준비 중').replace(/^0[6-9][- ]\d+\s*/,'').replace(/HOSPITAL_PRIVATE|VET_PRIVATE|GUARDIAN_PRIVATE|GROUP_ROOM|STUDENT_PRIVATE|ENTERPRISE_PRIVATE/g,'서비스 공간').replace(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi,'공간 정보');}}


// Guardian extension surfaces use the existing Domain IDs and read contracts.
// Exposure settings never grant permissions or enable external adapters.
const guardianFlagKeys=['guardian_ai_health_check','guardian_insurance','guardian_claim','guardian_reward','guardian_offerwall','guardian_pet_taxi','guardian_pet_hotel','guardian_grooming','guardian_funeral','guardian_marketplace'];
let guardianExposure=Object.fromEntries(guardianFlagKeys.map(k=>[k,false]));
let guardianInput={petId:'',inquiry:'',category:'health',check:{}};
const guardianHealthFields=[['appetite','식욕'],['water','음수'],['stool','배변'],['urine','배뇨'],['activity','활동성'],['pain','통증'],['gait','보행'],['joint','관절'],['skin','피부'],['eye','눈'],['oral','구강'],['wound','수술부위'],['medication','약 복용'],['other','기타 증상']];
async function loadGuardianExposure(){try{const r=await fetch(new URL('./guardian-features.json',location.href),{cache:'no-store'});if(!r.ok)throw new Error('Exposure config unavailable');const j=await r.json();guardianExposure=Object.fromEntries(guardianFlagKeys.map(k=>[k,j.flags?.[k]===true]));}catch{guardianExposure=Object.fromEntries(guardianFlagKeys.map(k=>[k,false]));}}
function guardianPageVisible(page){const flag={services:'guardian_insurance',guardianInsurance:'guardian_insurance',guardianClaims:'guardian_claim',guardianReward:'guardian_reward',guardianLife:'guardian_marketplace',guardianAssistant:'guardian_ai_health_check'}[page];return !flag||guardianExposure[flag]===true;}
function guardianFeatureOff(){return `${pageTitle('서비스 안내','현재 이용이 중지된 서비스입니다.')}<section class="panel"><p>우리 아이 정보와 건강기록은 계속 이용할 수 있습니다.</p><button class="secondary" data-page="home">보호자 홈</button></section>`;}
function guardianCare(){const pet=selectedGuardianPet();return pet&&state.guardianCare?.pet?.id===pet.id?state.guardianCare:null;}
function guardianLatestCheck(){return (guardianCare()?.checks||[]).slice().sort((a,b)=>Date.parse(b.checked_at||0)-Date.parse(a.checked_at||0))[0]||null;}
function guardianCarePending(){const pet=selectedGuardianPet();return `<section class="panel"><p>선택한 반려동물의 상세 기록이 아직 조회되지 않았습니다.</p>${pet?`<button class="secondary" id="loadPetCare" data-id="${esc(pet.id)}">기록 불러오기</button>`:''}</section>`;}
function guardianInputForPet(){const id=selectedGuardianPet()?.id||'';if(guardianInput.petId!==id)guardianInput={petId:id,inquiry:'',category:'health',check:{}};return guardianInput;}
function guardianPreparedNotice(){return '<div class="notice guardian-prepared-notice" role="status"><strong>미전송 · 입력 서비스 준비 중</strong><p>입력 내용과 선택한 파일은 서버에 저장되거나 병원에 전달되지 않습니다. 반려동물·공간 전환, 로그아웃, 새로고침 시 지워집니다.</p></div>';}
function guardianAttachmentField(id){return `<label>사진 건강체크 / 영상 선택 (업로드 준비 중)<input id="${id}" type="file" accept="image/*,video/*" multiple><small>기기에서 파일을 선택할 수 있습니다. 업로드·분석은 하지 않습니다.</small></label><p id="${id}Status" class="guardian-note" aria-live="polite">선택한 파일 없음</p>`;}
function guardianInquiryPage(){const pet=selectedGuardianPet(),input=guardianInputForPet(),hospitals=[...new Set((guardianCare()?.programs||[]).map(p=>p.hospital_name).filter(Boolean))];return `${pageTitle('건강상태 / 문의',(pet?.name||'우리 아이')+'의 건강·병원·보험·생활서비스 문의창입니다.',petSelector())}${!pet?empty('먼저 반려동물을 등록해 주세요.'): `<section class="panel guardian-composer"><h2>${esc(pet.name)}에게 어떤 일이 있나요?</h2><p class="guardian-note">프로그램 연결 병원: ${esc(hospitals.join(' · ')||'등록 없음')}</p>${guardianPreparedNotice()}<form id="guardianInquiryForm"><label>문의 종류<select id="guardianInquiryCategory">${[['health','건강상태·증상'],['hospital','병원 문의'],['insurance','보험 문의'],['life','생활서비스 문의']].map(([k,t])=>`<option value="${k}" ${input.category===k?'selected':''}>${t}</option>`).join('')}</select></label><label>자유롭게 입력하세요<textarea id="guardianInquiryText" maxlength="2000" rows="5" placeholder="오늘 밥을 안 먹어요 / 수술 부위가 부은 것 같아요 / 병원에 전달해 주세요">${esc(input.inquiry)}</textarea></label>${guardianAttachmentField('guardianInquiryFiles')}<button class="primary" type="submit" disabled>문의 전송 준비 중</button></form></section>`}<section class="panel section"><h2>병원 전달·상담 연결</h2><p>병원 전달과 문의 내역은 준비 중입니다. 현재 전달된 문의가 있는 것처럼 표시하지 않습니다.</p>${guardianExposure.guardian_ai_health_check?'<h3>AI 건강관리 도우미</h3><p>이전 건강기록·ReturnCare·보험 정보를 권한 범위 안에서 활용할 서비스를 준비합니다. 실제 AI 분석 결과는 제공하지 않습니다. 현재 AI 답변과 의료 판단은 제공하지 않습니다.</p>':''}</section>`;}
function guardianCheckPage(){const pet=selectedGuardianPet(),input=guardianInputForPet();return `${pageTitle('24시 건강관리',(pet?.name||'우리 아이')+'의 집에서의 상태를 확인해 보세요.',petSelector())}${!pet?empty('먼저 반려동물을 등록해 주세요.'): `<section class="panel form-panel"><h2>${esc(pet.name)}의 오늘 건강체크</h2>${guardianPreparedNotice()}<form id="guardianCheckForm"><div class="guardian-check-grid">${guardianHealthFields.map(([k,t])=>`<label>${t}<select data-guardian-check="${k}" aria-label="${t}">${[['','선택 안 함'],['usual','평소와 같음'],['changed','변화 있음'],['unknown','잘 모르겠음']].map(([v,n])=>`<option value="${v}" ${input.check[k]===v?'selected':''}>${n}</option>`).join('')}</select></label>`).join('')}</div><label>보호자 자유메모<textarea id="guardianHealthMemo" maxlength="2000" rows="4" placeholder="증상·복용 약·변화한 시간을 적어 보세요.">${esc(input.check.memo||'')}</textarea></label>${guardianAttachmentField('guardianHealthFiles')}<button class="primary" type="submit" disabled>건강체크 저장 준비 중</button></form></section>`}<section class="panel section"><h2>등록된 건강기록</h2><p>병원에서 등록한 건강체크·검사 결과는 지금 확인할 수 있습니다.</p><button class="secondary" data-page="health">시간순 건강기록</button><button class="secondary" data-page="guardianReturnCare">ReturnCare</button></section>`;}
function guardianTimeline(care){const rows=[];for(const p of care.programs||[])rows.push({date:p.enrolled_at,title:p.program_name||'프로그램 등록',body:p.hospital_name||'병원 정보 없음',status:p.status});for(const c of care.checks||[])rows.push({date:c.checked_at,title:label(c.check_type)+' 건강체크',body:c.result?.summary||c.result?.grade||c.hospital_name||'결과 요약 미등록',status:c.result_status||c.status});for(const m of care.measurements||[])rows.push({date:m.measured_at,title:guardianMeasurementLabel(m.measurement_type),body:m.numeric_value!=null?m.numeric_value+' '+(m.unit||''):guardianResultText(m.value),status:null});for(const f of care.followUps||[])rows.push({date:f.completed_at||f.due_at,title:f.completed_at?'후속 확인 완료':'후속 확인 예정',body:f.result?guardianResultText(f.result):'병원에서 등록한 건강관리 일정',status:f.status});rows.sort((a,b)=>Date.parse(b.date||0)-Date.parse(a.date||0));return `<section class="panel"><h2>건강 타임라인</h2><p class="guardian-note">${esc(care.pet.name)}의 등록된 시간순 기록입니다. 다른 반려동물 기록은 포함하지 않습니다.</p>${rows.length?`<div class="health-timeline">${rows.map((x,i)=>`<article><span>${i+1}</span><div><small>${fmt(x.date)}</small><b>${esc(x.title)}</b><p>${esc(x.body)}</p></div>${x.status?badge(x.status):''}</article>`).join('')}</div>`:empty('등록된 건강기록이 없습니다.','진료·처방·사진·영상·보험·재내원 기록 연결은 서비스 계약이 준비되는 대로 확장됩니다.')}</section>`;}
function guardianMeasurementLabel(type){return {ACTIVITY:'활동성',PAIN:'통증',GAIT:'보행',URINE:'소변 건강',WEIGHT:'체중'}[type]||type||'측정 기록';}
function guardianResultText(value){if(!value)return '결과 미등록';if(typeof value==='string')return value;return value.summary||value.note||value.grade||'상세 결과 안내 준비 중';}
function guardianComparison(care){const types=[...new Set((care.measurements||[]).map(m=>m.measurement_type))];const pairs=types.map(type=>{const rows=care.measurements.filter(m=>m.measurement_type===type).sort((a,b)=>Date.parse(a.measured_at)-Date.parse(b.measured_at));return {type,rows};}).filter(p=>p.rows.length>=2);return `<section class="panel section"><h2>이전 결과 비교</h2><p class="guardian-note">동일 측정 항목의 등록된 최초·최근 값입니다. 진단이나 개선 판정을 자동 생성하지 않습니다.</p>${pairs.length?`<div class="guardian-comparison"><table><thead><tr><th>항목</th><th>이전 기록</th><th>최근 기록</th></tr></thead><tbody>${pairs.map(({type,rows})=>{const a=rows[0],b=rows[rows.length-1],v=m=>m.numeric_value!=null?m.numeric_value+' '+(m.unit||''):guardianResultText(m.value);return `<tr><th>${esc(guardianMeasurementLabel(type))}</th><td>${fmt(a.measured_at)}<br>${esc(v(a))}</td><td>${fmt(b.measured_at)}<br>${esc(v(b))}</td></tr>`;}).join('')}</tbody></table></div>`:empty('비교할 동일 항목 기록이 아직 없습니다.','활동성·통증·보행·소변 등 실제 측정 기록이 2건 이상이면 비교합니다.')}</section>`;}
function guardianReturnCarePage(){const pet=selectedGuardianPet(),care=guardianCare();return `${pageTitle('ReturnCare',(pet?.name||'우리 아이')+'의 반복 건강관리와 재검 일정입니다.',petSelector())}${!pet?empty('먼저 반려동물을 등록해 주세요.'):!care?guardianCarePending(): `<section class="panel"><h2>진행 프로그램 / 등록 상태</h2>${care.programs?.length?care.programs.map(p=>`<article class="info-card"><h3>${esc(p.program_name)}</h3><p>${esc(p.hospital_name||'연결 병원 미등록')} · ${fmt(p.enrolled_at)} 시작</p>${badge(p.status)}</article>`).join(''):empty('등록된 ReturnCare 프로그램이 없습니다.')}<p class="guardian-note">현재 Pet에 연결된 프로그램을 조회합니다. 새 프로그램 신청은 준비 중입니다.</p></section><section class="panel section"><h2>1주 / 4주 · 소변 건강검사</h2><p>등록된 검사 유형과 결과만 표시합니다. 기록이 없으면 완료 상태를 만들지 않습니다.</p>${care.checks?.length?care.checks.map(c=>`<article class="info-card"><h3>${esc(label(c.check_type))}</h3><p>${fmt(c.checked_at)} · ${esc(c.result?.summary||c.result?.grade||'결과 요약 미등록')}</p>${badge(c.result_status||c.status)}</article>`).join(''):empty('등록된 검사·결과가 없습니다.')}</section>${guardianComparison(care)}<section class="panel section"><h2>재검 안내 / 재내원 상태</h2>${care.followUps?.length?care.followUps.map(f=>`<article class="info-card"><h3>${fmt(f.due_at)} 후속 확인</h3>${badge(f.status)}<p>${f.completed_at?'완료 기록: '+fmt(f.completed_at):'완료 기록 없음'}</p><p>${esc(guardianResultText(f.result))}</p></article>`).join(''):empty('등록된 후속 일정이 없습니다.')}<p class="guardian-note">후속 확인 완료와 실제 재내원은 별개입니다. 재내원 확정·예약·외과/재활 판정 연결은 준비 중입니다.</p></section>`}<section class="panel section"><h2>병원과 이어지는 건강관리</h2><p>진료 → 처방 → 집에서의 건강관리 → 건강체크 → 병원 확인 → 재검·재내원 흐름을 준비합니다. 자동 CRM과 병원 알림은 아직 연결되지 않았습니다.</p><button class="secondary" data-page="guardianCheck">24시 건강관리</button><button class="secondary" data-page="health">전체 건강기록</button></section>`;}
function guardianHospitalPage(){const care=guardianCare();return `${pageTitle('연결 동물병원','현재 반려동물의 프로그램에 등록된 병원입니다.',petSelector())}<section class="panel">${care?.programs?.length?care.programs.map(p=>`<article class="info-card"><h2>${esc(p.hospital_name||'병원 정보 미등록')}</h2><p>${esc(p.program_name)} · ${esc(label(p.status))}</p></article>`).join(''):empty('등록된 연결 프로그램이 없습니다.')}<p>보호자방과 병원방은 각각 독립된 공간입니다. 병원이 다른 병원의 보호자 기록을 볼 수 없도록 권한을 구분합니다.</p><p class="guardian-note">프로그램 병원 표시는 진료 관계 전체나 병원의 정보 열람 권한을 의미하지 않습니다. 병원 CRM 건강정보 조회·전달은 준비 중입니다.</p></section>`;}
function guardianInsurancePage(page,embedded=false){const claim=page==='guardianClaims',items=claim?['청구 접수','청구 진행상태','지급 결과','사진·영수증 접수']:['보험 비교','전문 상담','GA 연결','가입','가입상품 확인','보장내용','병원 보험차트','진료 예상비용','예상 보험보장금액','예상 본인부담금','만기·갱신','가입자 전용 Health / ReturnCare'];return `${embedded?'':pageTitle(claim?'보험 청구':'보험 비교·상담','서비스 연결을 준비하고 있습니다.',petSelector())}<section class="panel section"><span class="slot-badge">준비 중</span><h2>${claim?'청구 · 지급':'보험 안내'}</h2><div class="guardian-categories">${items.map(t=>`<div>${esc(t)}<small>미연동</small></div>`).join('')}</div><p>실제 GA·보험사 API가 아직 연결되지 않았습니다. 실제 보험료나 보장금액을 계산하지 않습니다. 본인부담금·지급 결과도 생성하지 않습니다.</p><p class="guardian-note">보험 상담·판매는 GA와 보험사 연결을 통해 준비합니다. 병원·수의사가 직접 판매하는 구조가 아닙니다.</p>${!claim&&guardianPageVisible('guardianClaims')?'<button class="secondary" data-page="guardianClaims">보험 청구 안내</button>':''}<button class="secondary" data-page="guardianReturnCare">ReturnCare</button></section>`;}
function guardianRewardPage(){return `${pageTitle('Reward','참여 혜택과 적립 서비스를 준비하고 있습니다.')}<section class="panel"><span class="slot-badge">준비 중</span><h2>참여 · 포인트 · 이용 내역</h2><div class="guardian-categories">${['출석','미션','설문','광고 참여','앱 설치','기업 Campaign','건강체크 완료','친구 추천','병원 추천','Sample / Coupon','우리 아이 배변패드 받기','Reward Point','Reward History'].filter(t=>guardianExposure.guardian_offerwall||!['광고 참여','앱 설치'].includes(t)).map(t=>`<div>${esc(t)}<small>미연동</small></div>`).join('')}</div><p>잔액·적립·사용 내역은 아직 연결되지 않았습니다. 표시할 실제 Reward 기록이 없습니다.</p><p class="guardian-note">보험 혜택은 임의로 연계하지 않습니다. 오퍼월 사업자 연결과 공통 Reward 서비스 확장은 준비 중입니다.</p><button class="secondary" data-page="campaign">실제 캠페인 확인</button><button class="secondary" data-page="guardianReferral">친구·가족 추천</button></section>`;}
function guardianBenefitsPage(){return `${pageTitle('캠페인·혜택','보호자 개인 단위 캠페인을 확인하세요.')}<section class="panel"><h2>혜택 둘러보기</h2><div class="guardian-categories">${['건강관리','무료검사','체험','샘플','Kit','Coupon','Event','Survey','Review','사료 / 영양제','의료기기','보험사 / 기업 Campaign'].map(t=>`<div>${t}</div>`).join('')}</div><p class="guardian-note">카테고리는 서비스 안내입니다. 현재 목록은 공통 캠페인이며 보호자 대상 판정·반려동물별 참여 연결은 준비 중입니다.</p><button class="primary" data-page="campaign">모집 중 캠페인·내 신청</button>${guardianPageVisible('guardianReward')?'<button class="secondary" data-page="guardianReward">Reward 준비 안내</button>':''}</section>`;}
function guardianReferralPage(){return `${pageTitle('친구·가족 추천','공통 추천코드와 추천 관계를 사용합니다.')}${inviteContext()}${referralPanel()}<section class="panel section"><h2>추천 혜택</h2><p>추천 관계는 실제 기록됩니다. 추천 Reward·가입 완료별 지급 연결은 준비 중입니다.</p></section>`;}
function guardianLifePage(){const categories=[['펫택시','guardian_pet_taxi'],['펫호텔','guardian_pet_hotel'],['펫미용','guardian_grooming'],['장례','guardian_funeral'],['펫시터',null],['훈련',null],['유치원',null],['사료',null],['영양제',null],['용품',null],['검사',null],['재활',null],['기타 생활서비스',null]];return `${pageTitle('반려동물 생활서비스','우리 아이 생활에 필요한 서비스를 모아 준비합니다.',petSelector())}<section class="panel"><span class="slot-badge">준비 중</span><div class="guardian-categories">${categories.filter(([,flag])=>!flag||guardianExposure[flag]).map(([t])=>`<div><b>${t}</b><small>사업자 미연동 · 예약 준비 중</small></div>`).join('')}</div><p>연결된 사업자가 없습니다. 실제 예약·가격·재고·결제는 제공하지 않습니다.</p><p class="guardian-note">사업자·제안·문의·예약·결제·정산은 공통 외부 서비스 연결을 통해 확장합니다.</p></section>`;}
function bindGuardianPreparedInputs(){const input=guardianInputForPet();$('#guardianInquiryForm')?.addEventListener('submit',e=>e.preventDefault());$('#guardianCheckForm')?.addEventListener('submit',e=>e.preventDefault());$('#guardianInquiryText')?.addEventListener('input',e=>input.inquiry=e.target.value);$('#guardianInquiryCategory')?.addEventListener('change',e=>input.category=e.target.value);$('#guardianHealthMemo')?.addEventListener('input',e=>input.check.memo=e.target.value);document.querySelectorAll('[data-guardian-check]').forEach(e=>e.addEventListener('change',()=>input.check[e.dataset.guardianCheck]=e.value));for(const id of ['guardianInquiryFiles','guardianHealthFiles'])$('#'+id)?.addEventListener('change',e=>{const status=$('#'+id+'Status');if(status)status.textContent=e.target.files.length+'개 파일 선택 · 업로드하지 않음';});}

// UX-7-5: Student surfaces reuse Person/Room/Group/Referral and Runtime v22.
const studentNav=[['home','홈','⌂'],['studentEducation','학습·교육','▣'],['studentCareer','커리어','◇'],['studentNetwork','네트워크','◎'],['space','내 공간','⌘'],['more','더보기','•••'],['studentProfile','학생 프로필','○'],['campaign','캠페인·혜택','♡'],['account','내 계정','○']];
const studentCareerLabels=['탐색중','실습 희망','인턴 희망','취업 준비','구직중','취업완료'];
function isStudentContext(){return contextKind()==='student'}
function studentHasOwnRoom(me=state.me,spaces=state.mySpace?.spaces||me?.rooms||[]){return me?.state==='ACTIVE'&&me.roles?.includes('STUDENT')&&spaces.some(r=>r.room_type==='STUDENT_PRIVATE'&&r.status==='ACTIVE'&&['OWNER','MEMBER'].includes(r.membership_role));}
function studentAuthView(){return `<div class="auth-wrap"><div class="auth-card"><div class="logo-mark">D</div><div class="brand auth-brand">DoctorPet</div><h1>닥터펫 수의대생 로그인</h1><p class="muted">학생 시절의 배움과 관계를 수의사 커리어로 이어가세요.</p>${state.sessionExpired?'<div class="notice error">로그인이 만료되었습니다. 다시 로그인해 주세요.</div>':''}<div id="msg"></div><form id="login"><label>이메일<input id="email" type="email" autocomplete="username" required></label><label>비밀번호<input id="password" type="password" autocomplete="current-password" minlength="10" required></label><button class="primary full-button" type="submit">로그인</button></form><p class="muted">본인에게 연결된 수의대생 개인공간만 이용할 수 있습니다.</p></div></div>`;}
function studentLink(page,title,body,prepared=false){return `<button class="panel student-entry" data-page="${page}"><span class="${prepared?'slot-badge':'now-badge'}">${prepared?'준비 중':'이용 가능'}</span><h3>${title}</h3><p>${body}</p><b>확인하기 →</b></button>`;}
function studentProfilePanel(){return `<section class="panel student-profile"><div class="section-head"><h2>학생 프로필</h2><span class="slot-badge">정보 연결 준비 중</span></div><dl class="friendly-dl">${['학교','학년','졸업예정연도','관심 진료분야','희망지역','커리어 상태'].map(t=>`<div><dt>${t}</dt><dd>등록 정보 미연결</dd></div>`).join('')}</dl><p class="muted">학교·학년·진로 정보 조회와 수정은 준비 중입니다. 학생 인증 완료를 의미하지 않습니다.</p></section>`;}
function studentHome(){return `${pageTitle('수의대생방','배움부터 실습과 커리어까지, 나의 시작을 함께합니다.')}<section class="panel student-hero"><span class="eyebrow">나의 수의사 생애주기</span><h2>${esc(state.me?.profile?.display_name||'회원')}님의 시작을 응원합니다</h2><p>학습 → 교육·세미나 → 네트워크 → 실습·인턴 → 취업</p><p>졸업 후에도 같은 계정으로 학생 시절의 그룹과 추천 관계를 이어갑니다. 수의사 전환 서비스는 준비 중입니다.</p><button class="secondary" data-page="studentLifecycle">졸업 후 연결 안내</button></section>${studentProfilePanel()}<section class="section"><div class="section-head"><h2>배움과 커리어</h2></div><div class="student-hub">${studentLink('studentEducation','학습·교육','전공·임상 기초·논문·케이스',true)}${studentLink('studentSeminars','세미나','학회·웨비나·임상교육·선배 수의사 교육',true)}${studentLink('studentCareer','실습·인턴·취업','실습 준비부터 취업까지',true)}${studentLink('studentPortfolio','포트폴리오·커리어 기록','교육과 활동 이력을 같은 계정으로',true)}</div></section><section class="section"><div class="section-head"><h2>관계와 참여</h2></div><div class="student-hub">${studentLink('studentNetwork','병원·수의사 네트워크','관심 병원·선배·멘토 연결 안내',true)}${studentLink('studentGroups','그룹','학교·학년·동아리·지역·관심분야 모임')}${studentLink('studentReferral','친구 초대·추천','내 추천코드·초대링크·실제 추천 관계')}${studentLink('studentBenefits','수의대생 혜택','현재 공통 캠페인과 준비 중 학생 프로그램')}</div></section><section class="section">${studentLink('studentAssistant','수의대생 비서','공부·실습·이력서·면접·진로 준비',true)}</section>`;}
function studentPrepared(title,desc,categories,note){return `${pageTitle(title,desc)}<section class="panel"><span class="slot-badge">준비 중</span><div class="student-categories">${categories.map(t=>`<div><b>${t}</b><small>서비스 연결 준비 중</small></div>`).join('')}</div><p>${note}</p>${empty('현재 연결된 서비스가 없습니다.','실제 등록된 자료와 서비스가 연결되면 확인할 수 있습니다.')}</section>`;}
function studentEducation(){return studentPrepared('학습·교육','학생 시절의 공부와 임상 기초를 이어갑니다.',['전공 공부','임상 기초','논문','케이스','임상교육','선배 수의사 교육'],'콘텐츠 목록·수강·수료 기록은 아직 연결되지 않았습니다. 등록되지 않은 교육이나 수료 정보를 표시하지 않습니다.')+`<section class="panel section"><button class="secondary" data-page="studentSeminars">세미나·학회 안내</button><button class="secondary" data-page="studentPortfolio">교육·활동 기록 안내</button></section>`;}
function studentSeminars(){return studentPrepared('세미나·학회','교육과 네트워크의 다음 기회를 준비합니다.',['학회','웨비나','임상교육','선배 수의사 교육','세미나'],'현재 연결된 일정·강사·교육비·신청 서비스가 없습니다. 자동 추천과 외부 학회 연동은 준비 중입니다.');}
function studentCareer(){return studentPrepared('실습·인턴·취업','나의 관심과 커리어 방향을 이어갑니다.',['관심 병원','실습 준비','인턴 준비','취업 준비','전문분야 탐색','이력서','면접'],'실습·인턴·채용 매칭, 병원 모집 공고, 커리어 추천은 준비 중입니다. 매칭 결과나 채용 확정을 생성하지 않습니다.')+`<section class="panel section"><h2>커리어 상태 안내</h2><div class="student-categories">${studentCareerLabels.map(t=>`<div>${t}</div>`).join('')}</div><p>향후 사용할 상태의 안내이며 현재 내 상태가 아닙니다. 상태 저장·수정 서비스는 준비 중입니다.</p><button class="secondary" data-page="studentNetwork">병원·수의사 연결 안내</button></section>`;}
function studentNetwork(){return studentPrepared('병원·수의사 네트워크','학생과 병원을 양방향으로 연결할 준비를 합니다.',['학생 → 관심 병원','학생 → 실습·인턴·취업','병원 → 실습생 모집','병원 → 인턴·신규 수의사 채용','멘토링','선배 수의사 추천'],'학교·학년·관심분야와 연락처를 병원·수의사·기업에 자동 공개하지 않습니다. 학생 탐색·멘토 추천·모집 기능은 준비 중입니다.')+`<div class="quick-grid section"><button data-page="studentGroups"><b>내 그룹</b><span>실제로 연결된 구성원과 모임</span></button><button data-page="studentReferral"><b>친구 초대·추천</b><span>공통 추천 관계 이어가기</span></button></div>`;}
function studentGroups(){const groups=state.mySpace?.groups||[];return `${pageTitle('학생 그룹','기존 그룹과 초대 기능을 사용합니다.')}<section class="panel"><h2>모임 분류 안내</h2><div class="student-categories">${['학교','학년','동아리','지역','관심 임상분야','졸업예정자'].map(t=>`<div>${t}</div>`).join('')}</div><p>현재 그룹명·소개로 모임의 목적을 표현합니다. 자동 학교 인증·분류·추천은 준비 중입니다.</p></section><section class="section"><h2>내 그룹</h2><div class="space-list">${groups.map(groupCard).join('')||empty('참여 중인 그룹이 없습니다.')}</div></section><section class="panel section form-panel"><h2>그룹 만들기</h2><form id="groupForm"><label>그룹명<input id="groupName" maxlength="80" required></label><label>그룹 소개<textarea id="groupDescription" maxlength="500"></textarea></label><button class="primary">그룹 만들기</button></form></section>`;}
function studentReferral(){return `${pageTitle('친구 초대·추천','학생 시절의 추천 관계를 같은 계정으로 이어갑니다.')}${inviteContext()}${referralPanel()}<section class="panel section"><p>추천코드와 귀속·계보는 공통 추천 기능을 사용합니다. 친구 가입과 추천 기록이 보상 지급을 의미하지 않습니다. 추천 Reward는 준비 중입니다.</p></section>`;}
function studentBenefits(){return `${pageTitle('수의대생 혜택','현재 연결된 공통 캠페인과 준비 중 학생 지원을 구분합니다.')}<section class="panel"><span class="now-badge">공통 캠페인 조회</span><p>현재 등록된 캠페인의 상세 대상과 참여 조건을 확인하세요. 학생 대상 자동 판정과 교육·장학 프로그램은 준비 중입니다.</p><button class="primary" data-page="campaign">공통 캠페인·내 신청</button></section><section class="panel section"><h2>학생 프로그램</h2><span class="slot-badge">준비 중</span><div class="student-categories">${['교육지원','세미나 후원','기업 제품 교육','샘플·제품 체험','장학·후원','도서·콘텐츠 지원','예비 수의사 프로그램'].map(t=>`<div>${t}</div>`).join('')}</div><p>실제 모집·지원금·샘플·수료·자격 정보를 만들지 않습니다.</p></section>`;}
function studentPortfolio(){return studentPrepared('포트폴리오·커리어 기록','학생 시절부터 수의사가 된 이후까지 같은 계정으로 이어갑니다.',['실습','인턴','세미나','교육','관심 진료과','프로젝트','활동','수료','자격'],'기록 저장·조회·증빙·수료 인증은 준비 중입니다. 개인 생애주기 이력으로 확장하며 특정 학생방이 종료되어도 이력의 계정 연결을 끊지 않는 방향을 유지합니다.')+`<section class="panel section"><button class="secondary" data-page="studentLifecycle">학생 → 수의사 연결 안내</button></section>`;}
function studentAssistant(){return `${pageTitle('수의대생 비서','공부와 커리어 준비를 돕는 개인 비서를 준비합니다.')}<section class="panel form-panel"><span class="slot-badge">준비 중</span><div class="student-categories">${['전공 공부','임상 기초','논문·케이스','약물·제품','실습 준비','인턴 준비','이력서','면접','진로','전공','세미나','교육'].map(t=>`<div>${t}</div>`).join('')}</div><label>문의 입력<textarea id="studentAssistantInput" disabled placeholder="비서 서비스 연결 준비 중"></textarea></label><button class="primary" disabled>비서 연결 준비 중</button><p>현재 답변·기록 저장·추천 서비스가 연결되지 않았습니다. 의료 답변이나 매칭·채용 결과를 생성하지 않습니다.</p></section>`;}
function studentLifecycle(){return `${pageTitle('학생 → 수의사','새 계정을 만들지 않고 나의 관계와 이력을 이어갑니다.')}<section class="panel"><span class="slot-badge">전환 서비스 준비 중</span><h2>같은 계정으로 이어지는 커리어</h2><ol><li>기존 계정과 학생 시절의 그룹·추천 관계 유지</li><li>졸업·면허 확인과 소속 확인</li><li>수의사 역할과 소속 추가</li><li>수의사 개인공간 연결</li></ol><p>학생 역할 삭제나 새 계정 생성이 기본 전제가 아닙니다. 실제 졸업전환·학생 인증·면허 인증 자동 처리는 준비 중입니다.</p><button class="secondary" data-page="space">현재 내 공간 확인</button></section>`;}
function studentCanApply(c,now=Date.now()){const a=applicationFor(c.id);return studentHasOwnRoom()&&state.me.permissions?.includes('CAMPAIGN_APPLY')&&c.status==='OPEN'&&!a&&(!c.starts_at||Number.isFinite(Date.parse(c.starts_at))&&Date.parse(c.starts_at)<=now)&&(!c.ends_at||Number.isFinite(Date.parse(c.ends_at))&&Date.parse(c.ends_at)>=now);}
function studentCampaignDetail(c){const a=applicationFor(c.id),b=c.brief&&typeof c.brief==='object'?c.brief:{};return `${pageTitle('캠페인 상세','등록된 참여 대상·조건을 확인하세요.','<button class="secondary" data-page="campaign">← 목록</button>')}<section class="panel"><h2>${esc(c.name)}</h2>${badge(c.status)}<p>${esc(typeof c.brief==='string'?c.brief:b.summary||b.description||'상세 설명 미등록')}</p><dl class="friendly-dl"><div><dt>대상</dt><dd>${esc(b.target||'대상 정보 미등록')}</dd></div><div><dt>기간</dt><dd>${fmt(c.starts_at)} — ${fmt(c.ends_at)}</dd></div><div><dt>신청 상태</dt><dd>${a?badge(a.status):'미신청'}</dd></div></dl><p>학생 대상 여부는 상세 참여 조건을 확인하세요. 자동 대상 판정·교육 수료·Reward는 준비 중입니다.</p>${studentCanApply(c)?`<button class="primary" id="applyCampaign" data-id="${esc(c.id)}">참여 조건 확인 후 신청</button>`:a?'<p>신청이 접수되었습니다.</p>':'<p>현재 신청할 수 없습니다.</p>'}</section>`;}
function studentContent(){if(state.page==='space'&&!state.detail)return spacePageNow();if(state.page==='account'&&!state.detail)return accountPage();if(state.detail?.type==='campaign')return studentCampaignDetail(state.detail.data);if(state.detail?.type==='group')return groupDetailView(state.detail.data);if(state.detail?.type==='spaceRoom'||state.detail?.type==='room')return `${pageTitle('내 수의대생 공간','본인에게 허용된 공간만 확인합니다.')}<section class="panel">${state.detail.data.status?badge(state.detail.data.status):''}<p>본인 개인공간 연결을 확인했습니다.</p><button class="secondary" data-page="space">내 공간으로</button></section>`;if(state.detail?.type==='slot')return studentAssistant();const pages={home:studentHome,studentProfile:()=>pageTitle('학생 프로필','개인정보를 다른 사용자에게 자동 공개하지 않습니다.')+studentProfilePanel(),studentEducation,studentSeminars,studentCareer,studentNetwork,studentGroups,studentReferral,studentBenefits,studentPortfolio,studentAssistant,studentLifecycle,more:studentMore};if(state.page==='campaign')return `${pageTitle('공통 캠페인·내 신청','학생 대상 여부는 상세 참여 조건을 확인하세요.')}<div class="campaign-grid">${(state.overview?.campaigns||[]).map(campaignCard).join('')||empty('등록된 캠페인이 없습니다.')}</div>`;return (pages[state.page]||studentHome)();}
function studentMore(){return `${pageTitle('수의대생 서비스','현재 연결된 기능과 준비 중 서비스를 구분합니다.')}<div class="student-hub">${[['studentProfile','학생 프로필',true],['studentEducation','학습·교육',true],['studentSeminars','세미나',true],['studentCareer','실습·인턴·취업',true],['studentNetwork','병원·수의사 네트워크',true],['studentGroups','그룹',false],['studentReferral','친구 초대·추천',false],['studentBenefits','수의대생 혜택',false],['studentPortfolio','포트폴리오·커리어 기록',true],['studentAssistant','수의대생 비서',true],['studentLifecycle','졸업 후 연결',true],['account','내 계정',false]].map(([p,t,f])=>studentLink(p,t,f?'서비스 연결 준비 중':'현재 연결된 기록 확인',f)).join('')}</div>`;}
function sanitizeStudentCopy(root){sanitizeGuardianCopy(root);}

const enterpriseConsoleNav=[['home','홈','⌂'],['campaign','캠페인','▣'],['matching','병원 매칭','⇄'],['enterpriseNetwork','네트워크','◇'],['space','내 공간','⌘'],['enterprise','기업·팀','▦'],['enterpriseProducts','제품·Demo','▧'],['enterpriseEducation','세미나·교육','▤'],['partnership','제휴·광고','◇'],['enterpriseReward','참여보상','♥'],['enterpriseReport','성과·증빙','▣'],['enterpriseContract','계약·거래','▦'],['enterpriseAssistant','기업 비서','✦'],['account','내 계정','○'],['more','더보기','•••']];
function enterpriseHasContext(){const r=currentRoom();return state.me?.state==='ACTIVE'&&state.me.roles?.includes('ENTERPRISE_USER')&&state.me.permissions?.includes('ROOM_READ')&&r?.room_type==='ENTERPRISE_PRIVATE'&&r.status==='ACTIVE'&&state.me.affiliations?.some(a=>a.enterprise_id===r.enterprise_id&&a.status==='ACTIVE'&&a.verification_status==='VERIFIED');}
function enterpriseAuthView(){return `<div class="auth-wrap admin-auth"><div class="auth-card"><div class="logo-mark">D</div><div class="brand auth-brand">DoctorPet</div><span class="admin-login-eyebrow">기업 네트워크 서비스</span><h1>닥터펫 기업 로그인</h1><p class="muted">우리 기업의 캠페인과 연결 업무를 확인하세요.</p><div id="msg" role="status"></div><form id="login"><label>이메일<input id="email" type="email" autocomplete="username" required></label><label>비밀번호<input id="password" type="password" autocomplete="current-password" minlength="10" required></label><button class="primary full-button">로그인</button></form><p class="admin-login-help">승인된 기업 소속과 기업방 참여 권한이 필요합니다.</p><a class="admin-service-link" href="${esc(location.pathname)}">다른 서비스로 이동 →</a></div></div>`;}
const enterpriseHubItems=[['campaign','캠페인·문의','등록된 캠페인과 신청 현황','NOW'],['matching','병원 매칭','운영자가 연결한 기업별 기록','NOW'],['enterpriseNetwork','네트워크 제안','병원·수의사·그룹·보호자·수의대생','PREPARED'],['enterpriseProducts','제품·샘플·Demo','제품 체험·Kit·설치·회수','PREPARED'],['enterpriseEducation','세미나·학회·교육','웨비나·제품교육·학생 프로그램','PREPARED'],['partnership','광고·스폰서십','상담 접수·등록된 프로그램','NOW'],['enterprisePlacement','Placement·Slot','노출 위치·기간·Category 입점','PREPARED'],['enterpriseReward','네트워크 참여보상','활동 기반 보상 예산·집행','PREPARED'],['enterpriseReport','성과·Proof·Report','증빙·성과·후속전환·재계약','PREPARED'],['enterpriseContract','계약·거래','견적·계약·주문·결제·정산','PREPARED'],['enterprise','기업·팀','기업 정보와 연결된 담당자','NOW'],['enterpriseAssistant','기업 AI 비서','기획·대상·보고서 보조','PREPARED']];
function enterpriseHub(){return `<div class="enterprise-console-hub">${enterpriseHubItems.map(([p,t,d,s])=>`<button class="service-card" data-page="${p}"><span class="${s==='NOW'?'now-badge':'slot-badge'}">${s==='NOW'?'등록 기록·문의':'준비 중'}</span><h3>${esc(t)}</h3><p>${esc(d)}</p></button>`).join('')}</div>`;}
function enterpriseConsoleHome(){const d=state.enterprise,e=d?.enterprise;if(!e||!enterpriseHasContext())return enterpriseMissing();return `${pageTitle('기업 네트워크 콘솔','우리 기업의 실제 기록과 닥터펫 접수 현황입니다.')}<section class="enterprise-hero"><div><span class="eyebrow">내 기업</span><h2>${esc(e.name)}</h2><p>${esc(state.me.profile?.display_name)} · ${esc(label(e.affiliation_verification))}</p></div><button class="light-button" data-page="enterprise">기업·담당자 확인 →</button></section><div class="metrics">${metric('진행 캠페인',d.campaigns.filter(c=>['OPEN','ACTIVE'].includes(c.status)).length+'건','조회된 등록 기록','campaign')}${metric('신청·참여 기록',d.applications.length+'건','조회된 신청 내역','campaign')}${metric('병원 매칭',d.matching.length+'건','우리 기업에 배정된 기록','matching')}${metric('문의·제안 접수',d.inquiries.length+'건','접수는 계약과 별개','enterpriseInquiry')}</div><div class="notice">닥터펫이 대상 선정과 연결을 운영합니다. 기업방 이용은 전체 네트워크의 열람권·제안권을 의미하지 않습니다.</div><section class="section"><div class="section-head"><h2>기업 서비스</h2></div>${enterpriseHub()}</section><section class="panel"><h2>최근 업무</h2>${d.inquiries.slice(0,3).map(i=>`<div class="status-row"><b>${esc(i.answers?.title||'등록 문의')}</b>${badge(i.status)}<span>${fmt(i.submitted_at)}</span></div>`).join('')||empty('현재 접수된 문의가 없습니다.','캠페인·제휴 상담을 접수하면 상태를 확인할 수 있습니다.')}<button class="secondary" data-page="enterpriseInquiry">문의·제안 접수</button></section>`;}
function enterprisePrepared(title,desc,items,tail=''){return `${pageTitle(title,desc)}<section class="panel enterprise-prepared"><span class="slot-badge">PREPARED · 준비 중</span><h2>서비스 연결 준비 중</h2><p>현재 신청·집행·승인·성과 처리 기능은 연결되지 않았습니다.</p><div class="chip-row">${items.map(i=>`<span class="badge">${esc(i)}</span>`).join('')}</div>${tail}<button class="secondary" disabled>서비스 연결 준비 중</button><button class="secondary" data-page="enterpriseInquiry">일반 문의 접수</button><p class="muted">일반 문의 접수는 해당 서비스 신청·승인·연결·계약 체결을 의미하지 않습니다.</p></section>`;}
function enterpriseNetwork(){return enterprisePrepared('네트워크 제안·열람권','닥터펫 검수와 상대측 수락을 거쳐 연결하는 구조입니다.',['동물병원','수의사','병원·수의사 그룹','수의대생·학생 그룹','보호자 Audience'],`<ol class="enterprise-flow"><li>기업 요청 → 닥터펫 접수·검수</li><li>조건·가격 협의 → 대상 선정</li><li>익명 Preview → Detail Unlock</li><li>Proposal 권한 → 상대측 수락</li><li>Connected → 실행·증빙·성과</li></ol><p>Preview, Detail Unlock, Proposal, Connected는 서로 다른 권한 단계입니다. 건별·기간별·캠페인별 Unlock을 처리하는 서비스는 준비 중이며, 실제 대상 목록이나 연락처를 제공하지 않습니다.</p>`);}
function enterpriseProducts(){return enterprisePrepared('제품·샘플·Demo','등록부터 사용·회수·후속 상담까지 연결할 서비스입니다.',['우리 제품·서비스','제품 체험','샘플 프로그램','의료기기 Demo','Kit','소모품','브로셔'],`<p>등록 → 대상 선택 → 신청·승인 → 배송·설치 → 수령·사용 → 회수·설문 → 결과 → 도입 상담</p><p>가격·재고·배송·사용 결과는 연결되지 않아 표시하지 않습니다.</p>`);}
function enterpriseEducation(){return enterprisePrepared('세미나·학회·교육','행사 운영과 참석·후속 관심자 기록 연결을 준비합니다.',['수의사 세미나','Lunch Seminar','병원 직원교육','제품교육','학회 후원','Webinar','Advisory Board','수의대생 교육','Future Vet Program']);}
function enterprisePlacement(){return enterprisePrepared('Placement·Slot·Category','기업은 신청하고 닥터펫이 가격·재고·승인·배치를 운영합니다.',['홈페이지','동물병원방','수의사방','보호자방','수의대생방','메뉴','Category','지역','진료분야','Audience','Banner','Placement','Slot'],`<p>Advertising · Sponsorship · Placement · Slot은 각각 별개입니다. 실제 상품 가격·재고·배치·노출 성과는 미연결입니다.</p>`);}
function enterpriseReward(){return enterprisePrepared('네트워크 참여보상','명확한 운영 활동과 성과를 기준으로 보상을 연결합니다.',['캠페인 운영','교육 참여','설문','샘플 관리','콘텐츠','그룹 운영','예산·집행'],`<p>기업 지출 → 닥터펫 매출 → 기여 측정 → 보상 규칙 → 보상 원장 → 지급·혜택·배송</p><p>보상 규칙과 원장은 별개입니다. 현금은 Payment, 제품은 Fulfillment, 혜택은 Benefit으로 연결합니다. 진료 의뢰·보험판매에 대한 무조건적 보상은 제공하지 않습니다.</p>`);}
function enterpriseReport(){return enterprisePrepared('성과·Proof·Report','등록 기록 외의 성과·증빙·후속 전환은 준비 중입니다.',['모집','신청','승인','참여','완료','배송','수령','사용','설문','사진·증빙','관심도','상담','도입','전환','재계약'],`<p>지급 ≠ 배송 ≠ 수령 ≠ 사용 ≠ 성과</p><p>조회된 캠페인 신청·참여 상태는 캠페인 메뉴에서 확인할 수 있습니다. ROI·전환율·재계약 후보·자동 Audience는 아직 계산하거나 제공하지 않습니다.</p>`);}
function enterpriseContract(){return enterprisePrepared('계약·주문·결제·정산','문의와 매칭은 계약 체결·결제 완료를 의미하지 않습니다.',['견적·조건','Contract','Order','Payment','Fulfillment','Settlement'],`<p>Application ≠ Order · Matching ≠ Contract · Contract ≠ Order · Order ≠ Payment · Payment ≠ Settlement</p>`);}
function enterpriseAssistant(){return enterprisePrepared('기업 AI 비서','실제 AI 서비스와 권한 있는 기업 Context 연결을 준비합니다.',['Campaign 기획','병원·수의사 Target','세미나 기획','Sponsor Package','KPI 설계','성과 요약','재캠페인','보고서 요약'],`<label>비서 요청<textarea id="enterpriseAssistantInput" disabled placeholder="AI 비서 연결 준비 중"></textarea></label><p>현재 AI 답변·추천·매칭 결과를 생성하지 않습니다.</p>`);}
function enterpriseConsoleCampaigns(){return `${pageTitle('기업 캠페인','등록된 우리 기업 캠페인과 신청·참여 상태입니다.')}<div class="notice">Target · Invited · Applied · Approved · Participated · Completed는 별개의 단계입니다. 대상 자동 선정·초대 집행은 준비 중입니다. 캠페인 문의 접수는 캠페인 생성이 아닙니다.</div>${enterpriseInquiryForm('CAMPAIGN')}<div class="campaign-grid">${state.enterprise.campaigns.map(enterpriseCampaignCard).join('')||empty('등록된 기업 캠페인이 없습니다.')}</div><section class="panel"><h2>확장 가능한 캠페인 대상</h2><p>동물병원 · 수의사 · 보호자 · 수의대생 · 그룹·소모임 · 교육·세미나 · 제품 체험·샘플·Demo</p><span class="slot-badge">Targeting 연결 준비 중</span></section>`;}
function enterpriseConsoleCampaignDetail(c){const apps=state.enterprise.applications.filter(a=>a.campaign_id===c.id),b=c.brief&&typeof c.brief==='object'?c.brief:{};return `${pageTitle('캠페인 상세','등록된 조건과 실제 신청 기록입니다.','<button class="secondary" data-page="campaign">← 목록</button>')}<section class="panel"><h2>${esc(c.name)}</h2>${badge(c.status)}<p>${esc(typeof c.brief==='string'?c.brief:b.summary||b.description||'설명 미등록')}</p><dl class="friendly-dl"><div><dt>대상</dt><dd>${esc(b.target||'대상 정보 미등록')}</dd></div><div><dt>기간</dt><dd>${fmt(c.starts_at)} — ${fmt(c.ends_at)}</dd></div></dl></section><section class="panel"><h2>신청·참여 현황</h2>${apps.map(a=>`<div class="status-row"><b>${esc(a.applicant_name||'참여 회원')}</b><span>신청 ${badge(a.status)}</span><span>참여 ${a.participation_status?badge(a.participation_status):'참여 기록 없음'}</span><span>${fmt(a.submitted_at)}</span></div>`).join('')||empty('신청 기록이 없습니다.')}</section>`;}
function enterpriseConnected(r){return ['CONNECTED','CONVERTED'].includes(r?.result_status)&&!!r.connected_at;}
function enterpriseConsoleMatching(){return `${pageTitle('병원 매칭','우리 기업에 배정된 기존 매칭 기록만 확인합니다.')}<div class="notice">Matching은 Contract·Payment와 별개입니다. 새 후보 생성·상대 수락·연락처 Unlock·제안 전달은 준비 중입니다.</div><div class="enterprise-flow-labels">Candidate → Suggested → Contacted → Accepted → Connected → Converted</div>${state.enterprise.matching.map(r=>`<button class="matching-card" data-enterprise-match="${esc(r.id)}"><span class="match-copy"><b>${esc(enterpriseConnected(r)?r.support_title||'등록 병원 요청':'배정된 요청 요약')}</b><small>${esc(enterpriseConnected(r)?r.hospital_name||'연결 병원':'대상 상세 연결 준비 중')} · ${esc(r.region_code||'지역 미등록')}</small></span>${hospitalWorkflowBadge(r.result_status||r.candidate_status||r.status,true)}</button>`).join('')||empty('배정된 매칭 기록이 없습니다.','전체 병원 요청을 검색하거나 열람하는 기능은 제공하지 않습니다.')}`;}
function enterpriseConsoleMatchDetail(r){return `${pageTitle('병원 매칭 상세','등록된 연결 상태를 확인합니다.','<button class="secondary" data-page="matching">← 목록</button>')}<section class="panel"><h2>${esc(enterpriseConnected(r)?r.support_title||'등록 병원 요청':'배정된 요청 요약')}</h2>${hospitalWorkflowBadge(r.result_status||r.candidate_status||r.status,true)}<dl class="friendly-dl"><div><dt>병원</dt><dd>${esc(enterpriseConnected(r)?r.hospital_name||'이름 미등록':'상세 연결 준비 중')}</dd></div><div><dt>유형</dt><dd>${esc(label(r.request_type))}</dd></div><div><dt>지역</dt><dd>${esc(r.region_code||'미등록')}</dd></div><div><dt>연결일</dt><dd>${r.connected_at?fmt(r.connected_at):'연결 기록 없음'}</dd></div></dl><p>현재 조회는 배정된 기존 기록입니다. 직접 제안·소통·계약·결제와 연락처 제공은 준비 중입니다.</p></section>`;}
function enterpriseConsolePartnership(){const d=state.enterprise;return `${pageTitle('광고·스폰서십','일반 상담 접수와 등록 기록을 확인합니다.')}<div class="notice">Advertising · Sponsorship · Placement · Slot은 서로 다릅니다. 상담 접수는 신청 승인·상품 구매·광고 집행이 아닙니다.</div>${enterpriseInquiryForm('PARTNERSHIP')}<section class="panel"><h2>등록된 광고</h2>${d.advertisements.map(a=>`<div class="status-row"><b>${esc(a.name)}</b>${badge(a.status)}<span>${fmt(a.starts_at)} — ${fmt(a.ends_at)}</span></div>`).join('')||empty('등록된 광고가 없습니다.')}</section><section class="panel"><h2>등록된 스폰서십</h2>${d.sponsorships.map(a=>`<div class="status-row"><b>${esc(a.name)}</b>${badge(a.status)}</div>`).join('')||empty('등록된 스폰서십이 없습니다.')}<p>등록 상태는 실제 집행·증빙·성과 완료를 의미하지 않습니다.</p></section><button class="secondary" data-page="enterprisePlacement">Placement·Slot·Category 준비 안내</button>`;}
function enterpriseConsoleTeam(){return enterpriseRoomPage()+`<section class="panel"><h2>담당자별 계정·권한</h2><p>기업과 담당자는 별개입니다. 기업 관리자·마케팅·영업·학술·제품·지역 담당자가 각자의 계정과 소속으로 연결될 수 있습니다.</p><span class="slot-badge">팀 초대·권한 관리 준비 중</span><p>표시된 구성원 목록은 팀 관리·기업 전체 권한을 부여하지 않습니다.</p><h3>기업 Category</h3><p>동물용 제약·바이오 · 사료·처방식·영양제 · 의료·진단·검사 · 보험·GA · 펫테크 · 제조·수입·유통·소모품 · 경영·법률·노무·세무·인테리어 · CRM/EMR·예약·결제 · 교육·학회 · 광고 · 펫택시·호텔·미용·장례·생활서비스</p><span class="slot-badge">다중 Category 조회·수정 연결 준비 중</span></section>`;}
function enterpriseConsoleContent(){if(!enterpriseHasContext()||!state.enterprise?.enterprise)return enterpriseMissing();if(state.detail?.type==='enterpriseCampaign')return enterpriseConsoleCampaignDetail(state.detail.data);if(state.detail?.type==='enterpriseMatch')return enterpriseConsoleMatchDetail(state.detail.data);if(state.detail?.type==='group')return groupDetailView(state.detail.data);const pages={home:enterpriseConsoleHome,enterprise:enterpriseConsoleTeam,campaign:enterpriseConsoleCampaigns,matching:enterpriseConsoleMatching,enterpriseNetwork,enterpriseProducts,enterpriseEducation,partnership:enterpriseConsolePartnership,enterprisePlacement,enterpriseReward,enterpriseReport,enterpriseContract,enterpriseAssistant,enterpriseInquiry:()=>pageTitle('기업 문의·제안','닥터펫 운영 검토를 위한 일반 접수입니다.')+enterpriseInquiryForm('PARTNERSHIP'),more:()=>pageTitle('기업 서비스','연결된 기록과 준비 중 서비스를 확인하세요.')+enterpriseHub()};return (pages[state.page]||enterpriseConsoleHome)();}

render();if(state.session)load();
